List<InvestmentPlan> _investmentPlansFromMaps(List<Map<String, dynamic>> maps) {
  final plans = maps.map((e) => InvestmentPlan.fromJson(e)).toList();
  for (final pl in plans) {
    pl.applyFixedRoi();
  }
  plans.sort((a, b) => a.price.compareTo(b.price));
  return plans;
}

List<Map<String, dynamic>> _investmentPlansToMaps(List<InvestmentPlan> plans) =>
    plans.map((e) => e.toJson()).toList();

Future<List<Map<String, dynamic>>> _fetchRemoteInvestmentPlans() async {
  try {
    final cfg = await Supabase.instance.client.from('config').select('investmentPlans').eq('id', 1).maybeSingle();
    if (cfg == null) return [];
    final raw = cfg['investmentPlans'];
    if (raw is! List) return [];
    return raw.map((e) => Map<String, dynamic>.from(e as Map)).toList();
  } catch (e) {
    debugPrint('[investmentPlans] fetch error: $e');
    return [];
  }
}

class InvestmentPlan {
  static const double fixedRoi = 0.0286; // 2.86% daily ROI for all plans
  static const int workDays = 261;

  String name;
  double price;
  double roi;

  InvestmentPlan({required this.name, required this.price, double? roi})
      : roi = fixedRoi;

  double get dailyIncome => price * fixedRoi;
  double get totalReturn => dailyIncome * workDays;

  void applyFixedRoi() => roi = fixedRoi;

  Map<String, dynamic> toJson() => {'name': name, 'price': price, 'roi': fixedRoi};
  factory InvestmentPlan.fromJson(Map<String, dynamic> json) => InvestmentPlan(
        name: (json['name'] ?? '').toString(),
        price: (json['price'] ?? 0.0).toDouble(),
      );
}

class MediaPost {
  final String id;
  final String userEmail;
  final String username;
  final String videoUrl;
  final String contentType; // video | image
  final String caption;
  final DateTime timestamp;
  int likes;
  List<String> likedBy;
  List<String> savedBy;
  List<Map<String, dynamic>> comments;
  List<String> taggedUsers;
  double? mediaAspectRatio;
  String externalLink;
  int previewSeconds;
  double continuePrice;
  double watchReward;
  int watchRequiredSeconds;
  List<String> rewardedViewers;

  MediaPost({
    required this.id,
    required this.userEmail,
    required this.username,
    required this.videoUrl,
    required this.caption,
    required this.timestamp,
    this.contentType = 'video',
    this.likes = 0,
    this.likedBy = const <String>[],
    this.savedBy = const <String>[],
    this.comments = const <Map<String, dynamic>>[],
    this.taggedUsers = const <String>[],
    this.mediaAspectRatio,
    this.externalLink = '',
    this.previewSeconds = 0,
    this.continuePrice = 0,
    this.watchReward = 0,
    this.watchRequiredSeconds = 0,
    List<String>? rewardedViewers,
  }) : rewardedViewers = rewardedViewers ?? <String>[];

  NgmyMediaMonetization get monetization => NgmyMediaMonetization(
        externalLink: externalLink,
        previewSeconds: previewSeconds,
        continuePrice: continuePrice,
        watchReward: watchReward,
        watchRequiredSeconds: watchRequiredSeconds,
        rewardedViewers: rewardedViewers,
      );

  void applyMonetization(NgmyMediaMonetization m) {
    externalLink = m.externalLink;
    previewSeconds = m.previewSeconds;
    continuePrice = m.continuePrice;
    watchReward = m.watchReward;
    watchRequiredSeconds = m.watchRequiredSeconds;
    rewardedViewers = List<String>.from(m.rewardedViewers);
  }

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{
      'id': id,
      'userEmail': userEmail,
      'username': username,
      'videoUrl': videoUrl,
      'url': videoUrl,
      'contentType': contentType,
      'type': contentType,
      'caption': caption,
      'timestamp': timestamp.toUtc().toIso8601String(),
      'likes': likedBy.length,
      'likedBy': likedBy,
      'savedBy': savedBy,
      'comments': comments,
      'taggedUsers': taggedUsers,
      if (mediaAspectRatio != null) 'mediaAspectRatio': mediaAspectRatio,
    };
    monetization.applyTo(map);
    return map;
  }

  factory MediaPost.fromJson(Map<String, dynamic> json) {
    final likedBy = List<String>.from(json['likedBy'] ?? json['liked_by'] ?? const []);
    final savedBy = List<String>.from(json['savedBy'] ?? json['saved_by'] ?? const []);
    final comments = _jsonMapList(json['comments'] ?? json['media_comments']);
    final taggedUsers = _jsonStringList(json['taggedUsers'] ?? json['tagged_users']);
    final mon = NgmyMediaMonetization.fromJson(json);
    return MediaPost(
      id: json['id'] ?? '',
      userEmail: json['userEmail'] ?? json['user_email'] ?? '',
      username: json['username'] ?? 'User',
      videoUrl: json['videoUrl'] ?? json['video_url'] ?? '',
      contentType: (json['contentType'] ?? json['content_type'] ?? json['type'] ?? 'video').toString(),
      caption: json['caption'] ?? '',
      timestamp: DateTime.parse(json['timestamp'] ?? json['created_at'] ?? DateTime.now().toIso8601String()).toLocal(),
      likedBy: likedBy,
      savedBy: savedBy,
      comments: comments,
      taggedUsers: taggedUsers,
      likes: likedBy.isNotEmpty ? likedBy.length : (json['likes'] ?? 0),
      mediaAspectRatio: (json['mediaAspectRatio'] as num?)?.toDouble(),
      externalLink: mon.externalLink,
      previewSeconds: mon.previewSeconds,
      continuePrice: mon.continuePrice,
      watchReward: mon.watchReward,
      watchRequiredSeconds: mon.watchRequiredSeconds,
      rewardedViewers: List<String>.from(mon.rewardedViewers),
    );
  }
}

double _clampMediaAspectRatio(double ratio) => ratio.clamp(0.45, 2.35);

/// Display name for media posts — never show generic "User" when we can resolve the account.
String _mediaAuthorName(UserData user) {
  final full = user.fullName?.trim();
  if (full != null && full.isNotEmpty) return full;
  final un = user.username.trim();
  if (un.isNotEmpty && un != 'User') return un;
  final email = user.email.trim().toLowerCase();
  if (email.contains('@')) return email.split('@').first;
  return un.isNotEmpty ? un : 'Member';
}

String _mediaPostDisplayName(MediaPost post, List<UserData> allUsers) {
  final stored = post.username.trim();
  if (stored.isNotEmpty && stored != 'User') return stored;
  final email = post.userEmail.toLowerCase().trim();
  if (email.isNotEmpty) {
    final user = allUsers.firstWhere(
      (x) => x.email.toLowerCase().trim() == email,
      orElse: () => UserData(email: post.userEmail),
    );
    return _mediaAuthorName(user);
  }
  return stored.isNotEmpty ? stored : 'Member';
}

String _pickMediaUsername(String remote, String local) {
  bool good(String s) => s.trim().isNotEmpty && s.trim() != 'User';
  if (good(remote)) return remote.trim();
  if (good(local)) return local.trim();
  return remote.trim().isNotEmpty ? remote.trim() : local.trim();
}

double _mediaFrameHeightForWidth(double width, double aspectRatio, double maxScreenFraction) {
  final safeRatio = _clampMediaAspectRatio(aspectRatio);
  final maxH = width / safeRatio;
  return maxH;
}

Future<double?> _aspectRatioFromImageBytes(Uint8List bytes) async {
  try {
    final codec = await ui.instantiateImageCodec(bytes);
    final frame = await codec.getNextFrame();
    final w = frame.image.width;
    final h = frame.image.height;
    if (w <= 0 || h <= 0) return null;
    return _clampMediaAspectRatio(w / h);
  } catch (e) {
    debugPrint('[media] aspect ratio decode: $e');
    return null;
  }
}

String? _missingColumnFromPostgrestError(Object error) {
  final text = error.toString();
  final m = RegExp("Could not find the '([^']+)' column").firstMatch(text);
  return m?.group(1);
}

bool _isMissingTablePostgrestError(Object error, String table) {
  return error.toString().contains("Could not find the table 'public.$table'");
}

Future<bool> _upsertMediaRowSafe(Map<String, dynamic> row) async {
  final working = Map<String, dynamic>.from(row);
  final mediaType = (working['contentType'] ?? working['content_type'] ?? working['type'] ?? 'video').toString();
  working['type'] = mediaType;
  working['contentType'] = mediaType;
  final url = (working['videoUrl'] ?? working['video_url'] ?? working['url'] ?? '').toString();
  if (url.isEmpty) return false;
  working['url'] = url;
  if (url.startsWith('data:') && url.length > 120000) {
    debugPrint('[media] skipped upsert: inline media too large for database.');
    return false;
  }
  for (int i = 0; i < 12; i++) {
    try {
      await Supabase.instance.client.from('media').upsert([working]);
      return true;
    } catch (e) {
      if (_isMissingTablePostgrestError(e, 'media')) {
        debugPrint('[media] table missing in Supabase.');
        return false;
      }
      final missing = _missingColumnFromPostgrestError(e);
      if (missing != null && missing.isNotEmpty) {
        working.remove(missing);
        continue;
      }
      debugPrint('[media] upsert error: $e');
      return false;
    }
  }
  return false;
}

Future<List<MediaPost>?> _fetchMediaPostsFromSupabase() async {
  try {
    final rows = await Supabase.instance.client.from('media').select();
    if (rows == null) return null;
    return (rows as List)
        .map((e) => MediaPost.fromJson(Map<String, dynamic>.from(e as Map)))
        .toList();
  } catch (e) {
    debugPrint('[media] fetch error: $e');
    return null;
  }
}

Future<bool> _deleteMediaRowFromSupabase(String id) async {
  if (id.isEmpty) return false;
  try {
    await Supabase.instance.client.from('media').delete().eq('id', id);
    return true;
  } catch (e) {
    debugPrint('[media] delete error: $e');
    return false;
  }
}

Future<bool> _mediaPostExistsInSupabase(String id) async {
  if (id.isEmpty) return false;
  try {
    final row = await Supabase.instance.client.from('media').select('id').eq('id', id).maybeSingle();
    return row != null;
  } catch (e) {
    debugPrint('[media] exists check error: $e');
    return true;
  }
}

bool _mediaUrlIsCloudSynced(String url) {
  final u = url.trim();
  return u.startsWith('supabase://') || u.startsWith('http://') || u.startsWith('https://');
}

/// Merges Supabase media with local-only drafts. Social fields merge both sides.
List<MediaPost> _mergeMediaWithRemote(
  List<MediaPost> local,
  List<MediaPost> remote, {
  Set<String> tombstones = const {},
}) {
  final merged = <String, MediaPost>{};
  for (final m in remote) {
    if (m.id.isNotEmpty && !tombstones.contains(m.id)) merged[m.id] = m;
  }
  for (final m in local) {
    if (m.id.isEmpty || tombstones.contains(m.id)) continue;
    if (merged.containsKey(m.id)) {
      merged[m.id] = _combineMediaPosts(merged[m.id]!, m);
      continue;
    }
    if (_mediaUrlIsCloudSynced(m.videoUrl)) {
      if (DateTime.now().difference(m.timestamp).inMinutes <= 15) {
        merged[m.id] = m;
      }
      continue;
    }
    merged[m.id] = m;
  }
  return merged.values.toList()..sort((a, b) => b.timestamp.compareTo(a.timestamp));
}

List<String> _mergeStringLists(List<String> a, List<String> b) {
  final out = <String>{...a, ...b};
  return out.toList();
}

List<Map<String, dynamic>> _mergeCommentLists(
  List<Map<String, dynamic>> a,
  List<Map<String, dynamic>> b,
) {
  final byId = <String, Map<String, dynamic>>{};
  for (final raw in [...a, ...b]) {
    final c = Map<String, dynamic>.from(raw);
    final id = (c['id'] ?? '').toString();
    if (id.isEmpty) continue;
    final existing = byId[id];
    if (existing == null) {
      byId[id] = c;
      continue;
    }
    final replies = _mergeCommentLists(
      List<Map<String, dynamic>>.from((existing['replies'] ?? []).map((e) => Map<String, dynamic>.from(e))),
      List<Map<String, dynamic>>.from((c['replies'] ?? []).map((e) => Map<String, dynamic>.from(e))),
    );
    final merged = Map<String, dynamic>.from(existing);
    final text = (c['text'] ?? '').toString().trim();
    if (text.isNotEmpty) merged['text'] = text;
    merged['replies'] = replies;
    byId[id] = merged;
  }
  final list = byId.values.toList();
  list.sort((x, y) {
    final tx = DateTime.tryParse((x['timestamp'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
    final ty = DateTime.tryParse((y['timestamp'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0);
    return tx.compareTo(ty);
  });
  return list;
}

MediaPost _combineMediaPosts(MediaPost remote, MediaPost local) {
  final likedBy = _mergeStringLists(remote.likedBy, local.likedBy);
  final savedBy = _mergeStringLists(remote.savedBy, local.savedBy);
  final comments = _mergeCommentLists(local.comments, remote.comments);
  return MediaPost(
    id: remote.id,
    userEmail: remote.userEmail,
    username: _pickMediaUsername(remote.username, local.username),
    videoUrl: remote.videoUrl.isNotEmpty ? remote.videoUrl : local.videoUrl,
    contentType: remote.contentType.isNotEmpty ? remote.contentType : local.contentType,
    caption: remote.caption.isNotEmpty ? remote.caption : local.caption,
    timestamp: remote.timestamp.isAfter(local.timestamp) ? remote.timestamp : local.timestamp,
    likes: likedBy.length,
    likedBy: likedBy,
    savedBy: savedBy,
    comments: comments,
    taggedUsers: _mergeStringLists(remote.taggedUsers, local.taggedUsers),
    mediaAspectRatio: remote.mediaAspectRatio ?? local.mediaAspectRatio,
    externalLink: remote.externalLink.isNotEmpty ? remote.externalLink : local.externalLink,
    previewSeconds: remote.previewSeconds > 0 ? remote.previewSeconds : local.previewSeconds,
    continuePrice: remote.continuePrice > 0 ? remote.continuePrice : local.continuePrice,
    watchReward: remote.watchReward > 0 ? remote.watchReward : local.watchReward,
    watchRequiredSeconds: remote.watchRequiredSeconds > 0 ? remote.watchRequiredSeconds : local.watchRequiredSeconds,
    rewardedViewers: _mergeStringLists(remote.rewardedViewers, local.rewardedViewers),
  );
}

int _mediaCommentCount(List<Map<String, dynamic>> comments) {
  var n = 0;
  for (final c in comments) {
    n += 1;
    final replies = c['replies'];
    if (replies is List) n += replies.length;
  }
  return n;
}

Uint8List _readMediaFileBytesSync(String path) => File(path).readAsBytesSync();

Future<Uint8List> _readMediaPickerBytes(XFile media) async {
  if (!kIsWeb) {
    final path = media.path.trim();
    if (path.isNotEmpty) {
      return compute(_readMediaFileBytesSync, path);
    }
  }
  return media.readAsBytes();
}

