Future<Map<String, String>> _fetchRemoteLegalContent() async {
  try {
    final row = await Supabase.instance.client.from('config').select().eq('id', 1).maybeSingle();
    if (row == null) return {};
    final map = Map<String, dynamic>.from(row);
