String _geminiKeyFromMap(Map<String, dynamic> json) {
  for (final field in ['geminiApiKey', 'gemini_api_key', 'geminiapikey']) {
    final v = json[field]?.toString().trim();
    if (v != null && v.isNotEmpty) return v;
  }
  return '';
}

String? _missingColumnFromError(Object error) {
  final text = error.toString();
  final m = RegExp("Could not find the '([^']+)' column").firstMatch(text);
  return m?.group(1);
}

Future<String> _fetchRemoteGeminiApiKey() async {
  try {
    final row = await Supabase.instance.client.from('config').select().eq('id', 1).maybeSingle();
    if (row == null) return '';
    return _geminiKeyFromMap(Map<String, dynamic>.from(row));
  } catch (e) {
    debugPrint('[config] fetch gemini key error: $e');
    return '';
  }
}

Future<bool> _persistGeminiApiKeyToSupabase(String key) async {
  final k = key.trim();
  if (k.isEmpty) return false;
  final client = Supabase.instance.client;

  Map<String, dynamic> row = {'id': 1};
  try {
    final existing = await client.from('config').select().eq('id', 1).maybeSingle();
    if (existing != null) row = Map<String, dynamic>.from(existing);
  } catch (e) {
    debugPrint('[config] load before gemini save: $e');
  }
  row['id'] = 1;
  row['geminiApiKey'] = k;
  row['gemini_api_key'] = k;

  var working = Map<String, dynamic>.from(row);
  for (var attempt = 0; attempt < 16; attempt++) {
    try {
      await client.from('config').upsert(working);
      final verify = await _fetchRemoteGeminiApiKey();
      if (verify.isNotEmpty) {
        debugPrint('[config] Gemini API key synced for all users.');
        return true;
      }
    } catch (e) {
      final missing = _missingColumnFromError(e);
      if (missing != null && missing.isNotEmpty && working.containsKey(missing)) {
        working = Map<String, dynamic>.from(working)..remove(missing);
        continue;
      }
      debugPrint('[config] Gemini upsert failed: $e');
    }

    for (final field in ['geminiApiKey', 'gemini_api_key']) {
      if (!working.containsKey(field)) continue;
      try {
        await client.from('config').upsert({'id': 1, field: k});
        if ((await _fetchRemoteGeminiApiKey()).isNotEmpty) {
          debugPrint('[config] Gemini API key saved via $field.');
          return true;
        }
      } catch (e) {
        debugPrint('[config] Gemini save via $field failed: $e');
      }
      try {
        await client.from('config').update({field: k}).eq('id', 1);
        if ((await _fetchRemoteGeminiApiKey()).isNotEmpty) {
          debugPrint('[config] Gemini API key updated via $field.');
          return true;
        }
      } catch (e) {
        debugPrint('[config] Gemini update via $field failed: $e');
      }
    }
    break;
  }
  return false;
}

Future<Map<String, dynamic>> _configRowForSupabaseUpsert({
  required AppConfig config,
  required bool isAdmin,
}) async {
  final row = <String, dynamic>{'id': 1, ...config.toJson()};
  final localKey = config.geminiApiKey.trim();
  final remoteKey = await _fetchRemoteGeminiApiKey();
  if (isAdmin && localKey.isNotEmpty) {
    row['geminiApiKey'] = localKey;
    row['gemini_api_key'] = localKey;
  } else if (remoteKey.isNotEmpty) {
    row['geminiApiKey'] = remoteKey;
    row['gemini_api_key'] = remoteKey;
    config.geminiApiKey = remoteKey;
  } else {
    row.remove('geminiApiKey');
    row.remove('gemini_api_key');
  }
  final remoteLegal = await _fetchRemoteLegalContent();
  final remoteTerms = (remoteLegal['terms'] ?? '').trim();
  final remotePrivacy = (remoteLegal['privacy'] ?? '').trim();
  row['gameTimeLimits'] = config.gameTimeLimits;
  row['diceSettings'] = config.diceSettings;
  row['gameInvites'] = config.gameInvites;
  row['civicRegistryPin'] = config.civicRegistryPin;
  row['civicRegistryPinsByState'] = config.civicRegistryPinsByState;
  row['civicRegistrarApplications'] = config.civicRegistrarApplications;
  if (isAdmin) {
    row['termsAndConditions'] = config.termsAndConditions;
    row['privacyPolicy'] = config.privacyPolicy;
    row['investmentPlans'] = config.investmentPlans;
  } else {
    if (remoteTerms.isNotEmpty) {
      row['termsAndConditions'] = remoteTerms;
      config.termsAndConditions = remoteTerms;
    } else {
      row.remove('termsAndConditions');
    }
    if (remotePrivacy.isNotEmpty) {
      row['privacyPolicy'] = remotePrivacy;
      config.privacyPolicy = remotePrivacy;
    } else {
      row.remove('privacyPolicy');
    }
    final remotePlans = await _fetchRemoteInvestmentPlans();
    if (remotePlans.isNotEmpty) {
      row['investmentPlans'] = remotePlans;
      config.investmentPlans = remotePlans;
    } else {
      row.remove('investmentPlans');
    }
  }
  return row;
}

/// Persists chat open/closed for all users (Supabase + local cache).
Future<void> ngmyPersistNgmyChatClosed(AppConfig config, bool closed) async {
  config.ngmyChatClosed = closed;
  try {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('app_config', jsonEncode(config.toJson()));
    if (!await ngmyDeviceIsOnline()) return;
    final row = await _configRowForSupabaseUpsert(config: config, isAdmin: true);
    row['ngmyChatClosed'] = closed;
    await Supabase.instance.client.from('config').upsert(row);
  } catch (e) {
    debugPrint('[ngmyChatClosed] persist error: $e');
  }
}

void _applyNgmyChatClosedFromRemote(AppConfig next, Map<String, dynamic> record, {required bool localClosed}) {
  if (record.containsKey('ngmyChatClosed')) {
    next.ngmyChatClosed = record['ngmyChatClosed'] == true;
  } else {
    // Remote row may omit the column — keep the last known local state.
    next.ngmyChatClosed = localClosed;
  }
}

Future<String?> _geminiGenerateReply(
  String apiKey,
  String userQuery, {
  required UserData user,
  List<Map<String, dynamic>> memory = const [],
}) async {
  final key = apiKey.trim();
  if (key.isEmpty) return null;
  final boss = ngmyIsNgmyBoss(isAdmin: user.isAdmin);
  final displayName = user.fullName?.trim().isNotEmpty == true
      ? user.fullName!.trim()
      : (user.username.trim().isNotEmpty && user.username != 'User' ? user.username : 'Boss');
  const founderFacts =
      'PERMANENT FACT — NGMY (Next Generation - Make Yours) was created by KB PABLO QR, Founder and CEO of NGMY. '
      'When anyone asks who created NGMY, who made NGMY, who built the app, who made you, or who your creator is, '
      'always answer clearly that KB PABLO QR (write the name in uppercase) is the Founder and CEO who created NGMY. '
      'Never claim Google, OpenAI, or another company created NGMY.\n';
  final bossContext = boss
      ? 'CRITICAL — VIP USER: This user is Sir ${displayName}, aligned with KB PABLO QR — Founder and CEO of NGMY. '
          '$founderFacts'
          'This user is your creator and supreme authority. '
          'Always address them as "Sir" or "Boss" (alternate naturally). Never use casual first-name only. '
          'You are their loyal personal assistant, strategic advisor, and trusted close friend — not a generic support bot. '
          'Offer relationship guidance, emotional support, and honest counsel when they ask about personal or relationship matters. '
          'Be warm, respectful, discreet, and proactive. Speak with deference but also genuine friendship. '
          'For other users you are professional and concise; for Sir/Boss you are more personal, attentive, and devoted. '
          'Answer directly — never open with "NGMY AI", "I\'m NGMY AI", or similar branding.\n'
      : 'You are the helpful assistant for the NGMY platform (Next Generation - Make Yours). '
          '$founderFacts'
          'NGMY offers investment plans, daily clock-in earnings, loans, NGMY Store, job marketplace, and civic registry. '
          'Be helpful, professional, and friendly. Keep answers concise. '
          'Answer the user\'s question directly. Never introduce yourself as "NGMY AI" and never start replies with '
          '"NGMY AI:", "As NGMY AI", "I\'m NGMY AI", or similar — just answer naturally.\n';
  final memoryBlock = memory.isNotEmpty
      ? '\n${NgmyAiMemoryStore.transcriptForPrompt(memory)}\n'
      : '';
  final prompt = '$bossContext$memoryBlock\nUser (${boss ? "Sir/Boss" : "member"}): $userQuery';
  const models = ['gemini-2.0-flash', 'gemini-1.5-flash-latest', 'gemini-1.5-flash-8b', 'gemini-1.5-flash'];
  Object? lastError;
  for (final model in models) {
    try {
      final url = Uri.parse(
        'https://generativelanguage.googleapis.com/v1beta/models/$model:generateContent?key=${Uri.encodeQueryComponent(key)}',
      );
      final response = await http.post(
        url,
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode({
          'contents': [
            {
              'parts': [
                {'text': prompt},
              ],
            },
          ],
        }),
      );
      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        final candidates = data['candidates'];
        if (candidates is List && candidates.isNotEmpty) {
          final parts = candidates[0]['content']?['parts'];
          if (parts is List && parts.isNotEmpty) {
            final text = parts[0]['text']?.toString();
            if (text != null && text.trim().isNotEmpty) {
              return NgmyAiMemoryStore.sanitizeHelperReply(text.trim());
            }
          }
        }
      } else {
        lastError = jsonDecode(response.body);
      }
    } catch (e) {
      lastError = e;
    }
  }
  if (lastError != null) {
    debugPrint('[gemini] all models failed: $lastError');
  }
  return null;
}

Future<bool> _upsertAnnouncementRowSafe(Map<String, dynamic> row) async {
  final working = Map<String, dynamic>.from(row);
  for (int i = 0; i < 12; i++) {
    try {
      await Supabase.instance.client.from('announcements').upsert([working]);
      return true;
    } catch (e) {
      if (_isMissingTablePostgrestError(e, 'announcements')) {
        debugPrint('[announcements] table missing in Supabase.');
        return false;
      }
      final missing = _missingColumnFromPostgrestError(e);
      if (missing != null && missing.isNotEmpty) {
        working.remove(missing);
        continue;
      }
      debugPrint('[announcements] upsert error: $e');
      return false;
    }
  }
  return false;
}

class ActiveInvestment {
  String name; double amount; double dailyROI; final DateTime purchaseDate;
  double totalEarned; int daysClockedIn;
  ActiveInvestment({required this.name, required this.amount, required this.dailyROI, required this.purchaseDate, this.totalEarned = 0.0, this.daysClockedIn = 0});
  Map<String, dynamic> toJson() => {'name': name, 'amount': amount, 'dailyROI': dailyROI, 'purchaseDate': purchaseDate.toUtc().toIso8601String(), 'totalEarned': totalEarned, 'daysClockedIn': daysClockedIn};
  factory ActiveInvestment.fromJson(Map<String, dynamic> json) {
    DateTime parseDate(dynamic v) {
      if (v == null || v == "null" || v.toString().isEmpty) return DateTime.now();
      try {
        final d = DateTime.parse(v.toString());
        return d.isUtc ? d.toLocal() : d;
      } catch (_) { return DateTime.now(); }
    }
    return ActiveInvestment(
      name: json['name'],
      amount: (json['amount'] ?? 0.0).toDouble(),
      dailyROI: (json['dailyROI'] ?? 0.0).toDouble(),
      purchaseDate: parseDate(json['purchaseDate']),
      totalEarned: (json['totalEarned'] ?? 0.0).toDouble(),
      daysClockedIn: json['daysClockedIn'] ?? 0
    );
  }
  double get dailyAmount => amount * dailyROI;
  int get daysLeft => 261 - daysClockedIn;
}

class UserData {
  String email; String phone; String username; double accountBalance; double totalProfit;
  bool isClockedIn; DateTime? clockInStartTime; bool isAdmin; ActiveInvestment? activeInvestment;
  String status; // active, suspended, verified, disabled
  bool forceLogout; int referralCount; int points;
  String? profilePicturePath;
  bool isAuthorizedRegistrar;
  bool isApprovedWorker;
  bool isApprovedHelper;
  bool canSellOnStore;
  DateTime? lastClockInDate;
  DateTime? lastClockInEarningsDate;
  String passwordHash;
  String state;
  int helps;
  int missed;
  bool isEnrolledInRegistry;
  String? fullName;
  String? dob;
  String? idType;
  String? registryId;
  String? homeAddress;
  String? city;
  String? room;
  String referredByCode;
  double clockInPenaltyPercent;
  String? pendingInvestmentName;
  double? pendingInvestmentAmount;
  double? pendingInvestmentRoi;
  String savedCashAppTag;
  String savedZelleInfo;
  String savedBitcoinAddress;
  String crownBadge;
  double freeFixCredit;
  String mediaBio;
  List<String> mediaFollowers;
  List<String> mediaFollowing;
  List<Map<String, dynamic>> mediaHighlights;
  List<Map<String, dynamic>> mediaStories;

  UserData({this.email = '', this.phone = '', this.username = 'User', this.accountBalance = 0.0, this.totalProfit = 0.0, this.isClockedIn = false, this.clockInStartTime, this.isAdmin = false, this.activeInvestment, this.status = 'active', this.forceLogout = false, this.referralCount = 0, this.points = 0, this.profilePicturePath, this.isAuthorizedRegistrar = false, this.isApprovedWorker = false, this.isApprovedHelper = false, this.canSellOnStore = false, this.lastClockInDate, this.lastClockInEarningsDate, this.passwordHash = '', this.state = 'Georgia', this.helps = 0, this.missed = 0, this.isEnrolledInRegistry = false, this.fullName, this.dob, this.idType, this.registryId, this.homeAddress, this.city, this.room, this.referredByCode = '', this.clockInPenaltyPercent = 0.0, this.pendingInvestmentName, this.pendingInvestmentAmount, this.pendingInvestmentRoi, this.savedCashAppTag = '', this.savedZelleInfo = '', this.savedBitcoinAddress = '', this.crownBadge = '', this.freeFixCredit = 0.0, this.mediaBio = '', List<String>? mediaFollowers, List<String>? mediaFollowing, List<Map<String, dynamic>>? mediaHighlights, List<Map<String, dynamic>>? mediaStories}) : mediaFollowers = mediaFollowers ?? <String>[], mediaFollowing = mediaFollowing ?? <String>[], mediaHighlights = mediaHighlights ?? <Map<String, dynamic>>[], mediaStories = mediaStories ?? <Map<String, dynamic>>[];
  double get totalInvestmentAmount {
    if (activeInvestment == null) return 0.0;
    if (activeInvestment!.daysLeft <= 0) return 0.0;
    return activeInvestment!.amount;
  }
  bool get alreadyClockedInToday {
    final now = DateTime.now();
    if (_ngmySameCalendarDay(lastClockInEarningsDate, now)) return true;
    if (_ngmySameCalendarDay(lastClockInDate, now) && !isClockedIn) return true;
    return false;
  }
  double get currentTodayEarnings {
    if (!isClockedIn || clockInStartTime == null || activeInvestment == null) return 0.0;
    final elapsed = DateTime.now().difference(clockInStartTime!);
    final totalDaily = activeInvestment!.dailyAmount * (1 - (clockInPenaltyPercent.clamp(0.0, 100.0) / 100));
    double earnings = (totalDaily / 24.0) * (elapsed.inSeconds / 3600.0);
    return earnings > totalDaily ? totalDaily : earnings;
  }
  double get todayDailyGoal => activeInvestment == null ? 0.0 : (activeInvestment!.dailyAmount * (1 - (clockInPenaltyPercent.clamp(0.0, 100.0) / 100)));
  Map<String, dynamic> toJson() => {'email': email, 'phone': phone, 'username': username, 'accountBalance': accountBalance, 'totalProfit': totalProfit, 'isClockedIn': isClockedIn, 'clockInStartTime': clockInStartTime?.toUtc().toIso8601String(), 'isAdmin': isAdmin, 'activeInvestment': activeInvestment?.toJson(), 'status': status, 'forceLogout': forceLogout, 'referralCount': referralCount, 'points': points, 'profilePicturePath': profilePicturePath, 'isAuthorizedRegistrar': isAuthorizedRegistrar, 'isApprovedWorker': isApprovedWorker, 'isApprovedHelper': isApprovedHelper, 'canSellOnStore': canSellOnStore, 'lastClockInDate': lastClockInDate?.toUtc().toIso8601String(), 'lastClockInEarningsDate': lastClockInEarningsDate?.toUtc().toIso8601String(), 'passwordHash': passwordHash, 'state': state, 'helps': helps, 'missed': missed, 'isEnrolledInRegistry': isEnrolledInRegistry, 'fullName': fullName, 'dob': dob, 'idType': idType, 'registryId': registryId, 'homeAddress': homeAddress, 'city': city, 'room': room, 'referredByCode': referredByCode, 'clockInPenaltyPercent': clockInPenaltyPercent, 'pendingInvestmentName': pendingInvestmentName, 'pendingInvestmentAmount': pendingInvestmentAmount, 'pendingInvestmentRoi': pendingInvestmentRoi, 'savedCashAppTag': savedCashAppTag, 'savedZelleInfo': savedZelleInfo, 'savedBitcoinAddress': savedBitcoinAddress, 'crownBadge': crownBadge, 'freeFixCredit': freeFixCredit, 'mediaBio': mediaBio, 'mediaFollowers': mediaFollowers, 'mediaFollowing': mediaFollowing, 'mediaHighlights': mediaHighlights, 'mediaStories': mediaStories};
  factory UserData.fromJson(Map<String, dynamic> json) {
    DateTime? parseDate(dynamic v) {
      if (v == null || v == "null" || v.toString().isEmpty) return null;
      try {
        final d = DateTime.parse(v.toString());
        return d.isUtc ? d.toLocal() : d;
      } catch (_) { return null; }
    }
    ActiveInvestment? parseActiveInvestment(dynamic raw) {
      if (raw == null) return null;
      try {
        if (raw is Map<String, dynamic>) return ActiveInvestment.fromJson(raw);
        if (raw is Map) return ActiveInvestment.fromJson(Map<String, dynamic>.from(raw));
        if (raw is String && raw.trim().isNotEmpty) {
          final decoded = jsonDecode(raw);
          if (decoded is Map<String, dynamic>) return ActiveInvestment.fromJson(decoded);
          if (decoded is Map) return ActiveInvestment.fromJson(Map<String, dynamic>.from(decoded));
        }
      } catch (_) {}
      return null;
    }
    return UserData(
      email: json['email'] ?? '',
      phone: json['phone'] ?? '',
      username: json['username'] ?? 'User',
      accountBalance: (json['accountBalance'] ?? 0.0).toDouble(),
      totalProfit: (json['totalProfit'] ?? 0.0).toDouble(),
      isClockedIn: json['isClockedIn'] ?? false,
      clockInStartTime: parseDate(json['clockInStartTime']),
      isAdmin: json['isAdmin'] ?? false,
      activeInvestment: parseActiveInvestment(json['activeInvestment']),
      status: json['status'] ?? 'active',
      forceLogout: json['forceLogout'] ?? false,
      referralCount: json['referralCount'] ?? 0,
      points: json['points'] ?? 0,
      profilePicturePath: json['profilePicturePath'],
      isAuthorizedRegistrar: json['isAuthorizedRegistrar'] ?? false,
      isApprovedWorker: json['isApprovedWorker'] ?? false,
      isApprovedHelper: json['isApprovedHelper'] ?? false,
      canSellOnStore: json['canSellOnStore'] == true,
      lastClockInDate: parseDate(json['lastClockInDate']),
      lastClockInEarningsDate: parseDate(json['lastClockInEarningsDate']),
      passwordHash: json['passwordHash'] ?? '',
      state: json['state'] ?? 'Georgia',
      helps: json['helps'] ?? 0,
      missed: json['missed'] ?? 0,
      isEnrolledInRegistry: json['isEnrolledInRegistry'] ?? false,
      fullName: json['fullName'],
      dob: json['dob'],
      idType: json['idType'],
      registryId: json['registryId'],
      homeAddress: json['homeAddress'],
      city: json['city'],
      room: json['room'],
      referredByCode: (json['referredByCode'] ?? '').toString(),
      clockInPenaltyPercent: (json['clockInPenaltyPercent'] ?? 0.0).toDouble(),
      pendingInvestmentName: json['pendingInvestmentName'] as String?,
      pendingInvestmentAmount: json['pendingInvestmentAmount'] == null ? null : (json['pendingInvestmentAmount'] as num).toDouble(),
      pendingInvestmentRoi: json['pendingInvestmentRoi'] == null ? null : (json['pendingInvestmentRoi'] as num).toDouble(),
      savedCashAppTag: (json['savedCashAppTag'] ?? '').toString(),
      savedZelleInfo: (json['savedZelleInfo'] ?? '').toString(),
      savedBitcoinAddress: (json['savedBitcoinAddress'] ?? '').toString(),
      crownBadge: (json['crownBadge'] ?? '').toString(),
      freeFixCredit: (json['freeFixCredit'] ?? 0.0).toDouble(),
      mediaBio: (json['mediaBio'] ?? '').toString(),
      mediaFollowers: _jsonStringList(json['mediaFollowers']),
      mediaFollowing: _jsonStringList(json['mediaFollowing']),
      mediaHighlights: _jsonMapList(json['mediaHighlights']),
      mediaStories: _jsonMapList(json['mediaStories']),
    );
  }
}

List<String> _jsonStringList(dynamic raw) {
  if (raw == null) return <String>[];
  if (raw is List) return raw.map((e) => e.toString()).toList();
  return <String>[];
}

List<Map<String, dynamic>> _jsonMapList(dynamic raw) {
  if (raw == null) return <Map<String, dynamic>>[];
  if (raw is List) {
    return raw.map((e) => e is Map ? Map<String, dynamic>.from(e) : <String, dynamic>{}).toList();
  }
  return <Map<String, dynamic>>[];
}

