    try { _configChannel?.unsubscribe(); } catch (_) {}
    try { _storeListingsChannel?.unsubscribe(); } catch (_) {}
    try { _ngmySettingsChannel?.unsubscribe(); } catch (_) {}
    try { _authSub?.cancel(); } catch (_) {}
    super.dispose();
  }

  final supabase = Supabase.instance.client;

  ThemeMode get _effectiveThemeMode {
    if (_themeMode != ThemeMode.system) return _themeMode;
    final now = DateTime.now();
    final mins = now.hour * 60 + now.minute;
    const startLight = 9 * 60;  // 9:00 AM
    const startDark = 20 * 60;  // 8:00 PM
    return (mins >= startLight && mins < startDark) ? ThemeMode.light : ThemeMode.dark;
  }

  void _applySystemUiForMode(ThemeMode mode) {
    final isDarkMode = mode == ThemeMode.dark;
    final style = isDarkMode
        ? const SystemUiOverlayStyle(
            statusBarColor: Color(0xFF121212),
            statusBarIconBrightness: Brightness.light,
            statusBarBrightness: Brightness.dark,
            systemNavigationBarColor: Color(0xFF121212),
            systemNavigationBarIconBrightness: Brightness.light,
          )
        : const SystemUiOverlayStyle(
            // Keep light mode top area bright and never black.
            statusBarColor: Colors.white,
            statusBarIconBrightness: Brightness.dark,
            statusBarBrightness: Brightness.light,
            systemNavigationBarColor: Colors.white,
            systemNavigationBarIconBrightness: Brightness.dark,
          );
    SystemChrome.setSystemUIOverlayStyle(style);
    if (kIsWeb && !isDarkMode) {
      ngmyApplyWebStatusBarStyle(lightMode: true);
    }
  }

  Future<void> _setThemeMode(ThemeMode mode) async {
    if (!mounted) return;
    setState(() => _themeMode = mode);
    _applySystemUiForMode(_effectiveThemeMode);
    final p = await SharedPreferences.getInstance();
    await p.setString('theme_mode', mode.name);
    _scheduleAutoThemeTick();
  }

  String? _oauthRedirectTo() => ngmyOAuthRedirectUrl();

  Future<String?> _startDesktopOAuthSignIn(OAuthProvider provider) async {
    HttpServer? server;
    try {
      server = await HttpServer.bind(InternetAddress.loopbackIPv4, 53682);
      final redirectTo = 'http://127.0.0.1:53682/auth-callback';
      final oauthUrl = await supabase.auth.getOAuthSignInUrl(
        provider: provider,
        redirectTo: redirectTo,
      );
      final launched = await launchUrl(
        Uri.parse(oauthUrl.url),
        mode: LaunchMode.externalApplication,
      );
      if (!launched) {
        await server.close(force: true);
        return 'Could not open ${provider.name} login screen.';
      }

      final req = await server.first.timeout(const Duration(minutes: 2));
      final callbackUri = Uri.parse('$redirectTo?${req.uri.query}');
      final hasError = callbackUri.queryParameters['error'] != null;
      final errorDescription = callbackUri.queryParameters['error_description'];

      const html = '''
<!doctype html>
<html><head><meta charset="utf-8"><title>NGMY Login</title></head>
<body style="font-family:Arial,sans-serif;padding:24px;background:#0f172a;color:#e2e8f0;">
<h2>Login Completed</h2>
<p>You can close this browser tab and return to NGMY.</p>
</body></html>
''';
      req.response.headers.contentType = ContentType.html;
      req.response.write(html);
      await req.response.close();

      if (hasError) {
        await server.close(force: true);
        return '${provider.name.toUpperCase()} login failed: ${errorDescription ?? "OAuth callback error"}';
      }
      await supabase.auth.getSessionFromUrl(callbackUri);
      await server.close(force: true);
      return null;
    } on SocketException {
      await server?.close(force: true);
      return 'Desktop login callback port is busy. Close other apps using port 53682 and try again.';
    } on TimeoutException {
      await server?.close(force: true);
      return '${provider.name.toUpperCase()} login timed out. Please try again.';
    } catch (e) {
      await server?.close(force: true);
      return '${provider.name.toUpperCase()} login failed. Add this redirect URL in Supabase Auth settings: http://127.0.0.1:53682/auth-callback. Error: $e';
    }
  }

  Future<String?> _startOAuthSignIn(OAuthProvider provider) async {
    if (!kIsWeb && (Platform.isWindows || Platform.isLinux || Platform.isMacOS)) {
      return _startDesktopOAuthSignIn(provider);
    }
    return ngmyStartOAuthSignIn(provider);
  }

  String _appConfigSig(AppConfig c) => jsonEncode(c.toJson());

  List<Map<String, dynamic>> _mergeLoanApplicationsLists(
    List<Map<String, dynamic>> local,
    List<Map<String, dynamic>> remote,
  ) {
    if (remote.isEmpty) return local;
    if (local.isEmpty) return remote;
    final byId = <String, Map<String, dynamic>>{};
    for (final a in local) {
      final id = (a['id'] ?? '').toString();
      if (id.isNotEmpty) byId[id] = Map<String, dynamic>.from(a);
    }
    for (final a in remote) {
      final id = (a['id'] ?? '').toString();
      if (id.isEmpty) continue;
      final r = Map<String, dynamic>.from(a);
      final existing = byId[id];
      if (existing == null) {
        byId[id] = r;
      } else {
        final lu = (existing['updatedAt'] ?? '').toString();
        final ru = (r['updatedAt'] ?? '').toString();
        byId[id] = ru.compareTo(lu) >= 0 ? r : existing;
      }
    }
    return byId.values.toList()
      ..sort((a, b) => (b['createdAt'] ?? '').toString().compareTo((a['createdAt'] ?? '').toString()));
  }

  void _startConfigRefreshLoop() {
    _configRefreshTimer?.cancel();
    _configRefreshTimer = Timer.periodic(const Duration(seconds: 45), (_) async {
      if (_isSyncing) return;
      try {
        final cfg = await supabase.from('config').select().maybeSingle();
        if (cfg == null) return;
        if (!mounted) return;
        final keepGemini = _config.geminiApiKey.trim();
        final keepListings = List<Map<String, dynamic>>.from(_config.storeListings.map((e) => Map<String, dynamic>.from(e)));
        final keepInquiries = List<Map<String, dynamic>>.from(_config.storeInquiries.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpApps = List<Map<String, dynamic>>.from(_config.helpHelperApplications.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpReqs = List<Map<String, dynamic>>.from(_config.helpRequests.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpBiz = List<Map<String, dynamic>>.from(_config.helpBusinesses.map((e) => Map<String, dynamic>.from(e)));
        final keepOrders = List<Map<String, dynamic>>.from(_config.storeOrders.map((e) => Map<String, dynamic>.from(e)));
        final keepPlans = List<Map<String, dynamic>>.from(_config.investmentPlans.map((e) => Map<String, dynamic>.from(e)));
        final keepPopups = List<Map<String, dynamic>>.from(_config.ngmyPopups.map((e) => Map<String, dynamic>.from(e)));
        final keepVideoPopups = List<Map<String, dynamic>>.from(_config.ngmyVideoPopups.map((e) => Map<String, dynamic>.from(e)));
        final keepLoans = List<Map<String, dynamic>>.from(_config.loanApplications.map((e) => Map<String, dynamic>.from(e)));
        final keepChatClosed = _config.ngmyChatClosed;
        final cfgMap = Map<String, dynamic>.from(cfg);
        final keepConfig = _config;
        final next = AppConfig.fromJson(cfgMap);
        _applyRemoteConfigMerge(next, cfgMap, keepConfig);
        _applyNgmyChatClosedFromRemote(next, cfgMap, localClosed: keepChatClosed);
        _applyRemoteLegalToConfig(next, cfgMap);
        final remoteGemini = _geminiKeyFromMap(cfgMap);
        if (remoteGemini.isNotEmpty) {
          next.geminiApiKey = remoteGemini;
        } else if (next.geminiApiKey.trim().isEmpty && keepGemini.isNotEmpty) {
          next.geminiApiKey = keepGemini;
        }
        if (next.storeListings.isEmpty && keepListings.isNotEmpty) next.storeListings = keepListings;
        if (next.storeInquiries.isEmpty && keepInquiries.isNotEmpty) next.storeInquiries = keepInquiries;
        if (next.storeOrders.isEmpty && keepOrders.isNotEmpty) next.storeOrders = keepOrders;
        else next.storeOrders = _mergeStoreOrdersLists(keepOrders, next.storeOrders);
        if (_maintainStoreOrders(next.storeOrders)) {
          unawaited(_pushStoreOrdersToSupabase(next.storeOrders));
        }
        if (next.helpHelperApplications.isEmpty && keepHelpApps.isNotEmpty) next.helpHelperApplications = keepHelpApps;
        if (next.helpRequests.isEmpty && keepHelpReqs.isNotEmpty) next.helpRequests = keepHelpReqs;
        if (next.helpBusinesses.isEmpty && keepHelpBiz.isNotEmpty) next.helpBusinesses = keepHelpBiz;
        if (next.loanApplications.isEmpty && keepLoans.isNotEmpty) {
          next.loanApplications = keepLoans;
        } else {
          next.loanApplications = _mergeLoanApplicationsLists(keepLoans, next.loanApplications);
        }
        final remotePopups = (cfgMap['ngmyPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        final remoteVideoPopups = (cfgMap['ngmyVideoPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        next.ngmyPopups = _mergeNgmyPopupsFromRemote(keepPopups, remotePopups, NgmyPopupDefaults.ensurePopups);
        next.ngmyVideoPopups = _mergeNgmyPopupsFromRemote(keepVideoPopups, remoteVideoPopups, NgmyPopupDefaults.ensureVideoPopups);
        final authPopups = await _fetchAuthoritativeNgmyPopups();
        if (authPopups.popups.isNotEmpty || authPopups.videos.isNotEmpty) {
          next.ngmyPopups = NgmyPopupDefaults.ensurePopups(authPopups.popups);
          next.ngmyVideoPopups = NgmyPopupDefaults.ensureVideoPopups(authPopups.videos);
        }
        final plansSigBefore = jsonEncode(_globalPlans.map((e) => e.toJson()).toList());
        final legal = await _fetchAuthoritativeLegalContent();
        final remotePlans = await _fetchAuthoritativeInvestmentPlans();
        final terms = (legal['terms'] ?? '').trim();
        final privacy = (legal['privacy'] ?? '').trim();
        if (terms.isNotEmpty) next.termsAndConditions = terms;
        if (privacy.isNotEmpty) next.privacyPolicy = privacy;
        if (remotePlans.isNotEmpty) {
          next.investmentPlans = remotePlans;
          _globalPlans = _investmentPlansFromMaps(remotePlans);
        } else if (next.investmentPlans.isEmpty && keepPlans.isNotEmpty) {
          next.investmentPlans = keepPlans;
        } else if (next.investmentPlans.isNotEmpty) {
          _globalPlans = _investmentPlansFromMaps(next.investmentPlans);
        }
        final plansSigAfter = jsonEncode(_globalPlans.map((e) => e.toJson()).toList());
        if (_appConfigSig(_config) == _appConfigSig(next) && plansSigBefore == plansSigAfter) return;
        setState(() => _config = next);
        SharedPreferences.getInstance().then((prefs) {
          prefs.setString('app_config', jsonEncode(_config.toJson()));
          prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
        }).catchError((_) {});
      } catch (_) {
        // Silent fallback; realtime/local cache still handles config.
      }
    });
  }

  void _mergeStoreListingsIntoConfig(List<Map<String, dynamic>> remote) {
    final byId = <String, Map<String, dynamic>>{};
    for (final l in remote) {
      final id = (l['id'] ?? '').toString();
      if (id.isEmpty || _isNgmySystemStoreListingId(id)) continue;
      byId[id] = _normalizeStoreListing(Map<String, dynamic>.from(l));
    }
    for (final l in _config.storeListings) {
      final id = (l['id'] ?? '').toString();
      if (id.isEmpty || _isNgmySystemStoreListingId(id)) continue;
      final existing = byId[id];
      final local = _normalizeStoreListing(Map<String, dynamic>.from(l));
      byId[id] = existing == null ? local : _pickNewerListing(existing, local);
    }
    _config.storeListings = byId.values.toList();
  }

  void _mergeStoreInquiriesIntoConfig(List<Map<String, dynamic>> remote) {
    final byId = <String, Map<String, dynamic>>{};
    for (final m in _config.storeInquiries) {
      final id = (m['id'] ?? '').toString();
      if (id.isNotEmpty) byId[id] = Map<String, dynamic>.from(m);
    }
    for (final m in remote) {
      final id = (m['id'] ?? '').toString();
      if (id.isEmpty) continue;
      byId[id] = Map<String, dynamic>.from(m);
    }
    _config.storeInquiries = byId.values.toList();
  }

  List<String> _purgeExpiredSoldStoreListings() {
    final now = DateTime.now();
    final removedListingIds = <String>[];
    final removedInquiryIds = <String>[];
    _config.storeListings.removeWhere((l) {
      if ((l['status'] ?? '').toString() != 'sold') return false;
      final soldAt = DateTime.tryParse((l['soldAt'] ?? '').toString());
      if (soldAt == null || now.difference(soldAt).inDays < 7) return false;
      final id = (l['id'] ?? '').toString();
      if (id.isNotEmpty) removedListingIds.add(id);
      return true;
    });
    _config.storeInquiries.removeWhere((m) {
      final listingId = (m['listingId'] ?? '').toString();
      if (!removedListingIds.contains(listingId)) return false;
      final id = (m['id'] ?? '').toString();
      if (id.isNotEmpty) removedInquiryIds.add(id);
      return true;
    });
    if (removedListingIds.isNotEmpty || removedInquiryIds.isNotEmpty) {
      unawaited(_deleteStoreListingRowsFromSupabase(removedListingIds));
      unawaited(_deleteStoreInquiryRowsFromSupabase(removedInquiryIds));
    }
    return removedListingIds;
  }

  Future<void> _reloadStoreFromSupabase() async {
    final listingsSigBefore = _storeListingsSignature(_config.storeListings);
    final inquiriesBefore = _config.storeInquiries.length;
    final remoteListings = await _fetchStoreListingsFromSupabase();
    final remoteInquiries = await _fetchStoreInquiriesFromSupabase();
    _mergeStoreListingsIntoConfig(remoteListings);
    _mergeStoreInquiriesIntoConfig(remoteInquiries);
    _purgeExpiredSoldStoreListings();
    if (!mounted) return;
    final listingsSigAfter = _storeListingsSignature(_config.storeListings);
    final inquiriesAfter = _config.storeInquiries.length;
    if (listingsSigBefore != listingsSigAfter || inquiriesBefore != inquiriesAfter) {
      setState(() {});
    }
  }

  void _mergeHelpListIntoConfig(String key, List<Map<String, dynamic>> remote, void Function(List<Map<String, dynamic>>) setter, List<Map<String, dynamic>> local) {
    final byId = <String, Map<String, dynamic>>{};
    for (final m in local) {
      final id = (m['id'] ?? '').toString();
      if (id.isNotEmpty) byId[id] = Map<String, dynamic>.from(m);
    }
    for (final m in remote) {
      final id = (m['id'] ?? '').toString();
      if (id.isEmpty) continue;
      byId[id] = Map<String, dynamic>.from(m);
    }
    setter(byId.values.toList());
  }

  Future<void> _reloadHelpFromSupabase() async {
    final apps = await _fetchHelpTableFromSupabase('help_applications');
    final reqs = await _fetchHelpTableFromSupabase('help_requests');
    final biz = await _fetchHelpTableFromSupabase('help_businesses');
    _mergeHelpListIntoConfig('apps', apps, (v) => _config.helpHelperApplications = v, _config.helpHelperApplications);
    _mergeHelpListIntoConfig('reqs', reqs, (v) => _config.helpRequests = v, _config.helpRequests);
    _mergeHelpListIntoConfig('biz', biz, (v) => _config.helpBusinesses = v, _config.helpBusinesses);
    if (mounted) setState(() {});
  }

  Future<void> _persistAllMediaLocally() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('all_media', jsonEncode(_allMedia.map((e) => e.toJson()).toList()));
    } catch (_) {}
  }

  Future<void> _reloadMediaFromSupabase() async {
    final remote = await _fetchMediaPostsFromSupabase();
    if (remote == null || !mounted) return;
    final next = _mergeMediaWithRemote(_allMedia, remote, tombstones: _tombstonedMediaIds);
    setState(() => _allMedia = next);
    await _persistAllMediaLocally();
  }

  Future<void> _pruneStaleMediaAgainstCloud() async {
    final remote = await _fetchMediaPostsFromSupabase();
    if (remote == null || !mounted) return;
    final next = _mergeMediaWithRemote(_allMedia, remote, tombstones: _tombstonedMediaIds);
    final before = jsonEncode(_allMedia.map((e) => e.toJson()).toList());
    final after = jsonEncode(next.map((e) => e.toJson()).toList());
    if (before != after) {
      setState(() => _allMedia = next);
      await _persistAllMediaLocally();
    }
  }

  bool _mediaListsSameIds(List<MediaPost> a, List<MediaPost> b) {
    if (a.length != b.length) return false;
    final aIds = a.map((m) => m.id).toSet();
    final bIds = b.map((m) => m.id).toSet();
    return aIds.length == bIds.length && aIds.containsAll(bIds);
  }

  Future<void> _pruneDeletedMediaPost(MediaPost post) async {
    if (post.id.isEmpty) return;
    final exists = await _mediaPostExistsInSupabase(post.id);
    if (exists) return;
    _tombstonedMediaIds.add(post.id);
    await _persistTombstonedMediaIds(_tombstonedMediaIds);
    if (!mounted) return;
    setState(() => _allMedia.removeWhere((m) => m.id == post.id));
    await _persistAllMediaLocally();
  }

  Future<void> _deleteMediaPostGlobally(MediaPost post) async {
    final id = post.id;
    if (id.isEmpty) return;
    _tombstonedMediaIds.add(id);
    await _persistTombstonedMediaIds(_tombstonedMediaIds);
    final deleted = await _deleteMediaRowFromSupabase(id);
    if (!deleted) {
      debugPrint('[media] database delete failed for $id');
    }
    final ref = _parseSupabaseStorageRef(post.videoUrl);
    if (ref != null) {
      try {
        await supabase.storage.from(ref.bucket).remove([ref.path]);
      } catch (e) {
        debugPrint('[media] storage remove warning: $e');
      }
    }
    if (!mounted) return;
    setState(() => _allMedia.removeWhere((m) => m.id == id));
    await _persistAllMediaLocally();
  }

  Future<bool> _saveLegalContentToSupabase(String terms, String privacy) async {
    try {
      setState(() {
        _config.termsAndConditions = terms;
        _config.privacyPolicy = privacy;
      });
      final saved = await _persistLegalContentToCloud(terms, privacy);
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      return saved;
    } catch (e) {
      debugPrint('[legal] save error: $e');
      return false;
    }
  }

  Future<bool> _savePopupsSettingsToCloud(List<Map<String, dynamic>> popups, List<Map<String, dynamic>> videos) async {
    try {
      _config.ngmyPopups = popups.map((e) => Map<String, dynamic>.from(e)).toList();
      _config.ngmyVideoPopups = videos.map((e) => Map<String, dynamic>.from(e)).toList();
      final saved = await _persistNgmyPopupsToCloud(_config.ngmyPopups, _config.ngmyVideoPopups);
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      if (mounted) setState(() {});
      return saved;
    } catch (e) {
      debugPrint('[popups] save error: $e');
      return false;
    }
  }

  Future<void> _refreshPopupsFromCloud({bool updateUi = true}) async {
    try {
      final remote = await _fetchAuthoritativeNgmyPopups();
      if (remote.popups.isEmpty && remote.videos.isEmpty) return;
      final nextPopups = NgmyPopupDefaults.ensurePopups(remote.popups);
      final nextVideos = NgmyPopupDefaults.ensureVideoPopups(remote.videos);
      final sigBefore = jsonEncode({'p': _config.ngmyPopups, 'v': _config.ngmyVideoPopups});
      final sigAfter = jsonEncode({'p': nextPopups, 'v': nextVideos});
      if (sigBefore == sigAfter) return;
      _config.ngmyPopups = nextPopups;
      _config.ngmyVideoPopups = nextVideos;
      if (updateUi && mounted) setState(() {});
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
    } catch (e) {
      debugPrint('[popups] cloud refresh error: $e');
    }
  }

  Future<void> _refreshLegalAndPlansFromCloud({bool updateUi = true}) async {
    try {
      final legal = await _fetchAuthoritativeLegalContent();
      final remotePlans = await _fetchAuthoritativeInvestmentPlans();
      final terms = (legal['terms'] ?? '').trim();
      final privacy = (legal['privacy'] ?? '').trim();
      final termsChanged = terms.isNotEmpty && terms != _config.termsAndConditions.trim();
      final privacyChanged = privacy.isNotEmpty && privacy != _config.privacyPolicy.trim();
      final plansSigBefore = jsonEncode(_globalPlans.map((e) => e.toJson()).toList());
      if (terms.isNotEmpty) _config.termsAndConditions = terms;
      if (privacy.isNotEmpty) _config.privacyPolicy = privacy;
      if (remotePlans.isNotEmpty) {
        _config.investmentPlans = remotePlans;
        _globalPlans = _investmentPlansFromMaps(remotePlans);
      }
      await _refreshPopupsFromCloud(updateUi: updateUi);
      final plansSigAfter = jsonEncode(_globalPlans.map((e) => e.toJson()).toList());
      if (!updateUi || (!termsChanged && !privacyChanged && plansSigBefore == plansSigAfter)) return;
      if (!mounted) return;
      setState(() {});
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      await prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
    } catch (e) {
      debugPrint('[legal/plans] cloud refresh error: $e');
    }
  }

  Future<void> _syncStoreToSupabase() async {
    _purgeExpiredSoldStoreListings();
    for (final listing in _config.storeListings) {
      final copy = Map<String, dynamic>.from(listing);
      copy['updatedAt'] = DateTime.now().toUtc().toIso8601String();
      await _upsertStoreListingRowSafe(copy);
    }
    for (final inquiry in _config.storeInquiries) {
      await _upsertStoreInquiryRowSafe(inquiry);
    }
  }

  Future<void> _initLocalNotifications() async {
    if (kIsWeb) return;
    try {
      const android = AndroidInitializationSettings('@mipmap/ic_launcher');
      const darwin = DarwinInitializationSettings(
        requestAlertPermission: true,
        requestBadgePermission: true,
        requestSoundPermission: true,
      );
      const linux = LinuxInitializationSettings(defaultActionName: 'Open');
      const initSettings = InitializationSettings(
        android: android,
        iOS: darwin,
        macOS: darwin,
        linux: linux,
      );
      await _localNotifications.initialize(settings: initSettings);
      await _localNotifications
          .resolvePlatformSpecificImplementation<AndroidFlutterLocalNotificationsPlugin>()
          ?.requestNotificationsPermission();
      _notificationsReady = true;
    } catch (e) {
      debugPrint('Notification init failed: $e');
      _notificationsReady = false;
    }
  }

  String _notificationTitleForTransaction(AppTransaction t, {bool statusChanged = false}) {
    if (statusChanged) {
      if (t.status == TransactionStatus.approved) return 'Transaction approved';
      if (t.status == TransactionStatus.rejected) return 'Transaction rejected';
      return 'Transaction update';
    }
    if (t.type == TransactionType.reimbursement &&
        (t.sourceDetails ?? '').toLowerCase().contains('clock-in')) {
      return 'Clock-in income received';
    }
    switch (t.type) {
      case TransactionType.deposit:
        return 'Deposit request submitted';
      case TransactionType.withdrawal:
        return 'Withdrawal request submitted';
      case TransactionType.adminAdd:
        return 'Account credited';
      case TransactionType.adminRemove:
        return 'Account debit';
      case TransactionType.reimbursement:
        return 'Earnings received';
      case TransactionType.contribution:
        return 'Contribution recorded';
      case TransactionType.claim:
        return 'Claim update';
    }
  }

  String _notificationBodyForTransaction(AppTransaction t, {bool statusChanged = false}) {
    final amount = '\$${formatCurrency(t.amount)}';
    final details = (t.sourceDetails ?? '').trim();
    if (statusChanged) {
      final statusText = t.status.name.toUpperCase();
      if (details.isNotEmpty) return '$statusText: $amount - $details';
      return '$statusText: $amount';
    }
    if (details.isNotEmpty) return '$amount - $details';
    return amount;
  }

  Future<void> _pushInAppNotification({
    required String title,
    required String body,
  }) async {
    if (_currentUser == null) return;

    if (_notificationsReady && !kIsWeb) {
      try {
        const androidDetails = AndroidNotificationDetails(
          'ngmy_transactions',
          'NGMY Transactions',
          channelDescription: 'Transaction and earnings notifications while app is open',
          importance: Importance.max,
          priority: Priority.high,
        );
        const darwinDetails = DarwinNotificationDetails(
          presentAlert: true,
          presentBadge: true,
          presentSound: true,
        );
        const linuxDetails = LinuxNotificationDetails();
        const details = NotificationDetails(
          android: androidDetails,
          iOS: darwinDetails,
          macOS: darwinDetails,
          linux: linuxDetails,
        );
        await _localNotifications.show(
          id: _nextNotificationId++,
          title: title,
          body: body,
          notificationDetails: details,
        );
      } catch (e) {
        debugPrint('Notification show failed: $e');
      }
    }

    _showModernInAppNotice(title: title, body: body);
  }

  void _showModernInAppNotice({
    required String title,
    required String body,
    bool isError = false,
  }) {
    if (!mounted) return;
    _inAppNoticeEntry?.remove();
    final overlay = Overlay.of(context, rootOverlay: true);
    final accent = isError ? const Color(0xFFEF4444) : const Color(0xFF22D3EE);
    _inAppNoticeEntry = OverlayEntry(
      builder: (_) => IgnorePointer(
        child: SafeArea(
          child: Align(
            alignment: Alignment.topCenter,
            child: Container(
              margin: const EdgeInsets.fromLTRB(14, 10, 14, 0),
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
              decoration: BoxDecoration(
                color: const Color(0xFF0B1020).withOpacity(0.92),
                borderRadius: BorderRadius.circular(14),
                border: Border.all(color: accent.withOpacity(0.55)),
                boxShadow: [BoxShadow(color: accent.withOpacity(0.28), blurRadius: 16, offset: const Offset(0, 6))],
              ),
              child: Row(
                children: [
                  Icon(Icons.notifications_active_rounded, color: accent),
                  const SizedBox(width: 10),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(title, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w800)),
                        const SizedBox(height: 2),
                        Text(body, style: const TextStyle(color: Colors.white70, fontSize: 12)),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
    overlay.insert(_inAppNoticeEntry!);
    Future.delayed(const Duration(seconds: 4), () {
      _inAppNoticeEntry?.remove();
      _inAppNoticeEntry = null;
    });
  }

  Future<void> _notifyTransactionEvent(AppTransaction t, {bool statusChanged = false}) async {
    final currentEmail = _currentUser?.email.toLowerCase().trim();
    if (currentEmail == null || currentEmail.isEmpty) return;
    if (t.userEmail.toLowerCase().trim() != currentEmail) return;
    await _pushInAppNotification(
      title: _notificationTitleForTransaction(t, statusChanged: statusChanged),
      body: _notificationBodyForTransaction(t, statusChanged: statusChanged),
    );
  }

  void _scheduleAutoThemeTick() {
    _autoThemeTimer?.cancel();
    if (_themeMode != ThemeMode.system) return;

    final now = DateTime.now();
    final morning = DateTime(now.year, now.month, now.day, 9, 0);
    final evening = DateTime(now.year, now.month, now.day, 20, 0);
    DateTime next;
    if (now.isBefore(morning)) {
      next = morning;
    } else if (now.isBefore(evening)) {
      next = evening;
    } else {
      next = morning.add(const Duration(days: 1));
    }
    final delay = next.difference(now) + const Duration(seconds: 1);
    _autoThemeTimer = Timer(delay, () {
      if (!mounted) return;
      setState(() {});
      _scheduleAutoThemeTick();
    });
  }

  void _subscribeToAuthState() {
    _authSub = supabase.auth.onAuthStateChange.listen((data) {
      final authUser = data.session?.user;
      final email = authUser?.email?.toLowerCase().trim();
      if (email == null || email.isEmpty) return;
      final fullName = (authUser?.userMetadata?['full_name'] ?? '').toString().trim();
      _signInOrCreateFromGoogle(email, fullName: fullName);
    });
    final current = supabase.auth.currentUser;
    final email = current?.email?.toLowerCase().trim();
    if (email != null && email.isNotEmpty) {
      final fullName = (current?.userMetadata?['full_name'] ?? '').toString().trim();
      _signInOrCreateFromGoogle(email, fullName: fullName);
    }
  }

  Future<void> _signInOrCreateFromGoogle(String email, {String fullName = ''}) async {
    final admins = ['kbpabloqr@gmail.com', 'ngumoyaking@gmail.com', 'appbusiness321@gmail.com', 'appbusiness84@gmail.com'];
    final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
    if (!mounted) return;
    setState(() {
      if (idx == -1) {
        final user = UserData(
          email: email,
          username: fullName.isNotEmpty ? fullName : email.split('@').first,
          isAdmin: admins.contains(email),
          // Google users do not need local password flow.
          passwordHash: '',
        );
        _allUsers.add(user);
        _currentUser = user;
      } else {
        if (fullName.isNotEmpty) {
          _allUsers[idx].username = fullName;
        }
        _currentUser = _allUsers[idx];
      }
    });
    await _saveData();
  }

  void _subscribeToRealtime() {
    try {
      _usersChannel = supabase
          .channel('public:users')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'users',
            callback: (payload) => _onUsersChange(payload),
          )
          .subscribe();

      _transactionsChannel = supabase
          .channel('public:transactions')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'transactions',
            callback: (payload) => _onTransactionsChange(payload),
          )
          .subscribe();

      _mediaChannel = supabase
          .channel('public:media')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'media',
            callback: (payload) => _onMediaChange(payload),
          )
          .subscribe();

      _announcementsChannel = supabase
          .channel('public:announcements')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'announcements',
            callback: (payload) => _onAnnouncementsChange(payload),
          )
          .subscribe();

      _configChannel = supabase
          .channel('public:config')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'config',
            callback: (payload) => _onConfigChange(payload),
          )
          .subscribe();

      _storeListingsChannel = supabase
          .channel('public:store_listings')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'store_listings',
            callback: (payload) => _onStoreListingChange(payload),
          )
          .subscribe();

      _ngmySettingsChannel = supabase
          .channel('public:ngmy_settings')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'ngmy_settings',
            callback: (payload) => _onNgmySettingsChange(payload),
          )
          .subscribe();
      debugPrint('Realtime subscriptions active');
    } catch (e) {
      debugPrint('Realtime subscribe error: $e');
    }
  }

  void _onAnnouncementsChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _allAnnouncements.removeWhere((a) => a.id == id));
      } else {
        final ann = Announcement.fromJson(payload.newRecord);
        bool isNew = false;
        setState(() {
          final idx = _allAnnouncements.indexWhere((a) => a.id == ann.id);
          if (idx == -1) {
            _allAnnouncements.add(ann);
            isNew = true;
          } else {
            _allAnnouncements[idx] = ann;
          }
        });
        if (isNew && !_seenRealtimeAnnouncementIds.contains(ann.id)) {
          _seenRealtimeAnnouncementIds.add(ann.id);
          _pushInAppNotification(
            title: 'New announcement',
            body: '${ann.title}: ${ann.message}',
          );
        }
      }
    } catch (e) {
      debugPrint('Announcements realtime apply error: $e');
    }
  }

  void _notifySellerOfNewStoreOrders(AppConfig prev, AppConfig next) {
    final me = _currentUser?.email.toLowerCase().trim();
    if (me == null || me.isEmpty) return;
    final prevIds = prev.storeOrders
        .map((o) => (o['id'] ?? '').toString())
        .where((id) => id.isNotEmpty)
        .toSet();
    for (final raw in next.storeOrders) {
      final o = Map<String, dynamic>.from(raw);
      final id = (o['id'] ?? '').toString();
      if (id.isEmpty || prevIds.contains(id) || _seenRealtimeStoreOrderIds.contains(id)) continue;
      final seller = (o['sellerEmail'] ?? '').toString().toLowerCase().trim();
      if (seller != me) continue;
      _seenRealtimeStoreOrderIds.add(id);
      final title = (o['title'] ?? 'Item').toString();
      unawaited(_pushInAppNotification(
        title: 'New sale',
        body: 'A buyer purchased $title. Open Store → Sales to ship.',
      ));
    }
  }

  void _onConfigChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    try {
      if (payload.eventType != PostgresChangeEvent.delete) {
        final keepListings = List<Map<String, dynamic>>.from(_config.storeListings.map((e) => Map<String, dynamic>.from(e)));
        final keepInquiries = List<Map<String, dynamic>>.from(_config.storeInquiries.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpApps = List<Map<String, dynamic>>.from(_config.helpHelperApplications.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpReqs = List<Map<String, dynamic>>.from(_config.helpRequests.map((e) => Map<String, dynamic>.from(e)));
        final keepHelpBiz = List<Map<String, dynamic>>.from(_config.helpBusinesses.map((e) => Map<String, dynamic>.from(e)));
        final keepOrders = List<Map<String, dynamic>>.from(_config.storeOrders.map((e) => Map<String, dynamic>.from(e)));
        final keepPlans = List<Map<String, dynamic>>.from(_config.investmentPlans.map((e) => Map<String, dynamic>.from(e)));
        final keepGeminiKey = _config.geminiApiKey.trim();
        final remoteGemini = _geminiKeyFromMap(Map<String, dynamic>.from(payload.newRecord));
        final record = Map<String, dynamic>.from(payload.newRecord);
        final keepConfig = _config;
        final next = AppConfig.fromJson(record);
        _applyRemoteConfigMerge(next, record, keepConfig);
        _applyRemoteLegalToConfig(next, record);
        _applyNgmyChatClosedFromRemote(next, record, localClosed: _config.ngmyChatClosed);
        if (next.storeOrders.isEmpty && keepOrders.isNotEmpty) next.storeOrders = keepOrders;
        else next.storeOrders = _mergeStoreOrdersLists(keepOrders, next.storeOrders);
        _maintainStoreOrders(next.storeOrders);
        if (next.storeListings.isEmpty && keepListings.isNotEmpty) next.storeListings = keepListings;
        if (next.storeInquiries.isEmpty && keepInquiries.isNotEmpty) next.storeInquiries = keepInquiries;
        if (next.helpHelperApplications.isEmpty && keepHelpApps.isNotEmpty) next.helpHelperApplications = keepHelpApps;
        if (next.helpRequests.isEmpty && keepHelpReqs.isNotEmpty) next.helpRequests = keepHelpReqs;
        if (next.helpBusinesses.isEmpty && keepHelpBiz.isNotEmpty) next.helpBusinesses = keepHelpBiz;
        final keepLoans = List<Map<String, dynamic>>.from(_config.loanApplications.map((e) => Map<String, dynamic>.from(e)));
        if (next.loanApplications.isEmpty && keepLoans.isNotEmpty) {
          next.loanApplications = keepLoans;
        } else {
          next.loanApplications = _mergeLoanApplicationsLists(keepLoans, next.loanApplications);
        }
        final keepPopups = List<Map<String, dynamic>>.from(_config.ngmyPopups.map((e) => Map<String, dynamic>.from(e)));
        final keepVideoPopups = List<Map<String, dynamic>>.from(_config.ngmyVideoPopups.map((e) => Map<String, dynamic>.from(e)));
        final remotePopups = (record['ngmyPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        final remoteVideoPopups = (record['ngmyVideoPopups'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)).toList();
        next.ngmyPopups = _mergeNgmyPopupsFromRemote(keepPopups, remotePopups, NgmyPopupDefaults.ensurePopups);
        next.ngmyVideoPopups = _mergeNgmyPopupsFromRemote(keepVideoPopups, remoteVideoPopups, NgmyPopupDefaults.ensureVideoPopups);
        if (remoteGemini.isNotEmpty) {
          next.geminiApiKey = remoteGemini;
        } else if (next.geminiApiKey.trim().isEmpty && keepGeminiKey.isNotEmpty) {
          next.geminiApiKey = keepGeminiKey;
        }
        unawaited(() async {
          final legal = await _fetchAuthoritativeLegalContent();
          final remotePlans = await _fetchAuthoritativeInvestmentPlans();
          final terms = (legal['terms'] ?? '').trim();
          final privacy = (legal['privacy'] ?? '').trim();
          if (terms.isNotEmpty) next.termsAndConditions = terms;
          if (privacy.isNotEmpty) next.privacyPolicy = privacy;
          if (remotePlans.isNotEmpty) {
            next.investmentPlans = remotePlans;
          } else if (next.investmentPlans.isEmpty && keepPlans.isNotEmpty) {
            next.investmentPlans = keepPlans;
          }
          final plansSigBefore = jsonEncode(_globalPlans.map((e) => e.toJson()).toList());
          if (next.investmentPlans.isNotEmpty) {
            _globalPlans = _investmentPlansFromMaps(next.investmentPlans);
          }
          if (!mounted) return;
          final plansSigAfter = jsonEncode(_globalPlans.map((e) => e.toJson()).toList());
          if (_appConfigSig(_config) == _appConfigSig(next) && plansSigBefore == plansSigAfter) return;
          _notifySellerOfNewStoreOrders(_config, next);
          setState(() => _config = next);
          SharedPreferences.getInstance().then((prefs) {
            prefs.setString('app_config', jsonEncode(_config.toJson()));
            prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
          }).catchError((_) {});
        }());
      }
    } catch (e) {
      debugPrint('Config realtime apply error: $e');
    }
  }

  void _onNgmySettingsChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    unawaited(_refreshLegalAndPlansFromCloud());
  }

  void _onStoreListingChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    try {
      final recordId = (payload.newRecord['id'] ?? payload.oldRecord['id'] ?? '').toString();
      if (_isNgmySystemStoreListingId(recordId)) {
        unawaited(_refreshLegalAndPlansFromCloud());
        return;
      }
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _config.storeListings.removeWhere((l) => (l['id'] ?? '').toString() == id));
        return;
      }
      final listing = _normalizeStoreListing(_storeListingFromRow(Map<String, dynamic>.from(payload.newRecord)));
      final id = (listing['id'] ?? '').toString();
      if (id.isEmpty) return;
      final idx = _config.storeListings.indexWhere((l) => (l['id'] ?? '').toString() == id);
      final merged = idx == -1
          ? listing
          : _pickNewerListing(_config.storeListings[idx], listing);
      final oldSig = _storeListingsSignature(_config.storeListings);
      if (idx == -1) {
        _config.storeListings.add(merged);
      } else if (_storeListingsSignature([_config.storeListings[idx]]) != _storeListingsSignature([merged])) {
        _config.storeListings[idx] = merged;
      }
      final newSig = _storeListingsSignature(_config.storeListings);
      if (newSig != oldSig && mounted) setState(() {});
    } catch (e) {
      debugPrint('Store listing realtime apply error: $e');
    }
  }

  void _onMediaChange(PostgresChangePayload payload) {
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? payload.newRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        if (!mounted) return;
        _tombstonedMediaIds.add(id);
        _persistTombstonedMediaIds(_tombstonedMediaIds);
        setState(() => _allMedia.removeWhere((m) => m.id == id));
        _persistAllMediaLocally();
        return;
      }
      if (_isSyncing) return;
      final incoming = MediaPost.fromJson(payload.newRecord);
      if (!mounted) return;
      setState(() {
        final idx = _allMedia.indexWhere((m) => m.id == incoming.id);
        if (idx == -1) {
          _allMedia.insert(0, incoming);
        } else {
          _allMedia[idx] = _combineMediaPosts(incoming, _allMedia[idx]);
        }
        _allMedia.sort((a, b) => b.timestamp.compareTo(a.timestamp));
      });
      unawaited(_persistAllMediaLocally());
    } catch (e) {
      debugPrint('Media realtime apply error: $e');
    }
  }

  void _onUsersChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final email = (payload.oldRecord['email'] ?? '').toString().toLowerCase().trim();
        if (email.isEmpty) return;
        setState(() => _allUsers.removeWhere((u) => u.email.toLowerCase().trim() == email));
      } else {
        final newRow = payload.newRecord;
        final updatedUser = UserData.fromJson(newRow);
        final email = updatedUser.email.toLowerCase().trim();
        if (email.isEmpty) return;
        setState(() {
          final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
          if (idx == -1) {
            _allUsers.add(updatedUser);
          } else {
            _allUsers[idx] = updatedUser;
          }
          if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == email) {
            if (updatedUser.forceLogout) {
              _currentUser = null;
            } else {
              _currentUser = updatedUser;
            }
          }
        });
      }
    } catch (e) {
      debugPrint('Users realtime apply error: $e');
    }
  }

  void _onTransactionsChange(PostgresChangePayload payload) {
    if (_isSyncing) return;
    try {
      if (payload.eventType == PostgresChangeEvent.delete) {
        final id = (payload.oldRecord['id'] ?? '').toString();
        if (id.isEmpty) return;
        setState(() => _allTransactions.removeWhere((t) => t.id == id));
      } else {
        final tx = AppTransaction.fromJson(payload.newRecord);
        setState(() {
          final idx = _allTransactions.indexWhere((t) => t.id == tx.id);
          if (idx == -1) {
            _allTransactions.add(tx);
          } else {
            _allTransactions[idx] = tx;
          }
        });
      }
    } catch (e) {
      debugPrint('Transactions realtime apply error: $e');
    }
  }

  void _preserveLocalSessionState(UserData local, UserData remote) {
    if (local.isClockedIn && local.clockInStartTime != null) {
      remote.isClockedIn = true;
      remote.clockInStartTime = local.clockInStartTime;
      remote.clockInPenaltyPercent = local.clockInPenaltyPercent;
    }
    if (local.activeInvestment != null && remote.activeInvestment == null) {
      remote.activeInvestment = local.activeInvestment;
    }
  }

  Future<void> _persistLocalSnapshot() async {
    await NgmyLocalCache.persistSnapshot(
      users: _allUsers.map((e) => e.toJson()).toList(),
      transactions: _allTransactions.map((e) => e.toJson()).toList(),
      media: _allMedia.map((e) => e.toJson()).toList(),
      announcements: _allAnnouncements.map((e) => e.toJson()).toList(),
      config: _config.toJson(),
      investmentPlans: _globalPlans.map((e) => e.toJson()).toList(),
      currentUser: _currentUser?.toJson(),
    );
  }

  Future<void> _loadData() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final savedTheme = prefs.getString('theme_mode');
      if (savedTheme == 'light') _themeMode = ThemeMode.light;
      if (savedTheme == 'dark') _themeMode = ThemeMode.dark;
      if (savedTheme == 'system') _themeMode = ThemeMode.system;

      String? safeGet(String key) {
        try {
          final val = prefs.getString(key);
          if (val == null || val.trim().isEmpty || val == "null") return null;
          final trimmed = val.trim();
          // Reject corrupted/binary-like strings (can crash jsonDecode on Windows).
          if (trimmed.contains('\u0000')) {
            prefs.remove(key);
            return null;
          }
          if (!trimmed.startsWith('{') && !trimmed.startsWith('[')) return null;
          return trimmed;
        } catch (_) { return null; }
      }

      _tombstonedMediaIds = await _loadTombstonedMediaIds();

      // 1. Load Local Config & Plans First
      final plansJson = safeGet('investment_plans');
      if (plansJson != null) {
        try {
          final decoded = jsonDecode(plansJson);
          if (decoded is List) {
            _globalPlans = decoded.map((e) => InvestmentPlan.fromJson(e)).toList();
            for (final pl in _globalPlans) {
              pl.applyFixedRoi();
            }
          }
        } catch (_) {}
      }

      final configJson = safeGet('app_config');
      if (configJson != null) {
        try {
          final map = jsonDecode(configJson);
          if (map is Map<String, dynamic>) _config = AppConfig.fromJson(map);
        } catch (_) {}
      }
      final localMediaJson = safeGet('all_media');
      List<MediaPost> localMedia = [];
      if (localMediaJson != null) {
        try {
          localMedia = (jsonDecode(localMediaJson) as List)
              .map((e) => MediaPost.fromJson(e))
              .where((m) => !_tombstonedMediaIds.contains(m.id))
              .toList();
          _allMedia = localMedia;
        } catch (_) {
          prefs.remove('all_media');
        }
      }

      final uLocalEarly = safeGet('all_users');
      if (uLocalEarly != null) {
        try {
          _allUsers = (jsonDecode(uLocalEarly) as List).map((e) => UserData.fromJson(e)).toList();
        } catch (_) {
          prefs.remove('all_users');
        }
      }
      final tLocalEarly = safeGet('all_transactions');
      if (tLocalEarly != null) {
        try {
          _allTransactions = (jsonDecode(tLocalEarly) as List).map((e) => AppTransaction.fromJson(e)).toList();
        } catch (_) {
          prefs.remove('all_transactions');
        }
      }
      final userJsonEarly = safeGet('current_user');
      if (userJsonEarly != null) {
        try {
          final map = jsonDecode(userJsonEarly);
          if (map is Map<String, dynamic>) {
            final localUser = UserData.fromJson(map);
            final index = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == localUser.email.toLowerCase().trim());
            _currentUser = index != -1 ? _allUsers[index] : localUser;
          }
        } catch (_) {}
      }

      final annLocalEarly = safeGet('all_announcements');
      if (annLocalEarly != null) {
        try {
          _allAnnouncements = (jsonDecode(annLocalEarly) as List).map((e) => Announcement.fromJson(e)).toList();
          await _pruneExpiredAnnouncements(updateUi: false);
        } catch (_) {
          prefs.remove('all_announcements');
        }
      }

      if (mounted) {
        _applySystemUiForMode(_effectiveThemeMode);
        setState(() => _isLoading = false);
      }

      // 2. Fetch from Supabase when reachable (slow/offline uses local cache above).
      if (!await ngmyCanReachCloud()) {
        debugPrint('[ngmy] offline or slow network — using cached local data');
        await _persistLocalSnapshot();
        if (mounted) setState(() {});
        return;
      }
      final localUsersBeforeFetch = <String, UserData>{
        for (final u in _allUsers) u.email.toLowerCase().trim(): u,
      };
      final localCurrent = _currentUser;
      await ngmyIgnoreTimeout(() async {
      try {
        final usersData = await supabase.from('users').select();
        if (usersData != null) {
          _allUsers = (usersData as List).map((e) => UserData.fromJson(e)).toList();
          for (final u in _allUsers) {
            final key = u.email.toLowerCase().trim();
            final local = localUsersBeforeFetch[key];
            if (local != null) _preserveLocalSessionState(local, u);
          }
          for (final u in _allUsers) {
            NgmyMediaProfile.normalizeUserMediaFields(u);
          }
        }

        final transData = await supabase.from('transactions').select();
        if (transData != null) {
          _allTransactions = (transData as List).map((e) => AppTransaction.fromJson(e)).toList();
        }

        final mediaData = await supabase.from('media').select();
        if (mediaData != null) {
          final remoteMedia = (mediaData as List).map((e) => MediaPost.fromJson(e)).toList();
          _allMedia = _mergeMediaWithRemote(localMedia, remoteMedia, tombstones: _tombstonedMediaIds);
          await _persistAllMediaLocally();
        }

        final annData = await supabase.from('announcements').select();
        if (annData != null) {
          _allAnnouncements = (annData as List).map((e) => Announcement.fromJson(e)).toList();
          await _pruneExpiredAnnouncements(updateUi: false);
          if (mounted) setState(() {});
        }

        final localStoreListings = List<Map<String, dynamic>>.from(_config.storeListings.map((e) => Map<String, dynamic>.from(e)));
        final localStoreInquiries = List<Map<String, dynamic>>.from(_config.storeInquiries.map((e) => Map<String, dynamic>.from(e)));
        final localGeminiKey = _config.geminiApiKey.trim();
        final localConfigSnapshot = AppConfig.fromJson(_config.toJson());
        final configData = await supabase.from('config').select().maybeSingle();
        if (configData != null) {
          final cfgMap = Map<String, dynamic>.from(configData);
          final next = AppConfig.fromJson(cfgMap);
          _applyRemoteConfigMerge(next, cfgMap, localConfigSnapshot);
          _config = next;
          (_config as dynamic).mediaVirtualProfiles = NgmyVirtualMediaProfiles.ensure(
            cfgMap['mediaVirtualProfiles'] ?? (_config as dynamic).mediaVirtualProfiles,
          );
          _applyRemoteLegalToConfig(_config, cfgMap);
          _mergeStoreListingsIntoConfig(localStoreListings);
          _mergeStoreInquiriesIntoConfig(localStoreInquiries);
          final remoteGemini = _geminiKeyFromMap(cfgMap);
          if (remoteGemini.isNotEmpty) {
            _config.geminiApiKey = remoteGemini;
          } else           if (_config.geminiApiKey.trim().isEmpty && localGeminiKey.isNotEmpty) {
            _config.geminiApiKey = localGeminiKey;
          }
          if (_config.investmentPlans.isNotEmpty) {
            _globalPlans = _investmentPlansFromMaps(_config.investmentPlans);
          }
        }
        await _refreshLegalAndPlansFromCloud(updateUi: false);
        await _refreshPopupsFromCloud(updateUi: false);
        await _reloadStoreFromSupabase();
        await _reloadMediaFromSupabase();
      } catch (e) {
        debugPrint("Supabase Load Error: $e. Falling back to local.");
        final uLocal = safeGet('all_users');
        if (uLocal != null) {
          try {
            _allUsers = (jsonDecode(uLocal) as List).map((e) => UserData.fromJson(e)).toList();
          } catch (_) {
            prefs.remove('all_users');
          }
        }
        final tLocal = safeGet('all_transactions');
        if (tLocal != null) {
          try {
            _allTransactions = (jsonDecode(tLocal) as List).map((e) => AppTransaction.fromJson(e)).toList();
          } catch (_) {
            prefs.remove('all_transactions');
          }
        }
        final mLocal = safeGet('all_media');
        if (mLocal != null) {
          try {
            _allMedia = (jsonDecode(mLocal) as List).map((e) => MediaPost.fromJson(e)).toList();
          } catch (_) {
            prefs.remove('all_media');
          }
        }
      }
      }, timeout: kNgmyCloudLoadTimeout);

      // 3. Handle Current User Session
      final userJson = safeGet('current_user');
      if (userJson != null) {
        try {
          final map = jsonDecode(userJson);
          if (map is Map<String, dynamic>) {
            final localUser = UserData.fromJson(map);
            final index = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == localUser.email.toLowerCase().trim());
            if (index != -1) {
              _currentUser = _allUsers[index];
            } else {
              _currentUser = localUser;
            }
          }
        } catch (_) {}
      }

      for (final u in _allUsers) {
        final computed = ngmyBalanceFromApprovedTransactions(u.email, _allTransactions);
        if (computed > u.accountBalance + 0.001) u.accountBalance = computed;
      }
      if (_currentUser != null) {
        final key = _currentUser!.email.toLowerCase().trim();
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
        if (idx != -1) {
          _preserveLocalSessionState(_currentUser!, _allUsers[idx]);
          _currentUser = _allUsers[idx];
        }
      } else if (localCurrent != null) {
        final key = localCurrent.email.toLowerCase().trim();
        final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == key);
        if (idx != -1) {
          _preserveLocalSessionState(localCurrent, _allUsers[idx]);
          _currentUser = _allUsers[idx];
        }
      }

      // Ensure admins are updated
      final admins = ['kbpabloqr@gmail.com', 'ngumoyaking@gmail.com', 'appbusiness321@gmail.com', 'appbusiness84@gmail.com'];
      for (var u in _allUsers) if (admins.contains(u.email.toLowerCase().trim())) u.isAdmin = true;

      for (final u in _allUsers) {
        NgmyMediaProfile.normalizeUserMediaFields(u);
      }
      if (_currentUser != null) {
        NgmyMediaProfile.normalizeUserMediaFields(_currentUser);
      }
      (_config as dynamic).mediaVirtualProfiles = NgmyVirtualMediaProfiles.ensure((_config as dynamic).mediaVirtualProfiles);
      NgmyMediaProfile.pruneExpiredStoriesAllUsers(_allUsers);

      _purgeExpiredSoldStoreListings();
      await _pruneExpiredAnnouncements(updateUi: false);
      for (final o in _config.storeOrders) {
        final id = (o['id'] ?? '').toString();
        if (id.isNotEmpty) _seenRealtimeStoreOrderIds.add(id);
      }
      await _persistLocalSnapshot();
    } catch (e) { debugPrint("General load error: $e"); }
    if (mounted) setState(() {});
  }

  bool _isMissingTableError(Object error, String table) {
    return error.toString().contains("Could not find the table 'public.$table'");
  }

  Future<void> _safeUpsertRows(String table, List<Map<String, dynamic>> rows) async {
    if (rows.isEmpty) return;
    if (_disabledSupabaseTables.contains(table)) return;

    final working = rows.map((e) => Map<String, dynamic>.from(e)).toList();
    final removed = <String>{};

    for (int i = 0; i < 12; i++) {
      try {
        await supabase.from(table).upsert(working).timeout(kNgmyCloudWriteTimeout);
        if (removed.isNotEmpty) {
          debugPrint('[$table] synced with removed columns: ${removed.join(', ')}');
        }
        return;
      } catch (e) {
        if (_isMissingTableError(e, table)) {
          _disabledSupabaseTables.add(table);
          debugPrint('[$table] table missing in Supabase. Local save continues.');
          return;
        }
        final missing = _missingColumnFromError(e);
        if (missing != null && missing.isNotEmpty) {
          removed.add(missing);
          for (final row in working) {
            row.remove(missing);
          }
          continue;
        }
        debugPrint('[$table] sync error: $e');
        return;
      }
    }
  }

  Future<void> _saveData() async {
    _isSyncing = true;
    _maintainStoreOrders(_config.storeOrders);
    var ordersSnapshot = List<Map<String, dynamic>>.from(
      _config.storeOrders.map((e) => Map<String, dynamic>.from(e)),
    );
    final online = await ngmyCanReachCloud();
    try {
      final prefs = await SharedPreferences.getInstance();

      // Normalize/merge users BEFORE syncing so stale duplicates can't overwrite
      // fresh account state (e.g., activeInvestment disappearing after purchase).
      _allUsers.removeWhere((u) => u.email.trim().isEmpty);
      final mergedByEmail = <String, UserData>{};
      for (final u in _allUsers) {
        final key = u.email.toLowerCase().trim();
        if (key.isEmpty) continue;
        mergedByEmail[key] = u;
      }
      if (_currentUser != null) {
        final key = _currentUser!.email.toLowerCase().trim();
        if (key.isNotEmpty) {
          mergedByEmail[key] = _currentUser!;
        }
      }
      _allUsers = mergedByEmail.values.toList();

      for (final u in _allUsers) {
        NgmyMediaProfile.normalizeUserMediaFields(u);
      }
      if (_currentUser != null) NgmyMediaProfile.normalizeUserMediaFields(_currentUser);
      NgmyMediaProfile.pruneExpiredStoriesAllUsers(_allUsers);

      if (_currentUser != null) {
        final email = _currentUser!.email.toLowerCase().trim();
        if (email.isNotEmpty) {
          final merged = mergedByEmail[email];
          if (merged != null) _currentUser = merged;
          await prefs.setString('current_user', jsonEncode(_currentUser!.toJson()));
        }
      }

      // Always persist locally first so slow/offline Wi‑Fi never blocks the UI.
      await prefs.setString('all_transactions', jsonEncode(_allTransactions.map((e) => e.toJson()).toList()));
      await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));
      await prefs.setString('investment_plans', jsonEncode(_globalPlans.map((e) => e.toJson()).toList()));
      await prefs.setString('app_config', jsonEncode(_config.toJson()));
      await prefs.setString('all_media', jsonEncode(_allMedia.map((e) => e.toJson()).toList()));
      await prefs.setString('all_announcements', jsonEncode(_allAnnouncements.map((e) => e.toJson()).toList()));
      await _persistLocalSnapshot();

      if (online) {
      await ngmyIgnoreTimeout(() async {
      // Sync all transactions to Supabase
      if (_allTransactions.isNotEmpty) {
        await _safeUpsertRows(
          'transactions',
          _allTransactions.map((e) => e.toJson()).map((e) => Map<String, dynamic>.from(e)).toList(),
        );
      }

      // Sync all users to Supabase (deduped list)
      if (_allUsers.isNotEmpty) {
        await _safeUpsertRows(
          'users',
          _allUsers.map((e) => e.toJson()).map((e) => Map<String, dynamic>.from(e)).toList(),
        );
      }

      // Do not bulk-upsert media here — it resurrected deleted posts from stale cache.
        await _pruneStaleMediaAgainstCloud();

        await _pruneExpiredAnnouncements(updateUi: false);
        if (_allAnnouncements.isNotEmpty) {
          await _safeUpsertRows(
            'announcements',
            _allAnnouncements.map((e) => e.toJson()).map((e) => Map<String, dynamic>.from(e)).toList(),
          );
        }

        await _reloadStoreFromSupabase();
        if (_maintainStoreOrders(_config.storeOrders)) {
          await _pushStoreOrdersToSupabase(_config.storeOrders);
        }
        await _syncStoreToSupabase();
        if (_currentUser?.isAdmin == true) {
          _config.investmentPlans = _investmentPlansToMaps(_globalPlans);
          await _persistInvestmentPlansToCloud(_config.investmentPlans);
        }
        final configRow = await _configRowForSupabaseUpsert(
          config: _config,
          isAdmin: _currentUser?.isAdmin ?? false,
        );
        configRow['storeListings'] = _config.storeListings;
        configRow['storeInquiries'] = _config.storeInquiries;
        configRow['storeOrders'] = _config.storeOrders;
        _config.storeOrders = List<Map<String, dynamic>>.from(
          _config.storeOrders.map((e) => Map<String, dynamic>.from(e)),
        );
        configRow['helpHelperApplications'] = _config.helpHelperApplications;
        configRow['helpRequests'] = _config.helpRequests;
        configRow['helpBusinesses'] = _config.helpBusinesses;
        if (_currentUser?.isAdmin == true) {
          configRow['ngmyPopups'] = _config.ngmyPopups.map((e) => Map<String, dynamic>.from(e)).toList();
          configRow['ngmyVideoPopups'] = _config.ngmyVideoPopups.map((e) => Map<String, dynamic>.from(e)).toList();
          await _persistNgmyPopupsToCloud(_config.ngmyPopups, _config.ngmyVideoPopups);
        }
        await _safeUpsertRows('config', [configRow]);
        await _persistCriticalConfigFields(_config);
      }, timeout: const Duration(seconds: 28));
      } else {
        _config.storeOrders = ordersSnapshot;
      }

    } catch (e) { debugPrint("Save error: $e"); }
    finally {
      Future.delayed(const Duration(milliseconds: 800), () => _isSyncing = false);
    }
  }

  Future<void> _upsertAnnouncement(Announcement ann) async {
    await _upsertAnnouncementRowSafe(Map<String, dynamic>.from(ann.toJson()));
  }

  Future<void> _deleteAnnouncementById(String id) async {
    try {
      await supabase.from('announcements').delete().eq('id', id);
    } catch (e) {
      debugPrint('Announcement delete error: $e');
    }
  }

  Future<void> _deleteAnnouncementStorageMedia(Announcement ann) async {
    for (final raw in [ann.imageUrl, ann.videoUrl]) {
      final url = raw?.trim() ?? '';
      if (url.isEmpty) continue;
      final ref = _parseSupabaseStorageRef(url);
      if (ref == null) continue;
      try {
        await supabase.storage.from(ref.bucket).remove([ref.path]);
      } catch (e) {
        debugPrint('[news] storage delete ${ref.path}: $e');
      }
    }
  }

  Future<void> _pruneExpiredAnnouncements({bool updateUi = true}) async {
    final expired = _allAnnouncements.where((a) => NgmyNewsRetention.isExpired(a.timestamp)).toList();
    if (expired.isEmpty) return;
    for (final ann in expired) {
      await _deleteAnnouncementStorageMedia(ann);
      await _deleteAnnouncementById(ann.id);
    }
    void apply() {
      _allAnnouncements.removeWhere((a) => NgmyNewsRetention.isExpired(a.timestamp));
    }
    if (updateUi && mounted) {
      setState(apply);
    } else {
      apply();
    }
    debugPrint('[news] pruned ${expired.length} announcement(s) older than ${NgmyNewsRetention.weekdayRetention} weekdays');
  }

  Future<void> _clearAllAnnouncementsRemote() async {
    try {
      await supabase.from('announcements').delete().neq('id', '');
    } catch (e) {
      debugPrint('Clear all announcements error: $e');
    }
  }

  @override Widget build(BuildContext context) {
    if (_isLoading) return const MaterialApp(debugShowCheckedModeBanner: false, home: Scaffold(body: Center(child: CircularProgressIndicator())));

    final isDarkMode = _effectiveThemeMode == ThemeMode.dark;
    final style = isDarkMode
        ? const SystemUiOverlayStyle(
            statusBarColor: Color(0xFF121212),
            statusBarIconBrightness: Brightness.light,
            statusBarBrightness: Brightness.dark,
            systemNavigationBarColor: Color(0xFF121212),
            systemNavigationBarIconBrightness: Brightness.light,
          )
        : const SystemUiOverlayStyle(
            statusBarColor: Colors.white,
            statusBarIconBrightness: Brightness.dark,
            statusBarBrightness: Brightness.light,
            systemNavigationBarColor: Colors.white,
            systemNavigationBarIconBrightness: Brightness.dark,
          );

    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: style,
      child: MaterialApp(
        navigatorKey: ngmyRootNavigatorKey,
        navigatorObservers: [NgmyHistoryObserver()],
        title: 'NGMY', debugShowCheckedModeBanner: false,
        theme: ThemeData(
          useMaterial3: true,
          colorSchemeSeed: const Color(0xFF00B25A),
          brightness: Brightness.light,
          scaffoldBackgroundColor: Colors.white,
          cardColor: Colors.white,
          pageTransitionsTheme: const PageTransitionsTheme(
            builders: {
              TargetPlatform.android: CupertinoPageTransitionsBuilder(),
              TargetPlatform.iOS: CupertinoPageTransitionsBuilder(),
              TargetPlatform.macOS: CupertinoPageTransitionsBuilder(),
              TargetPlatform.windows: CupertinoPageTransitionsBuilder(),
              TargetPlatform.linux: CupertinoPageTransitionsBuilder(),
            },
          ),
          appBarTheme: const AppBarTheme(
            systemOverlayStyle: SystemUiOverlayStyle(
              statusBarColor: Colors.white,
              statusBarIconBrightness: Brightness.dark,
              statusBarBrightness: Brightness.light,
            ),
            backgroundColor: Colors.white,
            elevation: 0,
          ),
        ),
        darkTheme: ThemeData(
          useMaterial3: true,
          colorSchemeSeed: const Color(0xFFBB86FC),
          brightness: Brightness.dark,
          scaffoldBackgroundColor: const Color(0xFF121212),
          cardColor: const Color(0xFF1E1E1E),
          pageTransitionsTheme: const PageTransitionsTheme(
            builders: {
              TargetPlatform.android: CupertinoPageTransitionsBuilder(),
              TargetPlatform.iOS: CupertinoPageTransitionsBuilder(),
              TargetPlatform.macOS: CupertinoPageTransitionsBuilder(),
              TargetPlatform.windows: CupertinoPageTransitionsBuilder(),
              TargetPlatform.linux: CupertinoPageTransitionsBuilder(),
            },
          ),
          appBarTheme: const AppBarTheme(
            systemOverlayStyle: SystemUiOverlayStyle(
              statusBarColor: Color(0xFF121212),
              statusBarIconBrightness: Brightness.light,
              statusBarBrightness: Brightness.dark,
            ),
            backgroundColor: Color(0xFF121212),
            elevation: 0,
          ),
        ),
        themeMode: _effectiveThemeMode,
        builder: (context, child) {
          final content = child ?? const SizedBox.shrink();
          if (kIsWeb && Theme.of(context).brightness == Brightness.light) {
            ngmyApplyWebStatusBarStyle(lightMode: true);
            return ColoredBox(color: Colors.white, child: content);
          }
          return content;
        },
        home: _currentUser == null
            ? AuthScreen(
                allUsers: _allUsers,
                config: _config,
                onGoogleLogin: () => _startOAuthSignIn(OAuthProvider.google),
                onGithubLogin: () => _startOAuthSignIn(OAuthProvider.github),
                onResetPasswordByEmail: (email, newHash) async {
                  final emailNorm = email.toLowerCase().trim();
                  debugPrint('[ResetPW] Starting reset for $emailNorm');
                  _isSyncing = true;

                  try {
                    final result = await supabase
                        .from('users')
                        .update({'passwordHash': newHash})
                        .eq('email', emailNorm)
                        .select();

                    if (result.isEmpty) {
                       await supabase.from('users').insert({
                         'email': emailNorm,
                         'passwordHash': newHash,
                         'username': emailNorm.split('@').first,
                       });
                    }

                    final idx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == emailNorm);
                    if (mounted) {
                      setState(() {
                        if (idx != -1) {
                          _allUsers[idx].passwordHash = newHash;
                        } else {
                          _allUsers.add(UserData(email: emailNorm, passwordHash: newHash, username: emailNorm.split('@').first));
                        }
                      });
                    }

                    final prefs = await SharedPreferences.getInstance();
                    await prefs.setString('all_users', jsonEncode(_allUsers.map((e) => e.toJson()).toList()));

                    _isSyncing = false;
                    return true;
                  } catch (e) {
                    _isSyncing = false;
                    return false;
                  }
                },
                onAuthComplete: (e, p, u, passwordHash, isLogin) async {
                  final admins = ['kbpabloqr@gmail.com', 'ngumoyaking@gmail.com', 'appbusiness321@gmail.com', 'appbusiness84@gmail.com'];
                  final email = e.toLowerCase().trim();

                  if (isLogin) {
                    final index = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
                    if (index != -1) {
                      _allUsers[index].passwordHash = passwordHash;
                      setState(() => _currentUser = _allUsers[index]);
                    }
                  } else {
                    final user = UserData(email: email, phone: p, username: u, isAdmin: admins.contains(email), passwordHash: passwordHash);
                    setState(() {
                      _currentUser = user;
                      _allUsers.add(user);
                    });
                  }
                  await _saveData();
                },
              )
            : MainScreen(
                user: _currentUser!, allTransactions: _allTransactions, allUsers: _allUsers, globalPlans: _globalPlans,
                allMedia: _allMedia,
                allAnnouncements: _allAnnouncements,
                config: _config,
                onThemeChanged: (m) => _setThemeMode(m), currentThemeMode: _themeMode,
                onLogout: () async {
                  try {
                    final p = await SharedPreferences.getInstance();
                    await p.remove('current_user');
                  } catch (_) {}
                  setState(() => _currentUser = null);
                },
                onDataChanged: () => _saveData(),
                onAddTransaction: (t) {
                  setState(() {
                    _allTransactions.add(t);
                    final userKey = t.userEmail.toLowerCase().trim();
                    final userIdx = _allUsers.indexWhere((u) => u.email.toLowerCase().trim() == userKey);
                    if (userIdx != -1) {
                      ngmyApplyApprovedTransactionToBalance(_allUsers[userIdx], t);
                      if (_currentUser != null && _currentUser!.email.toLowerCase().trim() == userKey) {
                        _currentUser = _allUsers[userIdx];
                      }
                    }
                    final userTrans = _allTransactions.where((tx) => tx.userEmail == t.userEmail).toList();
                    if (userTrans.length > 30) {
                      userTrans.sort((a, b) => a.timestamp.compareTo(b.timestamp));
                      final toRemove = userTrans.take(userTrans.length - 30).toList();
                      for (var old in toRemove) {
                        _allTransactions.removeWhere((tx) => tx.id == old.id);
                        supabase.from('transactions').delete().eq('id', old.id).then((_) {}).catchError((_) {});
                      }
                    }
                  });
                  _saveData();
                  _notifyTransactionEvent(t);
                },
                onProcessTransaction: (t, approve) { setState(() {
                  t.status = approve ? TransactionStatus.approved : TransactionStatus.rejected;
                  final targetIndex = _allUsers.indexWhere((u) => u.email == t.userEmail);
                  if (targetIndex == -1) return;
                  final targetUser = _allUsers[targetIndex];
                  final details = t.sourceDetails ?? '';
                  final isInvestmentRequest = t.type == TransactionType.deposit && isInvestmentRequestDetails(details);
                  if (approve) {
                    if (isInvestmentRequest) {
                      final meta = parseInvestmentRequestDetails(details);
                      final planName = (meta['plan'] ?? '').trim();
                      final planAmount = double.tryParse(meta['amount'] ?? '');
                      final planRoi = double.tryParse(meta['roi'] ?? '');
                      if (planName.isNotEmpty && planAmount != null && planRoi != null) {
                        targetUser.activeInvestment = ActiveInvestment(
                          name: planName,
                          amount: planAmount,
                          dailyROI: InvestmentPlan.fixedRoi,
                          purchaseDate: DateTime.now(),
                          daysClockedIn: 0,
                          totalEarned: 0.0,
                        );
                        targetUser.pendingInvestmentName = null;
                        targetUser.pendingInvestmentAmount = null;
                        targetUser.pendingInvestmentRoi = null;
                        _allTransactions.add(
                          AppTransaction(
                            id: '${DateTime.now()}-invest',
                            userEmail: t.userEmail,
                            amount: t.amount,
                            type: TransactionType.adminRemove,
                            method: PaymentMethod.system,
                            sourceDetails: 'Investment plan purchase/upgrade: $planName',
                            status: TransactionStatus.approved,
                            timestamp: DateTime.now(),
                          ),
                        );
                      }
                    } else if (t.type == TransactionType.deposit || t.type == TransactionType.adminAdd || t.type == TransactionType.reimbursement) {
                      targetUser.accountBalance += t.amount;
                    }
                  } else {
                    if (isInvestmentRequest) {
                      targetUser.pendingInvestmentName = null;
                      targetUser.pendingInvestmentAmount = null;
                      targetUser.pendingInvestmentRoi = null;
                    } else if (t.type == TransactionType.withdrawal) {
                      targetUser.accountBalance += t.amount;
                    }
                  }
                  if (_currentUser != null && _currentUser!.email == t.userEmail) _currentUser = targetUser;
                }); _saveData(); _notifyTransactionEvent(t, statusChanged: true); },
                onAddPlan: (p) {
                  setState(() {
                    _globalPlans.add(p);
                    p.applyFixedRoi();
                    _globalPlans.sort((a, b) => a.price.compareTo(b.price));
                    _config.investmentPlans = _investmentPlansToMaps(_globalPlans);
                  });
                  unawaited(() async {
                    await _persistInvestmentPlansToCloud(_config.investmentPlans);
                    await _saveData();
                  }());
                },
                onPostMedia: (post) {
                  _tombstonedMediaIds.remove(post.id);
                  setState(() {
                    _allMedia.removeWhere((m) => m.id == post.id);
                    _allMedia.insert(0, post);
                  });
                  unawaited(() async {
                    await _persistTombstonedMediaIds(_tombstonedMediaIds);
                    await _persistAllMediaLocally();
                    await Future.delayed(const Duration(seconds: 1));
                    await _reloadMediaFromSupabase();
                  }());
                },
                onRefreshMediaFromCloud: _reloadMediaFromSupabase,
                onDeleteMedia: _deleteMediaPostGlobally,
                onPruneMedia: _pruneDeletedMediaPost,
                onSaveLegalContent: _saveLegalContentToSupabase,
                onSavePopups: _savePopupsSettingsToCloud,
                onUploadPopupVideo: _uploadPopupVideoRef,
                onAddAnnouncement: (ann) {
                  setState(() => _allAnnouncements.insert(0, ann));
                  _upsertAnnouncement(ann);
                  _saveData();
                },
              onDeleteAnnouncement: (id) {
                setState(() => _allAnnouncements.removeWhere((a) => a.id == id));
                _deleteAnnouncementById(id);
                _saveData();
              },
              onClearAllAnnouncements: () {
                setState(() => _allAnnouncements.clear());
                _clearAllAnnouncementsRemote();
                _saveData();
              },
            ),
      ),
    );
  }
}

