  @override State<MainScreen> createState() => _MainScreenState();
}
class _MainScreenState extends State<MainScreen> with WidgetsBindingObserver {
  int _idx = 0; Timer? _t; int _syncCounter = 0;
  bool _clockPayoutLocked = false;
  DateTime? _clockPayoutDay;
  bool _offline = false;
  Timer? _onlineCheck;

  void _runScheduledPopups() {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      NgmyPopupOrchestrator.handleAppOpen(
        context,
        popupsRaw: widget.config.ngmyPopups,
        videoPopupsRaw: widget.config.ngmyVideoPopups,
        userEmail: widget.user.email,
      );
    });
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) _runScheduledPopups();
  }

  Future<void> _refreshOnlineStatus() async {
    final online = await ngmyCanReachCloud();
    if (!mounted) return;
    final nextOffline = !online;
    if (nextOffline != _offline) setState(() => _offline = nextOffline);
  }

  Future<void> _showOfficialNotice({
    required String title,
    required String message,
    bool isError = false,
  }) async {
    if (!mounted) return;
    final accent = isError ? const Color(0xFFEF4444) : const Color(0xFF22C55E);
    await showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (ctx) => Dialog(
        backgroundColor: Colors.transparent,
        insetPadding: const EdgeInsets.symmetric(horizontal: 22, vertical: 24),
        child: Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: const Color(0xFF0B1020).withOpacity(0.96),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: accent.withOpacity(0.55)),
            boxShadow: [BoxShadow(color: accent.withOpacity(0.24), blurRadius: 16, offset: const Offset(0, 6))],
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Row(
                children: [
                  Icon(isError ? Icons.info_outline_rounded : Icons.check_circle_outline_rounded, color: accent),
                  const SizedBox(width: 8),
                  Expanded(child: Text(title, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w800, fontSize: 16))),
                ],
              ),
              const SizedBox(height: 10),
              Text(message, style: const TextStyle(color: Colors.white70, fontSize: 13)),
              const SizedBox(height: 14),
              Align(
                alignment: Alignment.centerRight,
                child: FilledButton(
                  onPressed: () => Navigator.pop(ctx),
                  style: FilledButton.styleFrom(backgroundColor: accent, foregroundColor: Colors.white),
                  child: const Text('OK'),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  Future<void> _showLateClockInDialog(double penalty, DateTime clockTime) async {
    if (!mounted) return;
    await showDialog<void>(
      context: context,
      barrierDismissible: true,
      builder: (ctx) => _LateClockInDialog(penaltyPercent: penalty, clockTime: clockTime),
    );
  }

  @override
  void didUpdateWidget(MainScreen oldWidget) {
    super.didUpdateWidget(oldWidget);
    final oldSig = jsonEncode({'p': oldWidget.config.ngmyPopups, 'v': oldWidget.config.ngmyVideoPopups});
    final newSig = jsonEncode({'p': widget.config.ngmyPopups, 'v': widget.config.ngmyVideoPopups});
    if (oldSig != newSig) _runScheduledPopups();
  }

  @override void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    NgmyPopupOrchestrator.resolveVideoUrl = _resolveSupabaseStorageUrlResilient;
    _ngmyApplyMidnightClockReset(widget.user);
    _refreshOnlineStatus();
    _runScheduledPopups();
    _onlineCheck = Timer.periodic(const Duration(seconds: 8), (_) => _refreshOnlineStatus());
    _t = Timer.periodic(const Duration(seconds: 1), (t) {
      if (widget.user.forceLogout) { widget.user.forceLogout = false; widget.onDataChanged(); widget.onLogout(); return; }
      _ngmyApplyMidnightClockReset(widget.user);
      final now = DateTime.now();
      if (_clockPayoutDay == null || !_ngmySameCalendarDay(_clockPayoutDay, now)) {
        _clockPayoutDay = now;
        _clockPayoutLocked = false;
      }
      if (widget.user.isClockedIn) {
        if (_ngmySameCalendarDay(widget.user.lastClockInEarningsDate, now)) {
          widget.user.isClockedIn = false;
          widget.user.clockInStartTime = null;
          widget.onDataChanged();
          return;
        }
        double earned = 0;
        bool completed = false;
        final goal = widget.user.todayDailyGoal;
        if (!_clockPayoutLocked && goal > 0 && widget.user.currentTodayEarnings >= goal) {
          _clockPayoutLocked = true;
          earned = goal;
          setState(() {
            widget.user.accountBalance += earned;
            widget.user.totalProfit += earned;
            widget.user.activeInvestment!.totalEarned += earned;
            widget.user.activeInvestment!.daysClockedIn++;
            widget.user.isClockedIn = false;
            widget.user.clockInStartTime = null;
            widget.user.clockInPenaltyPercent = 0;
            widget.user.lastClockInDate = now;
            widget.user.lastClockInEarningsDate = now;
            completed = true;
          });
        }

        if (completed) {
          if (earned > 0) {
            widget.onAddTransaction(AppTransaction(
              id: '${now.millisecondsSinceEpoch}_clock',
              userEmail: widget.user.email,
              amount: earned,
              type: TransactionType.reimbursement,
              method: PaymentMethod.system,
              sourceDetails: 'Clock-in daily earnings',
              status: TransactionStatus.approved,
              timestamp: now,
            ));
          }
          widget.onDataChanged(); // Immediate sync on completion
        } else {
          // Throttle cloud sync to every 30 seconds to prevent "quick/stuttery" UI
          _syncCounter++;
          if (_syncCounter >= 30) {
            _syncCounter = 0;
            widget.onDataChanged();
          }
        }
      }
    });
  }
  @override void dispose() { WidgetsBinding.instance.removeObserver(this); _t?.cancel(); _onlineCheck?.cancel(); super.dispose(); }

  @override Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final sorted = List<AppTransaction>.from(widget.allTransactions)..sort((a, b) => b.timestamp.compareTo(a.timestamp));
    final pages = [
      HomeScreen(user: widget.user, onClockIn: () async {
        final now = DateTime.now();
        _ngmyApplyMidnightClockReset(widget.user);
        if (widget.user.activeInvestment == null) {
          _showOfficialNotice(
            title: 'Plan Required',
            message: 'You need an active investment plan to start clock-in earnings.',
            isError: true,
          );
          return;
        }
        if (_ngmyIsWeekend(now)) {
          await NgmyWeekendClockOverlay.show(context);
          return;
        }
        if (_ngmySameCalendarDay(widget.user.lastClockInEarningsDate, now)) {
          _showOfficialNotice(
            title: 'Already Earned Today',
            message: 'You have already earned today\'s clock-in payout. Check back tomorrow after midnight.',
            isError: true,
          );
          return;
        }
        if (widget.user.isClockedIn) {
          _showOfficialNotice(
            title: 'Session Active',
            message: 'Your clock-in session is already running.',
            isError: true,
          );
          return;
        }
        if (now.hour >= 12) {
          _showOfficialNotice(
            title: 'Clock-In Window Closed',
            message: 'You must clock in before 12:00 PM (noon). The window opens again at midnight.',
            isError: true,
          );
          return;
        }
        final penalty = _ngmyClockInLatePenaltyPercent(now);
        setState(() {
          widget.user.isClockedIn = true;
          widget.user.clockInStartTime = now;
          widget.user.clockInPenaltyPercent = penalty;
          _clockPayoutLocked = false;
        });
        widget.onDataChanged();
        await _showLateClockInDialog(penalty, now);
      }, allTransactions: sorted, onProcess: widget.onProcessTransaction, allUsers: widget.allUsers, globalPlans: widget.globalPlans, onAddPlan: widget.onAddPlan, onAddTransaction: widget.onAddTransaction, onDataChanged: widget.onDataChanged, config: widget.config, allMedia: widget.allMedia, allAnnouncements: widget.allAnnouncements, onAddAnnouncement: widget.onAddAnnouncement, onDeleteAnnouncement: widget.onDeleteAnnouncement, onClearAllAnnouncements: widget.onClearAllAnnouncements, onSaveLegalContent: widget.onSaveLegalContent, onSavePopups: widget.onSavePopups, onUploadPopupVideo: widget.onUploadPopupVideo),
      InvestScreen(user: widget.user, plans: widget.globalPlans, onInvest: (n, p, r, cost) {
        if (cost <= 0) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('This plan is already active.')),
          );
          return;
        }
        if (widget.user.accountBalance >= cost) {
          setState(() {
            widget.user.accountBalance -= cost;
            widget.user.activeInvestment = ActiveInvestment(
              name: n,
              amount: p,
              dailyROI: InvestmentPlan.fixedRoi,
              purchaseDate: DateTime.now(),
              daysClockedIn: 0,
              totalEarned: 0.0,
            );
            widget.user.pendingInvestmentName = null;
            widget.user.pendingInvestmentAmount = null;
            widget.user.pendingInvestmentRoi = null;
          });
          widget.onAddTransaction(
            AppTransaction(
              id: 'invest_buy_${DateTime.now().microsecondsSinceEpoch}',
              userEmail: widget.user.email,
              amount: cost,
              type: TransactionType.adminRemove,
              method: PaymentMethod.system,
              sourceDetails: 'Direct investment buy: $n',
              status: TransactionStatus.approved,
              timestamp: DateTime.now(),
            ),
          );
          widget.onDataChanged();
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text('Plan purchased: $n')),
          );
          return;
        }
        setState(() {
          widget.user.pendingInvestmentName = n;
          widget.user.pendingInvestmentAmount = p;
          widget.user.pendingInvestmentRoi = r;
        });
        widget.onDataChanged();
        NgmyNavigator.push(
          context,
          SubmitPaymentPage(
            user: widget.user,
            amount: cost,
            onAdd: widget.onAddTransaction,
            config: widget.config,
            requestTitle: 'Submit Investment Request',
            successHint: 'Your investment request was sent to admin for approval.',
            requestKind: 'investment',
            investmentPlanName: n,
            investmentPlanAmount: p,
            investmentPlanRoi: r,
          ),
        );
      }),
      WalletScreen(user: widget.user, transactions: sorted.where((t) => t.userEmail == widget.user.email).take(30).toList(), onAdd: widget.onAddTransaction, config: widget.config, onDataChanged: widget.onDataChanged),
      NgmyHubScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        allTransactions: sorted,
        onAddTransaction: widget.onAddTransaction,
        onDataChanged: widget.onDataChanged,
        config: widget.config,
      ),
      MediaHubScreen(
        user: widget.user,
        allUsers: widget.allUsers,
        allMedia: widget.allMedia,
        config: widget.config,
        onPost: widget.onPostMedia,
        onDataChanged: widget.onDataChanged,
        onAddTransaction: widget.onAddTransaction,
        onRefreshFromCloud: widget.onRefreshMediaFromCloud,
        onDeleteMedia: widget.onDeleteMedia,
        onPruneMedia: widget.onPruneMedia,
      ),
      StatsScreen(user: widget.user, transactions: sorted),
      ProfileScreen(user: widget.user, allUsers: widget.allUsers, config: widget.config, onThemeChanged: widget.onThemeChanged, currentThemeMode: widget.currentThemeMode, onLogout: widget.onLogout, onDataChanged: widget.onDataChanged, onAddTransaction: widget.onAddTransaction),
    ];
    return AnnotatedRegion<SystemUiOverlayStyle>(
      value: isDark
          ? const SystemUiOverlayStyle(
              statusBarColor: Color(0xFF121212),
              statusBarIconBrightness: Brightness.light,
              statusBarBrightness: Brightness.dark,
              systemNavigationBarColor: Colors.transparent,
              systemNavigationBarIconBrightness: Brightness.light,
            )
          : const SystemUiOverlayStyle(
              statusBarColor: Colors.white,
              statusBarIconBrightness: Brightness.dark,
              statusBarBrightness: Brightness.light,
              systemNavigationBarColor: Colors.transparent,
              systemNavigationBarIconBrightness: Brightness.dark,
            ),
      child: Scaffold(
        extendBody: true,
        backgroundColor: Theme.of(context).scaffoldBackgroundColor,
        body: Stack(
          children: [
            IndexedStack(
              index: _idx,
              sizing: StackFit.expand,
              children: pages,
            ),
            if (_offline)
              Positioned(
                top: 0,
                left: 0,
                right: 0,
                child: SafeArea(
                  bottom: false,
                  child: Container(
                    margin: const EdgeInsets.fromLTRB(12, 6, 12, 0),
                    padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                    decoration: BoxDecoration(
                      color: const Color(0xFF7C3AED).withOpacity(0.92),
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: const Row(
                      children: [
                        Icon(Icons.wifi_off_rounded, color: Colors.white, size: 18),
                        SizedBox(width: 8),
                        Expanded(
                          child: Text(
                            'Offline or slow connection — using data saved on this device.',
                            style: TextStyle(color: Colors.white, fontSize: 12, fontWeight: FontWeight.w600),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
          ],
        ),
        bottomNavigationBar: Material(
          type: MaterialType.transparency,
          elevation: 0,
          color: Colors.transparent,
          child: _buildBottomNavBar(),
        ),
      ),
    );
  }

  Widget _buildBottomNavBar() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
      child: SafeArea(
        top: false,
        child: NgmySculptedBottomNavFrame(
