  Widget _nav(int i, IconData icon) => Expanded(
        child: Material(
          color: Colors.transparent,
          child: InkWell(
            onTap: () {
              setState(() => _idx = i);
              if (i == 4) unawaited(widget.onRefreshMediaFromCloud?.call());
            },
            customBorder: const CircleBorder(),
            child: SizedBox(
              height: NgmyBottomNavMetrics.frameHeight,
              child: Center(
                child: Icon(
                  icon,
