  Widget _adminUsers(bool isDark) {
    final q = _query.trim().toLowerCase();
    final filtered = widget.allUsers.where((u) => _userMatchesQuery(u, q)).toList()
      ..sort((a, b) => a.username.compareTo(b.username));
    if (_selectedUserEmail != null) {
      UserData? selected;
      for (final x in widget.allUsers) {
        if (x.email.toLowerCase() == _selectedUserEmail!.toLowerCase()) {
          selected = x;
          break;
        }
      }
      if (selected != null) return _adminUserDetail(selected, isDark);
      _selectedUserEmail = null;
    }
    final workerApps = List<Map<String, dynamic>>.from(
      widget.config.jobWorkerApplications.map((e) => Map<String, dynamic>.from(e)),
    );
    final pendingApps = workerApps.where((a) => (a['status'] ?? 'pending') == 'pending').toList();
    final panelBg = isDark ? const Color(0xFF1C1F2E) : Colors.white;
    return Column(children: [
      Padding(
        padding: const EdgeInsets.all(15),
        child: TextField(
          controller: _search,
          style: TextStyle(color: isDark ? Colors.white : Colors.black),
          decoration: InputDecoration(
            hintText: 'Search by name, email, or account ID...',
            hintStyle: TextStyle(color: isDark ? Colors.white38 : Colors.grey),
            prefixIcon: Icon(Icons.search, color: isDark ? Colors.white38 : Colors.grey),
            filled: true,
            fillColor: panelBg,
            border: OutlineInputBorder(borderRadius: BorderRadius.circular(15), borderSide: BorderSide.none),
          ),
          onChanged: (v) => setState(() => _query = v.toLowerCase()),
        ),
      ),
      if (pendingApps.isNotEmpty)
        Container(
          margin: const EdgeInsets.fromLTRB(15, 0, 15, 10),
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: panelBg,
            borderRadius: BorderRadius.circular(12),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text('Worker Applications', style: TextStyle(fontWeight: FontWeight.bold)),
              const SizedBox(height: 8),
              ...pendingApps.map((app) {
                final email = (app['userEmail'] ?? '').toString().toLowerCase().trim();
                final userIndex = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
                return Container(
                  margin: const EdgeInsets.only(bottom: 8),
                  padding: const EdgeInsets.all(10),
                  decoration: BoxDecoration(
                    color: isDark ? Colors.black26 : const Color(0xFFF7FAFF),
                    borderRadius: BorderRadius.circular(10),
                  ),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text('${app['username'] ?? 'User'} • ${app['userEmail'] ?? ''}', style: const TextStyle(fontWeight: FontWeight.w700)),
                      if ((app['note'] ?? '').toString().trim().isNotEmpty) ...[
                        const SizedBox(height: 4),
                        Text((app['note'] ?? '').toString()),
                      ],
                      const SizedBox(height: 6),
                      Row(
                        children: [
                          ElevatedButton(
                            onPressed: () {
                              app['status'] = 'approved';
                              app['reviewedAt'] = DateTime.now().toIso8601String();
                              widget.config.jobWorkerApplications = workerApps;
                              if (userIndex != -1) {
                                widget.allUsers[userIndex].isApprovedWorker = true;
                                widget.allUsers[userIndex].status = 'verified';
                              }
                              widget.onDataChanged();
                              setState(() {});
                            },
                            child: const Text('Approve'),
                          ),
                          const SizedBox(width: 8),
                          OutlinedButton(
                            onPressed: () {
                              app['status'] = 'rejected';
                              app['reviewedAt'] = DateTime.now().toIso8601String();
                              widget.config.jobWorkerApplications = workerApps;
                              widget.onDataChanged();
                              setState(() {});
                            },
                            child: const Text('Reject'),
                          ),
                        ],
                      ),
                    ],
                  ),
                );
              }),
            ],
          ),
        ),
      Expanded(
        child: ListView.builder(
          padding: const EdgeInsets.symmetric(horizontal: 15),
          itemCount: filtered.length,
          itemBuilder: (_, i) {
            final u = filtered[i];
            final statusColor = u.status == 'active' ? Colors.green : u.status == 'suspended' ? Colors.orange : Colors.red;
            return Card(
              elevation: 0,
              color: panelBg,
              margin: const EdgeInsets.only(bottom: 10),
              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(15)),
              child: ListTile(
                onTap: () => setState(() => _selectedUserEmail = u.email),
                leading: _adminUserAvatar(u, fallback: statusColor),
                title: Text(u.username, style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14, color: isDark ? Colors.white : Colors.black)),
                subtitle: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(u.email, style: TextStyle(fontSize: 11, color: isDark ? Colors.white38 : Colors.black54)),
                    Text(ngmyUserDisplayAccountId(u), style: TextStyle(fontSize: 10, color: isDark ? Colors.white30 : Colors.black38)),
                  ],
                ),
                isThreeLine: true,
                trailing: Icon(Icons.chevron_right, color: isDark ? Colors.white38 : Colors.black38),
              ),
            );
          },
        ),
      ),
    ]);
  }

  void _prompt(BuildContext ctx, String title, Function(String) onSave) {
    final ctrl = TextEditingController();
    showDialog(context: ctx, builder: (c) => AlertDialog(title: Text(title), content: TextField(controller: ctrl, keyboardType: TextInputType.number), actions: [TextButton(onPressed:()=>Navigator.pop(c), child:const Text('CANCEL')), ElevatedButton(onPressed: (){ onSave(ctrl.text); Navigator.pop(c); }, child:const Text('SAVE'))]));
  }
  Widget _sBtn(String l, IconData i, Color c, VoidCallback onTap) => ElevatedButton.icon(onPressed: onTap, icon: Icon(i, size: 14), label: Text(l, style: const TextStyle(fontSize: 10)), style: ElevatedButton.styleFrom(backgroundColor: c, foregroundColor: Colors.white));
}

// --- STANDARD SCREENS ---

class WalletScreen extends StatefulWidget {
  final UserData user; final List<AppTransaction> transactions; final Function(AppTransaction) onAdd; final AppConfig config; final VoidCallback onDataChanged;
  const WalletScreen({super.key, required this.user, required this.transactions, required this.onAdd, required this.config, required this.onDataChanged});
  @override State<WalletScreen> createState() => _WalletScreenState();
}
class _WalletScreenState extends State<WalletScreen> {
  final _amt = TextEditingController(); final _handle = TextEditingController(); PaymentMethod _method = PaymentMethod.cashApp;
  int _view = 0; // 0: Deposit, 1: Withdraw, 2: History

  @override
  void initState() {
    super.initState();
    _applySavedWithdrawHandle();
  }

  @override
  void dispose() {
    _amt.dispose();
    _handle.dispose();
    super.dispose();
  }

  String get _savedHandleForMethod =>
      _method == PaymentMethod.cashApp ? widget.user.savedCashAppTag.trim() : widget.user.savedBitcoinAddress.trim();

  void _applySavedWithdrawHandle() {
    final saved = _savedHandleForMethod;
    if (saved.isNotEmpty) _handle.text = saved;
  }

  void _saveWithdrawHandle(String handle) {
    final trimmed = handle.trim();
    if (trimmed.isEmpty) return;
    if (_method == PaymentMethod.cashApp) {
      widget.user.savedCashAppTag = trimmed;
    } else {
      widget.user.savedBitcoinAddress = trimmed;
    }
    widget.onDataChanged();
  }

  void _clearSavedWithdrawHandle() {
    if (_method == PaymentMethod.cashApp) {
      widget.user.savedCashAppTag = '';
    } else {
      widget.user.savedBitcoinAddress = '';
    }
    _handle.clear();
    widget.onDataChanged();
    setState(() {});
  }

  void _submitWithdraw() async {
    final amount = double.tryParse(_amt.text) ?? 0;
    if (amount <= 0) return;

    if (amount > widget.user.accountBalance) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Insufficient balance. You have \$${formatCurrency(widget.user.accountBalance)}'))
      );
      return;
    }

    final fee = amount * 0.15;
    final receive = amount - fee;

    String handle = _handle.text.trim();
    if (handle.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(_method == PaymentMethod.cashApp ? 'Enter your Cash App tag.' : 'Enter your Bitcoin wallet address.')),
      );
      return;
    }
    if (_method == PaymentMethod.cashApp && !handle.startsWith('\$')) handle = '\$$handle';

    _saveWithdrawHandle(handle);

    widget.onAdd(AppTransaction(
      id: DateTime.now().toString(),
      userEmail: widget.user.email,
      amount: amount,
      type: TransactionType.withdrawal,
      method: _method,
      sourceDetails: '($handle) - Fee: \$${formatCurrency(fee)} - You receive: \$${formatCurrency(receive)}',
      timestamp: DateTime.now()
    ));

    setState(() {
      widget.user.accountBalance -= amount;
    });
    widget.onDataChanged();

    ScaffoldMessenger.of(context).showSnackBar(SnackBar(
      content: Text('Withdrawal request sent! You will receive \$${formatCurrency(receive)} after 15% fee.')
    ));
    _amt.clear();
    _applySavedWithdrawHandle();
  }

  @override Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.transparent,
      body: SafeArea(
        bottom: false,
        child: SingleChildScrollView(
          padding: EdgeInsets.fromLTRB(20, 10, 20, _ngmyBottomNavScrollPadding(context)),
          child: Column(children: [
      const FloatingTitle(title: 'MY WALLET'), const SizedBox(height: 20),
      Container(width: double.infinity, height: 180, decoration: BoxDecoration(gradient: const LinearGradient(colors: [Color(0xFF2E3192), Color(0xFF1BFFFF)]), borderRadius: BorderRadius.circular(30), boxShadow: [BoxShadow(color: Colors.blue.withOpacity(0.3), blurRadius: 20, offset: const Offset(0, 10))]), child: Stack(alignment: Alignment.center, children: [
        Positioned(
          top: 18,
          child: ShaderMask(
            shaderCallback: (bounds) => const LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: [Color(0xFFFFF8DC), Color(0xFFFFD700), Color(0xFFFFA500), Color(0xFFFFD700)],
            ).createShader(bounds),
            child: const Icon(Icons.account_balance_wallet_rounded, color: Colors.white, size: 40),
          ),
        ),
        Column(mainAxisAlignment: MainAxisAlignment.center, children: [const SizedBox(height: 10), const Text('Available Balance', style: TextStyle(color: Colors.white70, fontSize: 14)), const SizedBox(height: 5), Text('\$${formatCurrency(widget.user.accountBalance)}', style: const TextStyle(color: Colors.white, fontSize: 36, fontWeight: FontWeight.w900))]),
      ])),
      const SizedBox(height: 30),
      Row(children: [
        Expanded(child: InkWell(onTap: () => setState(() => _view = 0), child: _wNav(0, Icons.add_to_photos_rounded, 'DEPOSIT'))),
        const SizedBox(width: 15),
        Expanded(child: InkWell(onTap: () => setState(() => _view = 1), child: _wNav(1, Icons.outbox_rounded, 'WITHDRAW'))),
        const SizedBox(width: 15),
        Expanded(child: InkWell(onTap: () => setState(() => _view = 2), child: _wNav(2, Icons.history_rounded, 'HISTORY'))),
      ]),
      const SizedBox(height: 30),
      _walletBody(),
    ]),
        ),
      ),
    );
  }

  Widget _wNav(int i, IconData ic, String l) {
    final bool selected = _view == i;
    final bool isDark = Theme.of(context).brightness == Brightness.dark;
    return AnimatedContainer(
      duration: const Duration(milliseconds: 180),
      padding: const EdgeInsets.symmetric(vertical: 14),
      decoration: BoxDecoration(
        color: selected ? const Color(0xFF22C55E) : Theme.of(context).cardColor,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(
          color: selected ? const Color(0xFF16A34A) : Colors.grey.withOpacity(0.2),
          width: 1.2,
        ),
        boxShadow: [
          BoxShadow(
            color: selected ? const Color(0xFF22C55E).withOpacity(0.2) : Colors.black.withOpacity(0.05),
            blurRadius: selected ? 12 : 8,
            offset: const Offset(0, 4),
          ),
        ],
      ),
      child: Column(
        children: [
          Icon(ic, color: selected ? Colors.white : const Color(0xFF16A34A), size: 20),
          const SizedBox(height: 5),
          Text(
            l,
            style: TextStyle(
              fontSize: 10,
              fontWeight: FontWeight.w700,
              color: selected ? Colors.white : (isDark ? Colors.white70 : const Color(0xFF1F2937)),
              letterSpacing: 0.3,
            ),
          ),
        ],
      ),
    );
  }

  Widget _walletBody() {
    if (_view == 2) {
      double rollingBalance = widget.user.accountBalance;
      final entries = <MapEntry<AppTransaction, double>>[];
      for (final t in widget.transactions) {
        entries.add(MapEntry(t, rollingBalance));
        rollingBalance -= _transactionSignedDelta(t);
      }
      return Container(width: double.infinity, padding: const EdgeInsets.all(20), decoration: BoxDecoration(color: Theme.of(context).cardColor, borderRadius: BorderRadius.circular(25), boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.12), blurRadius: 15)]), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        const Text('TRANSACTION HISTORY', style: TextStyle(fontSize: 12, fontWeight: FontWeight.bold, color: Colors.grey)), const SizedBox(height: 15),
        if (widget.transactions.isEmpty) const Center(child: Text('Empty', style: TextStyle(color: Colors.grey, fontSize: 12)))
        else ...entries.map((entry) {
          final t = entry.key;
          final balanceAfter = entry.value;
          final incoming = _isIncomingTransaction(t);
          final icon = incoming ? Icons.arrow_downward : Icons.arrow_upward;
          final color = t.status == TransactionStatus.approved ? Colors.green : (t.status == TransactionStatus.pending ? Colors.orange : Colors.red);
          final typeLabel = _transactionTypeLabel(t);
          final details = _transactionDetails(t);
          return Container(
            margin: const EdgeInsets.only(bottom: 12),
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: Theme.of(context).brightness == Brightness.dark ? Colors.white.withOpacity(0.04) : Colors.white,
              borderRadius: BorderRadius.circular(14),
              border: Border.all(color: Colors.grey.withOpacity(0.2)),
              boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.04), blurRadius: 8)],
            ),
            child: Row(
              children: [
                Container(
                  padding: const EdgeInsets.all(8),
                  decoration: BoxDecoration(color: color.withOpacity(0.15), borderRadius: BorderRadius.circular(10)),
                  child: Icon(icon, size: 18, color: color),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(typeLabel, style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 12)),
                      const SizedBox(height: 2),
                      Text(_historyTimestamp(t.timestamp), style: const TextStyle(color: Colors.grey, fontSize: 10)),
                      const SizedBox(height: 2),
                      Text(details, style: const TextStyle(color: Colors.grey, fontSize: 10), maxLines: 2, overflow: TextOverflow.ellipsis),
                    ],
                  ),
                ),
                const SizedBox(width: 8),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.end,
                  children: [
                    Text('${incoming ? '+' : '-'}\$${formatCurrency(t.amount)}', style: TextStyle(fontWeight: FontWeight.bold, color: incoming ? Colors.green : Colors.red)),
                    Text('Balance: \$${formatCurrency(balanceAfter)}', style: const TextStyle(color: Colors.grey, fontSize: 9)),
                  ],
                )
              ],
            ),
          );
        }).toList()
      ]));
    }
    bool isDep = _view == 0;
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final cardBg = isDark ? const Color(0xFF161B22) : Colors.white;
    final inputBg = isDark ? const Color(0xFF0F141B) : const Color(0xFFF8FAFC);
    final inputBorder = isDark ? const Color(0xFF2B3440) : const Color(0xFFD1D5DB);
    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: cardBg,
        borderRadius: BorderRadius.circular(20),
        boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.08), blurRadius: 14, offset: const Offset(0, 4))],
      ),
