      ),
      child: Text(text, style: TextStyle(color: isDark ? Colors.white70 : const Color(0xFF334155), fontSize: 10, fontWeight: FontWeight.bold)),
    );
  }

  Widget _infoBox(BuildContext ctx, String label, String value, {bool compact = false}) {
    final isDark = Theme.of(ctx).brightness == Brightness.dark;
    return Container(
      padding: EdgeInsets.all(compact ? 6 : 10),
      decoration: BoxDecoration(
        color: isDark ? Colors.white.withOpacity(0.05) : Colors.white.withOpacity(0.72),
        borderRadius: BorderRadius.circular(compact ? 8 : 10),
        border: Border.all(color: isDark ? Colors.white10 : const Color(0xFFE2E8F0)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(label, style: TextStyle(color: isDark ? Colors.white60 : const Color(0xFF64748B), fontSize: compact ? 8 : 10)),
          SizedBox(height: compact ? 2 : 4),
          Text(
            value,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(color: isDark ? Colors.white : const Color(0xFF0F172A), fontWeight: FontWeight.bold, fontSize: compact ? 11 : 14),
          ),
        ],
      ),
    );
  }
}

class StatsScreen extends StatefulWidget {
  final UserData user;
  final List<AppTransaction> transactions;
  const StatsScreen({super.key, required this.user, required this.transactions});

  @override
  State<StatsScreen> createState() => _StatsScreenState();
}

class _StatsScreenState extends State<StatsScreen> {
  Timer? _ticker;
  DateTime _now = DateTime.now();

  @override
  void initState() {
    super.initState();
    _ticker = Timer.periodic(const Duration(milliseconds: 250), (_) {
      if (!mounted) return;
      setState(() => _now = DateTime.now());
    });
  }

  @override
  void dispose() {
    _ticker?.cancel();
    super.dispose();
  }

  BoxDecoration _statsFrameDecoration(BuildContext context, {bool elevated = false}) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final border = isDark ? const Color(0xFF64748B) : const Color(0xFFCBD5E1);
    return BoxDecoration(
      borderRadius: BorderRadius.circular(elevated ? 24 : 20),
      border: Border.all(color: border, width: 2.2),
      gradient: LinearGradient(
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
        colors: isDark
            ? [const Color(0xFF1B2436), const Color(0xFF0E1524)]
            : [Colors.white, const Color(0xFFF1F5F9)],
      ),
      boxShadow: [
        BoxShadow(color: Colors.black.withOpacity(isDark ? 0.42 : 0.16), blurRadius: elevated ? 20 : 14, offset: Offset(0, elevated ? 12 : 8)),
        BoxShadow(color: (isDark ? Colors.white : Colors.black).withOpacity(0.06), blurRadius: 1, offset: const Offset(0, -1)),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final approved = widget.transactions.where((t) => t.status == TransactionStatus.approved);
    final totalVol = approved.where((t) => t.type == TransactionType.deposit).fold(0.0, (s, t) => s + t.amount);
    final totalPay = approved.where((t) => t.type == TransactionType.withdrawal).fold(0.0, (s, t) => s + t.amount);
    final totalUsersInFlow = widget.transactions.map((t) => t.userEmail.toLowerCase().trim()).toSet().length;
    final totalDepositsCount = widget.transactions.where((t) => t.type == TransactionType.deposit).length;
    final totalWithdrawalsCount = widget.transactions.where((t) => t.type == TransactionType.withdrawal).length;
    final withdrawn24h = approved
        .where((t) => t.type == TransactionType.withdrawal && t.timestamp.isAfter(_now.subtract(const Duration(hours: 24))))
        .fold(0.0, (s, t) => s + t.amount);
    final active24hUsers = widget.transactions
        .where((t) => t.timestamp.isAfter(_now.subtract(const Duration(hours: 24))))
        .map((t) => t.userEmail.toLowerCase().trim())
        .toSet()
        .length;

    final last24h = _now.subtract(const Duration(hours: 24));
    final prev24h = _now.subtract(const Duration(hours: 48));
    final current24hVol = approved
        .where((t) => t.type == TransactionType.deposit && t.timestamp.isAfter(last24h))
        .fold(0.0, (s, t) => s + t.amount);
    final previous24hVol = approved
        .where((t) => t.type == TransactionType.deposit && t.timestamp.isAfter(prev24h) && t.timestamp.isBefore(last24h))
        .fold(0.0, (s, t) => s + t.amount);
    final growthPct = previous24hVol <= 0
        ? (current24hVol > 0 ? 100.0 : 0.0)
        : ((current24hVol - previous24hVol) / previous24hVol) * 100.0;

    final minuteVol = approved
        .where((t) => t.type == TransactionType.deposit && t.timestamp.isAfter(_now.subtract(const Duration(minutes: 1))))
        .fold(0.0, (s, t) => s + t.amount);
    final flowSecondsLeft = 60 - _now.second;
    final flowCountdown = '0:${flowSecondsLeft.toString().padLeft(2, '0')}';

    return Scaffold(
      backgroundColor: Colors.transparent,
      body: SafeArea(
        bottom: false,
        child: SingleChildScrollView(
          padding: EdgeInsets.fromLTRB(20, 10, 20, _ngmyBottomNavScrollPadding(context)),
          child: Column(
            children: [
              const FloatingTitle(title: 'PLATFORM STATS'),
              const SizedBox(height: 25),
              GridView.count(
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                crossAxisCount: 2,
                mainAxisSpacing: 15,
                crossAxisSpacing: 15,
                childAspectRatio: 1.25,
                children: [
                  _sTile(context, 'Total Volume', '\$${formatCurrency(totalVol)}', Icons.account_balance, Colors.blue),
                  _sTile(context, 'Total Profit', '\$${formatCurrency(widget.user.totalProfit)}', Icons.auto_graph, Colors.purple),
                  _sTile(context, 'Total Payout', '\$${formatCurrency(totalPay)}', Icons.payments, Colors.green),
                  _sTile(context, 'Global Rank', '#1', Icons.public, Colors.orange),
                ],
              ),
              const SizedBox(height: 25),
              Container(
                width: double.infinity,
                decoration: _statsFrameDecoration(context, elevated: true),
                child: Stack(
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(20, 20, 20, 20),
                      child: Column(
                        children: [
                    ShaderMask(
                      shaderCallback: (bounds) => LinearGradient(
                        colors: isDark
                            ? [const Color(0xFF93C5FD), const Color(0xFF34D399)]
                            : [const Color(0xFF2563EB), const Color(0xFF059669)],
                      ).createShader(bounds),
                      child: const Text('REAL-TIME GROWTH', style: TextStyle(fontWeight: FontWeight.w900, letterSpacing: 1.2, fontSize: 16, color: Colors.white)),
                    ),
                    const SizedBox(height: 14),
                    Icon(
                      growthPct >= 0 ? Icons.trending_up_rounded : Icons.trending_down_rounded,
                      size: 56,
                      color: growthPct >= 0 ? Colors.green : Colors.red,
                    ),
                    const SizedBox(height: 10),
                    Text(
                      '${growthPct >= 0 ? '+' : ''}${growthPct.toStringAsFixed(2)}% vs previous 24h',
                      style: TextStyle(
                        fontWeight: FontWeight.w800,
                        fontSize: 14,
                        color: growthPct >= 0 ? Colors.green : Colors.red,
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text('Last 24h deposits: \$${formatCurrency(current24hVol)}', style: const TextStyle(fontWeight: FontWeight.w700)),
                    const SizedBox(height: 6),
                    Container(
                      width: double.infinity,
                      padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
                      decoration: BoxDecoration(
                        color: isDark ? Colors.white.withOpacity(0.05) : Colors.black.withOpacity(0.03),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(color: isDark ? Colors.white24 : const Color(0xFFD1D5DB), width: 1.3),
                      ),
                      child: Column(
                        children: [
