  // Enrollment Form Controllers
  final _fullNameC = TextEditingController();
  final _dobC = TextEditingController();
  final _idTypeC = TextEditingController(text: 'National ID');
  final _addressC = TextEditingController();
  final _phoneC = TextEditingController();
  final _emailC = TextEditingController();
  final _cityC = TextEditingController();
  final _roomC = TextEditingController();
  final Set<String> _dismissedReceiptKeys = {};
  final Set<String> _openedReceiptKeys = {};
  bool _maintenanceQueued = false;

  final List<String> _usStates = [
    'Alabama', 'Alaska', 'Arizona', 'Arkansas', 'California', 'Colorado', 'Connecticut', 'Delaware', 'Florida', 'Georgia',
    'Hawaii', 'Idaho', 'Illinois', 'Indiana', 'Iowa', 'Kansas', 'Kentucky', 'Louisiana', 'Maine', 'Maryland',
    'Massachusetts', 'Michigan', 'Minnesota', 'Mississippi', 'Missouri', 'Montana', 'Nebraska', 'Nevada', 'New Hampshire', 'New Jersey',
    'New Mexico', 'New York', 'North Carolina', 'North Dakota', 'Ohio', 'Oklahoma', 'Oregon', 'Pennsylvania', 'Rhode Island', 'South Carolina',
    'South Dakota', 'Tennessee', 'Texas', 'Utah', 'Vermont', 'Virginia', 'Washington', 'West Virginia', 'Wisconsin', 'Wyoming'
  ];

  @override
  void initState() {
    super.initState();
    _selectedState = widget.user.state;
    _ensureUniqueRegistryIds();
    _openedReceiptKeys
      ..clear()
      ..addAll(widget.config.openedContributionReceiptKeys);
    _dismissedReceiptKeys
      ..clear()
      ..addAll(widget.config.dismissedContributionReceiptKeys);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _runHelpModeLifecycleMaintenance();
      _checkRegistryUnlock();
    });
  }

  bool _canBypassCivicGate() => widget.user.isAuthorizedRegistrar;

  Future<void> _checkRegistryUnlock() async {
    if (_canBypassCivicGate()) {
      if (mounted) setState(() {
        _registryUnlocked = true;
        _unlockChecked = true;
      });
      return;
    }
    final ok = await civicRegistryIsUnlocked(widget.user.email, _selectedState);
    if (mounted) {
      setState(() {
        _registryUnlocked = ok;
        _unlockChecked = true;
      });
    }
  }

  void _onRegistryUnlocked(String state) {
    setState(() {
      _selectedState = state;
      widget.user.state = state;
      _registryUnlocked = true;
    });
    widget.onDataChanged();
  }

  bool _canManageCivicRegistry() => widget.user.isAuthorizedRegistrar;

  int get _maxCivicTabIndex => _canManageCivicRegistry() ? 3 : 1;

  bool _hasPendingRegistrarApplication() {
    return widget.config.civicRegistrarApplications.any(
      (a) =>
          (a['userEmail'] ?? '').toString().toLowerCase().trim() == widget.user.email.toLowerCase().trim() &&
          (a['status'] ?? 'pending').toString() == 'pending',
    );
  }

  Future<void> _showRegistrarApplicationDialog() async {
    if (widget.user.isAuthorizedRegistrar) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('You are already an Authorized Registrar.')));
      return;
    }
    if (_hasPendingRegistrarApplication()) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Your registrar application is pending review.')));
      return;
    }
    final reasonC = TextEditingController();
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Apply — Authorized Registrar'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            const Text(
              'Authorized Registrars can enroll members, manage help mode, and maintain the registry for their state.',
              style: TextStyle(fontSize: 13),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: reasonC,
              maxLines: 4,
              decoration: const InputDecoration(
                labelText: 'Why should you be approved?',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Submit')),
        ],
      ),
    );
    if (ok == true && reasonC.text.trim().isNotEmpty) {
      widget.config.civicRegistrarApplications = [
        ...widget.config.civicRegistrarApplications.map((e) => Map<String, dynamic>.from(e)),
        {
          'id': DateTime.now().microsecondsSinceEpoch.toString(),
          'userEmail': widget.user.email,
          'username': widget.user.username,
          'fullName': widget.user.fullName ?? widget.user.username,
          'state': widget.user.state,
          'reason': reasonC.text.trim(),
          'status': 'pending',
          'createdAt': DateTime.now().toIso8601String(),
        },
      ];
      widget.onDataChanged();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Application sent. An admin will review it in the dashboard.')),
        );
        setState(() {});
      }
    } else if (ok == true) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please explain why you are applying.')));
    }
    reasonC.dispose();
  }

  List<UserData> _registryMembersMatchingSearch() {
    bool matchesFilters(UserData u) {
      final stateMatch = u.state.trim().toLowerCase() == _selectedState.trim().toLowerCase();
      final textMatch = _searchQuery.isEmpty ||
          u.username.toLowerCase().contains(_searchQuery) ||
          u.fullName?.toLowerCase().contains(_searchQuery) == true ||
          u.registryId?.toLowerCase().contains(_searchQuery) == true ||
          u.city?.toLowerCase().contains(_searchQuery) == true;
      return u.isEnrolledInRegistry && stateMatch && textMatch;
    }

    return widget.allUsers.where(matchesFilters).toList();
  }

  void _syncReceiptFlagsToConfig() {
    widget.config.openedContributionReceiptKeys = _openedReceiptKeys.toList();
    widget.config.dismissedContributionReceiptKeys = _dismissedReceiptKeys.toList();
    widget.onDataChanged();
  }

  void _markCampaignClosed(String campaignId, DateTime closedAt) {
    if (campaignId.trim().isEmpty) return;
    final closures = List<Map<String, dynamic>>.from(widget.config.helpCampaignClosures.map((e) => Map<String, dynamic>.from(e)));
    final idx = closures.indexWhere((e) => (e['campaignId'] ?? '').toString() == campaignId);
    final record = <String, dynamic>{
      'campaignId': campaignId,
      'closedAt': closedAt.toUtc().toIso8601String(),
    };
    if (idx >= 0) {
      closures[idx] = record;
    } else {
      closures.add(record);
    }
    widget.config.helpCampaignClosures = closures;
  }

  void _runHelpModeLifecycleMaintenance() {
    var changed = false;
    final now = DateTime.now();

    final startedAtRaw = widget.config.helpCampaignStartedAt.trim();
    if (widget.config.helpModeActive && startedAtRaw.isEmpty) {
      widget.config.helpCampaignStartedAt = now.toUtc().toIso8601String();
      changed = true;
    }
    if (widget.config.helpModeActive && startedAtRaw.isNotEmpty) {
      try {
        final startedAt = DateTime.parse(startedAtRaw).toLocal();
        if (now.difference(startedAt).inDays >= 5) {
          final campaignId = _activeHelpCampaignId();
          _markMissedForNonContributorsInCampaign(campaignId);
          widget.config.helpModeActive = false;
          widget.config.helpCampaignId = '';
          widget.config.helpCampaignStartedAt = '';
          _markCampaignClosed(campaignId, now);
          changed = true;
        }
      } catch (_) {}
    }

    if (widget.config.helpCampaignClosures.isNotEmpty) {
      final closures = List<Map<String, dynamic>>.from(widget.config.helpCampaignClosures.map((e) => Map<String, dynamic>.from(e)));
      final retained = <Map<String, dynamic>>[];
      for (final c in closures) {
        final campaignId = (c['campaignId'] ?? '').toString().trim();
        final closedAtRaw = (c['closedAt'] ?? '').toString().trim();
        if (campaignId.isEmpty || closedAtRaw.isEmpty) continue;
        DateTime? closedAt;
        try {
          closedAt = DateTime.parse(closedAtRaw).toLocal();
        } catch (_) {}
        if (closedAt == null) continue;
        final ageDays = now.difference(closedAt).inDays;
        if (ageDays >= 5) {
          _dismissedReceiptKeys.add(campaignId);
          changed = true;
        } else {
          retained.add(c);
        }
      }
      widget.config.helpCampaignClosures = retained;
    }

    if (changed) {
      _syncReceiptFlagsToConfig();
    }
  }

  void _queueHelpModeLifecycleMaintenance() {
    if (_maintenanceQueued) return;
    _maintenanceQueued = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _maintenanceQueued = false;
      if (!mounted) return;
      _runHelpModeLifecycleMaintenance();
    });
  }

  void _ensureUniqueRegistryIds() {
    final seen = <String>{};
    for (final u in widget.allUsers.where((u) => u.isEnrolledInRegistry)) {
      final id = (u.registryId ?? '').trim();
      if (id.isEmpty || seen.contains(id)) {
        u.registryId = _generateUniqueRegistryId(u.state);
      }
      seen.add((u.registryId ?? '').trim());
    }
  }

  String _generateUniqueRegistryId(String state) {
    final prefix = state.length >= 2 ? state.substring(0, 2).toUpperCase() : 'ST';
    final existing = widget.allUsers
        .map((u) => (u.registryId ?? '').trim())
        .where((id) => id.isNotEmpty)
        .toSet();
    for (int i = 0; i < 5000; i++) {
      final candidate = '$prefix${math.Random().nextInt(8999999) + 1000000}';
      if (!existing.contains(candidate)) return candidate;
    }
    return '$prefix${DateTime.now().microsecondsSinceEpoch}';
  }

  Future<void> _registerMember() async {
    final fullName = _fullNameC.text.trim();
    final dob = _dobC.text.trim();
    final idType = _idTypeC.text.trim();
    final address = _addressC.text.trim();
    final phone = _phoneC.text.trim();
    final email = _emailC.text.trim().toLowerCase();
    final city = _cityC.text.trim();
    final room = _roomC.text.trim();

    final hasTwoNames = RegExp(r'^\S+\s+\S+').hasMatch(fullName);
    if (!hasTwoNames) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Full Name must contain at least first and last name.')));
      return;
    }
    if (!RegExp(r'^\d{2}/\d{2}/\d{4}$').hasMatch(dob)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Date of Birth must be in MM/DD/YYYY format.')));
      return;
    }
    if (idType.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please select ID Type.')));
      return;
    }
    if (address.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Home Address is required.')));
      return;
    }
    if (!RegExp(r'^\d{7,15}$').hasMatch(phone)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Phone must contain numbers only (7-15 digits).')));
      return;
    }
    if (!RegExp(r'^[^\s@]+@[^\s@]+\.[^\s@]+$').hasMatch(email)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please enter a valid email address.')));
      return;
    }
    if (!widget.config.cities.contains(city)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please choose a city from Manage Cities & Rooms.')));
      return;
    }
    if (!widget.config.rooms.contains(room)) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please choose a room from Manage Cities & Rooms.')));
      return;
    }

    final idx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
    UserData targetUser;
    if (idx != -1) {
      targetUser = widget.allUsers[idx];
    } else {
      targetUser = UserData(
        email: email,
        username: fullName.split(' ').first,
        phone: phone,
        state: _selectedState,
      );
      widget.allUsers.add(targetUser);
    }

    setState(() {
      targetUser.isEnrolledInRegistry = true;
      targetUser.fullName = fullName;
      targetUser.dob = dob;
      targetUser.idType = idType;
      targetUser.homeAddress = address;
      targetUser.phone = phone;
      targetUser.email = email;
      targetUser.city = city;
      targetUser.room = room;
      targetUser.state = _selectedState;
      targetUser.registryId = targetUser.registryId?.isNotEmpty == true
          ? targetUser.registryId
          : _generateUniqueRegistryId(_selectedState);
      if (widget.allUsers.any((u) => u != targetUser && (u.registryId ?? '').trim() == (targetUser.registryId ?? '').trim())) {
        targetUser.registryId = _generateUniqueRegistryId(_selectedState);
      }

      _fullNameC.clear();
      _dobC.clear();
      _addressC.clear();
      _phoneC.clear();
      _emailC.clear();
      _cityC.clear();
      _roomC.clear();
      _activeTab = 2;
    });
    await _persistRegistryMember(targetUser);
    widget.onDataChanged();
    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Member Registered Successfully!'), backgroundColor: Colors.green));
  }

  Future<void> _persistRegistryMember(UserData member) async {
    try {
      await Supabase.instance.client
          .from('users')
          .upsert([Map<String, dynamic>.from(member.toJson())]);
    } catch (e) {
      debugPrint('Registry member upsert failed: $e');
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('all_users', jsonEncode(widget.allUsers.map((e) => e.toJson()).toList()));
    } catch (e) {
      debugPrint('Registry member local save failed: $e');
    }
  }

  void _showStatePicker() {
    showModalBottomSheet(
      context: context,
      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(30))),
      builder: (c) => Container(
        padding: const EdgeInsets.all(25),
        child: Column(
          children: [
            const Text('Select State', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 20)),
            const SizedBox(height: 15),
            Expanded(
              child: ListView.builder(
                itemCount: _usStates.length,
                itemBuilder: (ctx, i) => ListTile(
                  title: Text(_usStates[i], style: const TextStyle(fontWeight: FontWeight.w600)),
                  onTap: () async {
                    final newState = _usStates[i];
                    Navigator.pop(c);
                    if (!_canBypassCivicGate()) {
                      final ok = await civicRegistryIsUnlocked(widget.user.email, newState);
                      if (!ok) {
                        setState(() {
                          _selectedState = newState;
                          _selectedCity = 'All Cities';
                          _selectedRoom = 'All Rooms';
                          _registryUnlocked = false;
                        });
                        return;
                      }
                    }
                    setState(() {
                      _selectedState = newState;
                      _selectedCity = 'All Cities';
                      _selectedRoom = 'All Rooms';
                    });
                  },
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  bool _memberMatchesHelpScope(UserData u) {
    if (!widget.config.helpModeActive) return false;
    final scopeType = widget.config.helpScopeType;
    final scopeValue = widget.config.helpScopeValue.trim();
    if (scopeType == 'city') return scopeValue.isNotEmpty && (u.city ?? '') == scopeValue;
    if (scopeType == 'room') return scopeValue.isNotEmpty && (u.room ?? '') == scopeValue;
    return true;
  }

  String _activeHelpCampaignId() {
    final stored = widget.config.helpCampaignId.trim();
    if (stored.isNotEmpty) return stored;
    return '${widget.config.helpPurpose}|${widget.config.helpScopeType}|${widget.config.helpScopeValue}|${widget.user.state}';
  }

  List<UserData> _membersInCurrentHelpScope() {
    return widget.allUsers.where((m) {
      if (!m.isEnrolledInRegistry) return false;
      if (!_memberMatchesHelpScope(m)) return false;
      return (m.state.trim().isEmpty || m.state == widget.user.state);
    }).toList();
  }

  void _markMissedForNonContributorsInCampaign(String campaignId) {
    final normalizedCampaignId = campaignId.trim();
    if (normalizedCampaignId.isEmpty) return;
    final contributors = widget.allTransactions
        .where((t) => t.type == TransactionType.contribution && t.status == TransactionStatus.approved)
        .where((t) {
          final meta = _decodeContributionMeta(t);
          return (meta['campaignId'] ?? '').toString() == normalizedCampaignId;
        })
        .map((t) => t.userEmail.toLowerCase().trim())
        .toSet();
    for (final m in _membersInCurrentHelpScope()) {
      final key = m.email.toLowerCase().trim();
      if (!contributors.contains(key)) {
        m.missed += 1;
      }
    }
  }

  bool _canCurrentUserSeeHelpMode() {
    if (!widget.config.helpModeActive) return false;
    if (_canManageCivicRegistry()) return true;
    return _memberMatchesHelpScope(widget.user);
  }

  Map<String, dynamic> _decodeContributionMeta(AppTransaction t) {
    final raw = t.sourceDetails?.trim() ?? '';
    if (raw.isEmpty) return {};
    try {
      final decoded = jsonDecode(raw);
      if (decoded is Map<String, dynamic>) return decoded;
      if (decoded is Map) return Map<String, dynamic>.from(decoded);
    } catch (_) {}
    return {'note': raw};
  }

  bool _audienceMatchForViewer(String scopeType, String scopeValue) {
    if (_canManageCivicRegistry()) return true;
    if (scopeType == 'city') return (widget.user.city ?? '') == scopeValue;
    if (scopeType == 'room') return (widget.user.room ?? '') == scopeValue;
    return true;
  }

  List<AppTransaction> _visibleContributionTx() {
    return widget.allTransactions.where((t) {
      if (t.type != TransactionType.contribution || t.status != TransactionStatus.approved) return false;
      final meta = _decodeContributionMeta(t);
      final scopeType = (meta['scopeType'] ?? 'all').toString();
      final scopeValue = (meta['scopeValue'] ?? '').toString();
      final targetState = (meta['state'] ?? '').toString();
      if (targetState.isNotEmpty && targetState != widget.user.state && !_canManageCivicRegistry()) return false;
      return _audienceMatchForViewer(scopeType, scopeValue);
    }).toList()
      ..sort((a, b) => b.timestamp.compareTo(a.timestamp));
  }

  Map<String, List<AppTransaction>> _groupContributionReceipts(List<AppTransaction> txs, {bool unreadOnly = false}) {
    final groups = <String, List<AppTransaction>>{};
    for (final t in txs) {
      final meta = _decodeContributionMeta(t);
      final key = (meta['campaignId'] ?? '${meta['purpose'] ?? 'Campaign'}|${meta['scopeType'] ?? 'all'}|${meta['scopeValue'] ?? ''}|${meta['state'] ?? widget.user.state}')
          .toString();
      if (_dismissedReceiptKeys.contains(key)) continue;
      if (unreadOnly && _openedReceiptKeys.contains(key)) continue;
      groups.putIfAbsent(key, () => []).add(t);
    }
    return groups;
  }

  String _helpScopeLabel() {
    if (widget.config.helpScopeType == 'city') {
      return 'City: ${widget.config.helpScopeValue}';
    }
    if (widget.config.helpScopeType == 'room') {
      return 'Room: ${widget.config.helpScopeValue}';
    }
    return 'All members';
  }

  Future<void> _openCashApp() async {
    final raw = widget.config.helpCashApp.trim();
    if (raw.isEmpty) return;
    final handle = raw.startsWith(r'$') ? raw.substring(1) : raw;
    final uri = Uri.parse('https://cash.app/\$$handle');
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }

  Future<void> _callHelpPhone() async {
    final phone = widget.config.helpPhone.trim();
    if (phone.isEmpty) return;
    final uri = Uri.parse('tel:$phone');
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }

  void _copyText(String text, String label) {
    if (text.trim().isEmpty) return;
    Clipboard.setData(ClipboardData(text: text.trim()));
    ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$label copied')));
  }

