    final availableAppUsers = widget.allUsers.where((u) =>
      !u.isEnrolledInRegistry &&
      (u.username.toLowerCase().contains(_enrollSearchC.text.toLowerCase()) ||
       u.email.toLowerCase().contains(_enrollSearchC.text.toLowerCase()))
