  Widget _rankingsSection(bool isDark) {
    final enrolled = widget.allUsers
        .where((u) => u.isEnrolledInRegistry && u.state.trim().toLowerCase() == _selectedState.trim().toLowerCase())
        .toList();
    enrolled.sort((a, b) => b.helps.compareTo(a.helps));

    final topHelpers = enrolled.where((u) => u.helps >= 10).toList();
    final theMiss = enrolled.where((u) => u.helps > 0 && u.helps < 10).toList();
    final nonHelpers = enrolled.where((u) => u.helps == 0).toList();

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Row(
          mainAxisAlignment: MainAxisAlignment.spaceBetween,
          children: [
            const Text('Ranking - Top Helpers', style: TextStyle(fontWeight: FontWeight.bold, color: Colors.orange)),
            TextButton.icon(onPressed: _showStatePicker, icon: const Icon(Icons.edit_location_alt_rounded, size: 16), label: Text(_selectedState, style: const TextStyle(fontSize: 12))),
          ],
        ),
        const SizedBox(height: 10),
        if (topHelpers.isEmpty) const Text('No top helpers yet.', style: TextStyle(color: Colors.grey, fontSize: 12))
        else ...topHelpers.map((u) => _rankTile(u, Colors.orange)),

        const SizedBox(height: 25),
        const Text('The Miss (Active)', style: TextStyle(fontWeight: FontWeight.bold, color: Colors.blue)),
        const SizedBox(height: 10),
        if (theMiss.isEmpty) const Text('No active helpers in this range.', style: TextStyle(color: Colors.grey, fontSize: 12))
        else ...theMiss.map((u) => _rankTile(u, Colors.blue)),

        const SizedBox(height: 25),
        const Text('Non-Helpers', style: TextStyle(fontWeight: FontWeight.bold, color: Colors.grey)),
        const SizedBox(height: 10),
        if (nonHelpers.isEmpty) const Text('Everyone is helping!', style: TextStyle(color: Colors.grey, fontSize: 12))
        else ...nonHelpers.map((u) => _rankTile(u, Colors.grey)),
      ],
    );
  }

  Widget _rankTile(UserData u, Color color) {
    return ListTile(
      contentPadding: EdgeInsets.zero,
      leading: CircleAvatar(backgroundColor: color.withOpacity(0.1), child: Text(u.username[0], style: TextStyle(color: color, fontWeight: FontWeight.bold))),
      title: Text(u.username, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 14)),
      trailing: Text('${u.helps} Helps', style: TextStyle(color: color, fontWeight: FontWeight.w900)),
    );
  }

  Widget _aboutItem(String text) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text('• ', style: TextStyle(color: Colors.blue, fontWeight: FontWeight.bold)),
          Expanded(child: Text(text, style: TextStyle(color: Colors.grey.shade700, fontSize: 11, height: 1.4))),
        ],
      ),
    );
  }
}

/// Animated live shipment track (vehicle moves smoothly along the route).
class _LiveTrackingPanel extends StatefulWidget {
  final Map<String, dynamic> order;
  final bool isDark;
  final int replayTrigger;

  const _LiveTrackingPanel({
    super.key,
    required this.order,
    required this.isDark,
    this.replayTrigger = 0,
  });

  @override
  State<_LiveTrackingPanel> createState() => _LiveTrackingPanelState();
}

class _LiveTrackingPanelState extends State<_LiveTrackingPanel> with WidgetsBindingObserver {
  Timer? _tick;
  double _displayT = 0.0;
  bool _replayActive = false;
  DateTime? _replayStartedAt;
  double _replayTarget = 0.0;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _startReplayDrive();
    _tick = Timer.periodic(const Duration(milliseconds: 40), (_) => _onAnimationTick());
  }

  @override
  void didUpdateWidget(covariant _LiveTrackingPanel oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.replayTrigger != widget.replayTrigger) {
      _startReplayDrive();
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _startReplayDrive();
    }
  }

  void _startReplayDrive() {
    _replayActive = true;
    _replayStartedAt = DateTime.now();
    _displayT = 0.0;
    _replayTarget = _shipmentProgressFraction(widget.order);
  }

  void _onAnimationTick() {
    if (!mounted) return;
    final target = _shipmentProgressFraction(widget.order);
    if (_replayActive && _replayStartedAt != null) {
      const durationMs = 4500.0;
      final elapsed = DateTime.now().difference(_replayStartedAt!).inMilliseconds;
      final linear = (elapsed / durationMs).clamp(0.0, 1.0);
      final curved = Curves.easeInOutCubic.transform(linear);
      _displayT = (_replayTarget * curved).clamp(0.0, 1.0);
      if (linear >= 1.0) {
        _replayActive = false;
        _displayT = target;
      }
    } else {
      const step = 0.0012;
      final diff = target - _displayT;
      if (diff.abs() <= step) {
        _displayT = target;
      } else {
        _displayT += diff.sign * step;
      }
    }
    setState(() {});
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _tick?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final order = widget.order;
    final dark = widget.isDark;
    final progress = (_displayT * 100).round().clamp(0, 100);
    final t = _displayT.clamp(0.0, 1.0);
    final etaMins = _minutesUntilEta(order);
    final trackingId = (order['trackingId'] ?? '').toString();
    final status = (order['fulfillmentStatus'] ?? '').toString();
    final method = (order['shippingMethod'] ?? 'car').toString();
    final vehicle = _storeVehicleIcon(method);
    final vehicleLabel = _storeVehicleLabel(method);
    final eta = DateTime.tryParse((order['estimatedArrival'] ?? '').toString());
    final currentLoc = (order['currentLocation'] ?? '').toString();
    final steps = ['Shipped', 'In Transit', 'Arriving', 'Delivered'];
    var activeStep = 0;
    if (status == 'in_transit') activeStep = 1;
    if (status == 'arriving') activeStep = 2;
    if (status == 'delivered') activeStep = 3;

    final panelBg = dark ? const Color(0xFF12182A) : const Color(0xFFEFF6FF);
    final panelBorder = dark ? const Color(0xFF3B82F6) : const Color(0xFFBFDBFE);
    final titleColor = dark ? const Color(0xFF93C5FD) : const Color(0xFF1D4ED8);
    final bodyColor = dark ? Colors.white : const Color(0xFF334155);
    final mutedColor = dark ? Colors.white70 : const Color(0xFF475569);
    final trackBg = dark ? const Color(0xFF1E293B) : Colors.white;
    final stepActive = dark ? const Color(0xFF60A5FA) : const Color(0xFF2563EB);
    final stepDone = Colors.greenAccent.shade400;
    final stepIdle = dark ? Colors.white38 : Colors.grey;

    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: panelBg,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: panelBorder, width: 1.5),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Text('Live Tracking', style: TextStyle(fontWeight: FontWeight.w900, color: titleColor, fontSize: 14)),
              const Spacer(),
              Text('#$trackingId', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w800, color: dark ? const Color(0xFFC4B5FD) : const Color(0xFF6D28D9))),
            ],
          ),
          const SizedBox(height: 6),
          Text('$vehicleLabel · live drive animation', style: TextStyle(fontSize: 11, color: mutedColor, fontWeight: FontWeight.w600)),
          if (eta != null)
            Text('ETA: ${_formatStoreTrackingWhen(eta.toUtc().toIso8601String())}', style: TextStyle(fontSize: 11, color: dark ? const Color(0xFF93C5FD) : const Color(0xFF2563EB), fontWeight: FontWeight.w800)),
          if (currentLoc.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(top: 4),
              child: Text('Now: $currentLoc', style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700, color: bodyColor)),
            ),
          if (etaMins != null)
            Padding(
              padding: const EdgeInsets.only(top: 4),
              child: Text(etaMins, style: TextStyle(fontSize: 12, fontWeight: FontWeight.w900, color: dark ? const Color(0xFF34D399) : const Color(0xFF059669))),
            ),
          const SizedBox(height: 12),
          LayoutBuilder(
            builder: (_, constraints) {
              final w = constraints.maxWidth;
              final vehicleSize = 36.0;
              final x = (w - vehicleSize) * t.clamp(0.0, 1.0);
              return SizedBox(
                height: 52,
                child: Stack(
                  clipBehavior: Clip.none,
                  children: [
                    Positioned(
                      left: 0,
                      right: 0,
                      top: 22,
                      child: Container(
                        height: 6,
                        decoration: BoxDecoration(
                          color: trackBg,
                          borderRadius: BorderRadius.circular(4),
                          border: Border.all(color: panelBorder),
                        ),
                      ),
                    ),
                    Positioned(
                      left: 0,
                      top: 22,
                      width: (w * t).clamp(vehicleSize * 0.5, w),
                      child: Container(
                        height: 6,
                        decoration: BoxDecoration(
                          gradient: const LinearGradient(colors: [Color(0xFF7C3AED), Color(0xFF2563EB)]),
                          borderRadius: BorderRadius.circular(4),
                        ),
                      ),
                    ),
                    Positioned(
                      left: x,
                      top: 4,
                      child: Container(
                        padding: const EdgeInsets.all(6),
                        decoration: BoxDecoration(
                          color: dark ? const Color(0xFF1E293B) : Colors.white,
                          shape: BoxShape.circle,
                          boxShadow: [BoxShadow(color: const Color(0xFF7C3AED).withOpacity(0.35), blurRadius: 8, offset: const Offset(0, 2))],
                          border: Border.all(color: const Color(0xFF7C3AED), width: 2),
                        ),
                        child: Icon(vehicle, size: 22, color: const Color(0xFF7C3AED)),
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
          const SizedBox(height: 8),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: List.generate(4, (i) {
              final done = i <= activeStep;
              return Column(
                children: [
                  Icon(done ? Icons.check_circle : Icons.circle_outlined, size: 18, color: done ? stepDone : stepIdle),
                  Text(steps[i], style: TextStyle(fontSize: 9, fontWeight: FontWeight.w800, color: done ? stepActive : stepIdle)),
                ],
              );
            }),
          ),
          if ((order['locationHistory'] as List?)?.isNotEmpty == true) ...[
            const SizedBox(height: 10),
            ...((order['locationHistory'] as List).cast<Map>().map((e) => Map<String, dynamic>.from(e))).take(4).map((h) {
              return Padding(
                padding: const EdgeInsets.only(top: 6),
                child: Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Icon(Icons.fiber_manual_record, size: 10, color: dark ? const Color(0xFF60A5FA) : const Color(0xFF2563EB)),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            (h['location'] ?? '').toString(),
                            style: TextStyle(fontWeight: FontWeight.w800, fontSize: 13, color: bodyColor),
                          ),
                          Text(
                            '${h['note'] ?? ''} · ${(h['at'] ?? '').toString()}',
                            style: TextStyle(fontSize: 11, fontWeight: FontWeight.w600, color: mutedColor),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              );
            }),
          ],
          const SizedBox(height: 10),
          Center(
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 6),
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  colors: dark
                      ? [const Color(0xFF2563EB), const Color(0xFF7C3AED)]
                      : [const Color(0xFF1D4ED8), const Color(0xFF6D28D9)],
                ),
                borderRadius: BorderRadius.circular(20),
                boxShadow: [BoxShadow(color: const Color(0xFF2563EB).withOpacity(0.35), blurRadius: 8)],
              ),
              child: Text(
                status == 'delivered' ? '✓ Delivered' : '$progress% · Live',
                style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w900, color: Colors.white),
              ),
            ),
          ),
        ],
      ),
    );
  }
}

String _formatStoreTrackingWhen(String iso) {
  final dt = DateTime.tryParse(iso);
  if (dt == null) return iso;
  final local = dt.toLocal();
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return '${months[local.month - 1]} ${local.day}, ${local.year} ${local.hour}:${local.minute.toString().padLeft(2, '0')}';
}

