  void initState() {
    super.initState();
    _pageCtrl.addListener(_onPage);
  }

  void _onPage() {
    final p = _pageCtrl.page?.round() ?? 0;
    if (p != _page) {
      if (mounted) setState(() => _page = p);
      widget.onPageChanged?.call(p);
