          if (fulfillment != 'pending' && fulfillment != 'refunded') ...[
            const SizedBox(height: 12),
            _LiveTrackingPanel(
              key: ValueKey('track_${orderId}_${order['updatedAt']}_$_trackingReplayToken'),
              order: order,
              isDark: isDark,
