                              final hist = List<Map<String, dynamic>>.from((o['locationHistory'] as List?)?.map((e) => Map<String, dynamic>.from(e as Map)) ?? []);
                              hist.insert(0, {
                                'location': loc,
                                'note': 'Order shipped via ${_storeVehicleLabel(method)}',
                                'at': DateTime.now().toLocal().toString(),
