class JobMarketplaceScreen extends StatefulWidget {
  final UserData user;
  final List<UserData> allUsers;
  final AppConfig config;
  final VoidCallback onDataChanged;
  const JobMarketplaceScreen({
    super.key,
    required this.user,
    required this.allUsers,
    required this.config,
    required this.onDataChanged,
  });

  @override
  State<JobMarketplaceScreen> createState() => _JobMarketplaceScreenState();
}

class _JobMarketplaceScreenState extends State<JobMarketplaceScreen> {
  int _activeTab = 0; // 0: Find Jobs, 1: My Jobs, 2: Claimed
  final ImagePicker _picker = ImagePicker();

  @override
  void initState() {
    super.initState();
    widget.config.jobPosts = List<Map<String, dynamic>>.from(
      widget.config.jobPosts.map((e) => Map<String, dynamic>.from(e)),
    );
    widget.config.jobWorkerApplications = List<Map<String, dynamic>>.from(
      widget.config.jobWorkerApplications.map((e) => Map<String, dynamic>.from(e)),
    );
  }

  bool get _isApprovedWorker => widget.user.isApprovedWorker;
  List<Map<String, dynamic>> get _jobs => widget.config.jobPosts;
  List<Map<String, dynamic>> get _workerApplications =>
      widget.config.jobWorkerApplications.map((e) => Map<String, dynamic>.from(e)).toList()
        ..sort((a, b) => (b['createdAt'] ?? '').toString().compareTo((a['createdAt'] ?? '').toString()));

  ImageProvider? _jobImage(String? imageRef) {
    if (imageRef == null || imageRef.trim().isEmpty) return null;
    final src = imageRef.trim();
    if (src.startsWith('data:image')) {
      try {
        return MemoryImage(base64Decode(src.split(',').last));
      } catch (_) {
        return null;
      }
    }
    if (src.startsWith('http://') || src.startsWith('https://')) {
      return NetworkImage(src);
    }
    if (!kIsWeb) {
      return FileImage(File(src));
    }
    return null;
  }

  void _saveJobs() {
    widget.onDataChanged();
    setState(() {});
  }

  void _processWorkerApplication(Map<String, dynamic> app, {required bool approve}) {
    final appId = (app['id'] ?? '').toString();
    if (appId.isEmpty) return;
    final apps = List<Map<String, dynamic>>.from(
      widget.config.jobWorkerApplications.map((e) => Map<String, dynamic>.from(e)),
    );
    final idx = apps.indexWhere((a) => (a['id'] ?? '').toString() == appId);
    if (idx < 0) return;
    apps[idx]['status'] = approve ? 'approved' : 'rejected';
    apps[idx]['reviewedAt'] = DateTime.now().toIso8601String();
    apps[idx]['reviewedBy'] = widget.user.email;
    widget.config.jobWorkerApplications = apps;

    final email = (apps[idx]['userEmail'] ?? '').toString().toLowerCase().trim();
    final userIndex = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == email);
    if (userIndex >= 0) {
      widget.allUsers[userIndex].isApprovedWorker = approve;
    }
    _saveJobs();
  }

  String _appStatusLabel(String status) {
    switch (status) {
      case 'approved':
        return 'Approved';
      case 'rejected':
        return 'Rejected';
      default:
        return 'Pending Review';
    }
  }

  Color _appStatusColor(String status) {
    switch (status) {
      case 'approved':
        return Colors.green;
      case 'rejected':
        return Colors.red;
      default:
        return Colors.orange;
    }
  }

  Future<void> _confirmDeleteJob(Map<String, dynamic> job) async {
    final status = (job['status'] ?? 'open').toString();
    if (status != 'open') {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Only open jobs can be deleted.')));
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete Job?'),
        content: Text('Remove "${(job['title'] ?? 'this job').toString()}" from the marketplace?'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          ElevatedButton(
            onPressed: () => Navigator.pop(ctx, true),
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red, foregroundColor: Colors.white),
            child: const Text('Delete'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    final id = (job['id'] ?? '').toString();
    _jobs.removeWhere((j) => (j['id'] ?? '').toString() == id);
    _saveJobs();
    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Job deleted.')));
  }

  Future<void> _showPostJobDialog({Map<String, dynamic>? editJob}) async {
    final isEdit = editJob != null;
    final titleC = TextEditingController(text: isEdit ? (editJob['title'] ?? '').toString() : '');
    final descC = TextEditingController(text: isEdit ? (editJob['description'] ?? '').toString() : '');
    final contactC = TextEditingController(
      text: isEdit
          ? (editJob['contact'] ?? '').toString()
          : (widget.user.phone.isNotEmpty ? widget.user.phone : widget.user.email),
    );
    final whenC = TextEditingController(text: isEdit ? (editJob['preferredTime'] ?? '').toString() : '');
    final addressC = TextEditingController(text: isEdit ? (editJob['address'] ?? '').toString() : '');
    final budgetC = TextEditingController(
      text: isEdit ? ((editJob['budget'] as num?)?.toString() ?? '') : '',
    );
    String category = isEdit ? (editJob['category'] ?? 'General Service').toString() : 'General Service';
    String workType = isEdit ? (editJob['workType'] ?? 'On-site').toString() : 'On-site';
    String urgency = isEdit ? (editJob['urgency'] ?? 'Normal').toString() : 'Normal';
    String imageRef = isEdit ? (editJob['imageRef'] ?? '').toString() : '';

    await showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialog) => AlertDialog(
          title: Text(isEdit ? 'Edit Job' : 'Post New Job'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(controller: titleC, decoration: const InputDecoration(labelText: 'Job title')),
                TextField(controller: descC, maxLines: 3, decoration: const InputDecoration(labelText: 'Job details')),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Expanded(
                      child: DropdownButtonFormField<String>(
                        initialValue: category,
                        decoration: const InputDecoration(labelText: 'Category'),
                        items: const [
                          DropdownMenuItem(value: 'General Service', child: Text('General Service')),
                          DropdownMenuItem(value: 'Electrical', child: Text('Electrical')),
                          DropdownMenuItem(value: 'Plumbing', child: Text('Plumbing')),
                          DropdownMenuItem(value: 'Cleaning', child: Text('Cleaning')),
                          DropdownMenuItem(value: 'Carpentry', child: Text('Carpentry')),
                          DropdownMenuItem(value: 'Delivery', child: Text('Delivery')),
                        ],
                        onChanged: (v) => setDialog(() => category = v ?? 'General Service'),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: DropdownButtonFormField<String>(
                        initialValue: workType,
                        decoration: const InputDecoration(labelText: 'Work Type'),
                        items: const [
                          DropdownMenuItem(value: 'On-site', child: Text('On-site')),
                          DropdownMenuItem(value: 'Remote', child: Text('Remote')),
                          DropdownMenuItem(value: 'Hybrid', child: Text('Hybrid')),
                        ],
                        onChanged: (v) => setDialog(() => workType = v ?? 'On-site'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 8),
                TextField(controller: contactC, decoration: const InputDecoration(labelText: 'Phone or Email')),
                TextField(controller: whenC, decoration: const InputDecoration(labelText: 'When do you need it done?')),
                TextField(controller: addressC, decoration: const InputDecoration(labelText: 'Workplace address')),
                TextField(controller: budgetC, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Budget (\$)')),
                const SizedBox(height: 8),
                DropdownButtonFormField<String>(
                  initialValue: urgency,
                  decoration: const InputDecoration(labelText: 'Urgency'),
                  items: const [
                    DropdownMenuItem(value: 'Low', child: Text('Low')),
                    DropdownMenuItem(value: 'Normal', child: Text('Normal')),
                    DropdownMenuItem(value: 'Urgent', child: Text('Urgent')),
                  ],
                  onChanged: (v) => setDialog(() => urgency = v ?? 'Normal'),
                ),
                const SizedBox(height: 10),
                Row(
                  children: [
                    Expanded(
                      child: OutlinedButton.icon(
                        onPressed: () async {
                          final img = await _picker.pickImage(source: ImageSource.gallery, imageQuality: 78, maxWidth: 1200);
                          if (img == null) return;
                          if (kIsWeb) {
                            final bytes = await img.readAsBytes();
                            imageRef = 'data:image/jpeg;base64,${base64Encode(bytes)}';
                          } else {
                            imageRef = img.path;
                          }
                          setDialog(() {});
                        },
                        icon: const Icon(Icons.photo),
                        label: const Text('Add Picture'),
                      ),
                    ),
                  ],
                ),
                if (imageRef.isNotEmpty) ...[
                  const SizedBox(height: 8),
                  Container(
                    height: 110,
                    decoration: BoxDecoration(
                      borderRadius: BorderRadius.circular(10),
                      image: DecorationImage(image: _jobImage(imageRef)!, fit: BoxFit.cover),
                    ),
                  ),
                ],
              ],
            ),
          ),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
            ElevatedButton(
              onPressed: () {
                if (titleC.text.trim().isEmpty || contactC.text.trim().isEmpty || addressC.text.trim().isEmpty) {
                  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Title, contact, and address are required.')));
                  return;
                }
                final budget = double.tryParse(budgetC.text.trim()) ?? 0;
                if (isEdit) {
                  final id = (editJob['id'] ?? '').toString();
                  final idx = _jobs.indexWhere((j) => (j['id'] ?? '').toString() == id);
                  if (idx < 0) {
                    Navigator.pop(ctx);
                    return;
                  }
                  final existing = Map<String, dynamic>.from(_jobs[idx]);
                  existing['title'] = titleC.text.trim();
                  existing['description'] = descC.text.trim();
                  existing['category'] = category;
                  existing['workType'] = workType;
                  existing['urgency'] = urgency;
                  existing['contact'] = contactC.text.trim();
                  existing['preferredTime'] = whenC.text.trim();
                  existing['address'] = addressC.text.trim();
                  existing['budget'] = budget;
                  existing['imageRef'] = imageRef;
                  existing['agreedPrice'] = budget;
                  _jobs[idx] = existing;
                } else {
                  _jobs.add({
                    'id': DateTime.now().microsecondsSinceEpoch.toString(),
                    'ownerEmail': widget.user.email,
                    'ownerName': widget.user.username,
                    'title': titleC.text.trim(),
                    'description': descC.text.trim(),
                    'category': category,
                    'workType': workType,
                    'urgency': urgency,
                    'contact': contactC.text.trim(),
                    'preferredTime': whenC.text.trim(),
                    'address': addressC.text.trim(),
                    'budget': budget,
                    'imageRef': imageRef,
                    'status': 'open',
                    'offers': <Map<String, dynamic>>[],
                    'claimedByEmail': '',
                    'claimedByName': '',
                    'agreedPrice': budget,
                    'createdAt': DateTime.now().toIso8601String(),
                    'completedAt': '',
                  });
                }
                _saveJobs();
                Navigator.pop(ctx);
                ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(isEdit ? 'Job updated.' : 'Job posted.')));
              },
              child: Text(isEdit ? 'Save Changes' : 'Post Job'),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _showWorkerApplicationDialog() async {
    final fullNameC = TextEditingController(text: widget.user.fullName ?? widget.user.username);
    final phoneC = TextEditingController(text: widget.user.phone);
    final cityC = TextEditingController(text: widget.user.city ?? '');
    final yearsC = TextEditingController();
    final skillsC = TextEditingController();
    final roleC = TextEditingController();
    final portfolioC = TextEditingController();
    final noteC = TextEditingController();
    String availability = 'Full-time';
    final hasPending = widget.config.jobWorkerApplications.any(
      (a) => (a['userEmail'] ?? '').toString().toLowerCase().trim() == widget.user.email.toLowerCase().trim() && (a['status'] ?? '') == 'pending',
    );
    if (hasPending) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('You already have a pending worker application.')));
      return;
    }
    if (_isApprovedWorker) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('You are already approved as a worker.')));
      return;
    }
    await showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialog) {
          final isDark = Theme.of(ctx).brightness == Brightness.dark;
          final panelBg = isDark ? const Color(0xFF101827) : Colors.white;
          final fill = isDark ? const Color(0xFF0F172A) : const Color(0xFFF8FAFC);
          final border = isDark ? const Color(0xFF334155) : const Color(0xFFD1D5DB);
          InputDecoration dec(String label, {String? hint}) => InputDecoration(
                labelText: label,
                hintText: hint,
                filled: true,
                fillColor: fill,
                border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide(color: border)),
                enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide(color: border)),
              );
          return Dialog(
            backgroundColor: Colors.transparent,
            insetPadding: const EdgeInsets.all(16),
            child: Container(
              constraints: const BoxConstraints(maxWidth: 640),
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(
                color: panelBg,
                borderRadius: BorderRadius.circular(18),
                border: Border.all(color: border),
              ),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text('Professional Worker Application', style: TextStyle(fontWeight: FontWeight.w800, fontSize: 18)),
                    const SizedBox(height: 12),
                    TextField(controller: fullNameC, decoration: dec('Full Name *')),
                    const SizedBox(height: 10),
                    TextField(controller: phoneC, keyboardType: TextInputType.phone, decoration: dec('Phone Number *')),
                    const SizedBox(height: 10),
                    TextField(controller: cityC, decoration: dec('City / State')),
                    const SizedBox(height: 10),
                    Row(
                      children: [
                        Expanded(child: TextField(controller: yearsC, keyboardType: TextInputType.number, decoration: dec('Years of Experience'))),
                        const SizedBox(width: 10),
                        Expanded(
                          child: DropdownButtonFormField<String>(
                            initialValue: availability,
                            decoration: dec('Availability'),
                            items: const [
                              DropdownMenuItem(value: 'Full-time', child: Text('Full-time')),
                              DropdownMenuItem(value: 'Part-time', child: Text('Part-time')),
                              DropdownMenuItem(value: 'Weekends', child: Text('Weekends')),
                              DropdownMenuItem(value: 'Flexible', child: Text('Flexible')),
                            ],
                            onChanged: (v) => setDialog(() => availability = v ?? 'Flexible'),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    TextField(controller: skillsC, maxLines: 2, decoration: dec('Skills *', hint: 'e.g., electrical, plumbing, painting')),
                    const SizedBox(height: 10),
                    TextField(controller: roleC, decoration: dec('Preferred Role *', hint: 'e.g., Electrician')),
                    const SizedBox(height: 10),
                    TextField(controller: portfolioC, decoration: dec('Portfolio Link (optional)')),
                    const SizedBox(height: 10),
                    TextField(controller: noteC, maxLines: 3, decoration: dec('Why should we approve you? *')),
                    const SizedBox(height: 14),
                    Row(
                      children: [
                        Expanded(child: TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel'))),
                        const SizedBox(width: 10),
                        Expanded(
                          child: ElevatedButton(
                            onPressed: () {
                              if (fullNameC.text.trim().isEmpty || phoneC.text.trim().isEmpty || skillsC.text.trim().isEmpty || roleC.text.trim().isEmpty || noteC.text.trim().isEmpty) {
                                ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Please fill all required fields.')));
                                return;
                              }
                              widget.config.jobWorkerApplications.add({
                                'id': DateTime.now().microsecondsSinceEpoch.toString(),
                                'userEmail': widget.user.email,
                                'username': widget.user.username,
                                'fullName': fullNameC.text.trim(),
                                'phone': phoneC.text.trim(),
                                'city': cityC.text.trim(),
                                'yearsExperience': yearsC.text.trim(),
                                'availability': availability,
                                'skills': skillsC.text.trim(),
                                'preferredRole': roleC.text.trim(),
                                'portfolio': portfolioC.text.trim(),
                                'note': noteC.text.trim(),
                                'status': 'pending',
                                'createdAt': DateTime.now().toIso8601String(),
                              });
                              _saveJobs();
                              Navigator.pop(ctx);
                              ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Application sent to admin for review.')));
                            },
                            child: const Text('Submit Application'),
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      ),
    );
  }

  void _claimJob(Map<String, dynamic> job) {
    if (!_isApprovedWorker) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Only admin-approved workers can claim jobs.')));
      return;
    }
    if ((job['status'] ?? 'open') != 'open') return;
    job['status'] = 'claimed';
    job['claimedByEmail'] = widget.user.email;
    job['claimedByName'] = widget.user.username;
    job['claimedAt'] = DateTime.now().toIso8601String();
    if ((job['agreedPrice'] ?? 0) == 0) job['agreedPrice'] = (job['budget'] ?? 0);
    _saveJobs();
  }

  Future<void> _showOfferDialog(Map<String, dynamic> job) async {
    final amountC = TextEditingController(text: '${(job['budget'] ?? 0)}');
    final noteC = TextEditingController();
    await showDialog(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Send Offer'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            TextField(controller: amountC, keyboardType: const TextInputType.numberWithOptions(decimal: true), decoration: const InputDecoration(labelText: 'Your offer amount (\$)')),
            TextField(controller: noteC, maxLines: 3, decoration: const InputDecoration(labelText: 'Message')),
          ],
        ),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
          ElevatedButton(
            onPressed: () {
              final amount = double.tryParse(amountC.text.trim()) ?? 0;
              if (amount <= 0) {
                ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Enter a valid offer amount.')));
                return;
              }
              final offers = List<Map<String, dynamic>>.from((job['offers'] ?? const []).map((e) => Map<String, dynamic>.from(e)));
              offers.add({
                'id': DateTime.now().microsecondsSinceEpoch.toString(),
                'workerEmail': widget.user.email,
                'workerName': widget.user.username,
                'amount': amount,
                'message': noteC.text.trim(),
                'status': 'pending',
                'createdAt': DateTime.now().toIso8601String(),
              });
              job['offers'] = offers;
              _saveJobs();
              Navigator.pop(ctx);
            },
            child: const Text('Send Offer'),
          ),
        ],
      ),
    );
  }

  void _showOffersManager(Map<String, dynamic> job) {
    final offers = List<Map<String, dynamic>>.from((job['offers'] ?? const []).map((e) => Map<String, dynamic>.from(e)));
    showDialog(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialog) => AlertDialog(
          title: const Text('Job Offers'),
          content: SizedBox(
            width: 520,
            child: offers.isEmpty
                ? const Text('No offers yet.')
                : ListView.separated(
                    shrinkWrap: true,
                    itemBuilder: (context, i) {
                      final o = offers[i];
                      final status = (o['status'] ?? 'pending').toString();
                      return ListTile(
                        contentPadding: EdgeInsets.zero,
                        title: Text('${o['workerName'] ?? 'Worker'} • \$${formatCurrency((o['amount'] ?? 0).toDouble())}'),
                        subtitle: Text('${o['message'] ?? ''}\n$status'.trim()),
                        isThreeLine: true,
                        trailing: status == 'pending'
                            ? Wrap(
                                spacing: 6,
                                children: [
                                  IconButton(
                                    onPressed: () {
                                      for (final each in offers) {
                                        each['status'] = each['id'] == o['id'] ? 'accepted' : (each['status'] == 'pending' ? 'rejected' : each['status']);
                                      }
                                      job['offers'] = offers;
                                      job['status'] = 'claimed';
                                      job['claimedByEmail'] = o['workerEmail'];
                                      job['claimedByName'] = o['workerName'];
                                      job['agreedPrice'] = o['amount'];
                                      job['claimedAt'] = DateTime.now().toIso8601String();
                                      _saveJobs();
                                      setDialog(() {});
                                    },
                                    icon: const Icon(Icons.check_circle, color: Colors.green),
                                  ),
                                  IconButton(
                                    onPressed: () {
                                      o['status'] = 'rejected';
                                      job['offers'] = offers;
                                      _saveJobs();
                                      setDialog(() {});
                                    },
                                    icon: const Icon(Icons.cancel, color: Colors.red),
                                  ),
                                ],
                              )
                            : Text(status.toUpperCase()),
                      );
                    },
                    separatorBuilder: (_, __) => const Divider(),
                    itemCount: offers.length,
                  ),
          ),
          actions: [TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Close'))],
        ),
      ),
    );
  }

  void _markDone(Map<String, dynamic> job) {
    job['status'] = 'done';
    job['completedAt'] = DateTime.now().toIso8601String();
    _saveJobs();
  }

  Widget _workerApplicationCard(Map<String, dynamic> app, {required bool isDark, required bool adminView}) {
    final status = (app['status'] ?? 'pending').toString();
    final accent = _appStatusColor(status);
    final createdAt = (app['createdAt'] ?? '').toString();
    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: isDark ? const Color(0xFF141A24) : const Color(0xFFF8FAFC),
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: accent.withOpacity(0.35)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  (app['fullName'] ?? app['username'] ?? 'Applicant').toString(),
                  style: const TextStyle(fontWeight: FontWeight.w800, fontSize: 15),
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                decoration: BoxDecoration(color: accent.withOpacity(0.12), borderRadius: BorderRadius.circular(8)),
                child: Text(_appStatusLabel(status), style: TextStyle(color: accent, fontWeight: FontWeight.w700, fontSize: 10)),
              ),
            ],
          ),
          const SizedBox(height: 6),
          Text('Email: ${(app['userEmail'] ?? '').toString()}'),
          Text('Phone: ${(app['phone'] ?? '').toString()}'),
          if ((app['city'] ?? '').toString().trim().isNotEmpty) Text('Location: ${(app['city'] ?? '').toString()}'),
          if ((app['preferredRole'] ?? '').toString().trim().isNotEmpty) Text('Role: ${(app['preferredRole'] ?? '').toString()}'),
          if ((app['skills'] ?? '').toString().trim().isNotEmpty) Text('Skills: ${(app['skills'] ?? '').toString()}'),
          if ((app['availability'] ?? '').toString().trim().isNotEmpty) Text('Availability: ${(app['availability'] ?? '').toString()}'),
          if ((app['note'] ?? '').toString().trim().isNotEmpty) Text('Statement: ${(app['note'] ?? '').toString()}'),
          if (createdAt.isNotEmpty)
            Text(
              'Submitted: ${_safeDate(createdAt)}',
              style: TextStyle(fontSize: 11, color: isDark ? Colors.white60 : Colors.black54),
            ),
          if (adminView && status == 'pending') ...[
            const SizedBox(height: 10),
            Row(
              children: [
                Expanded(
                  child: OutlinedButton.icon(
                    onPressed: () => _processWorkerApplication(app, approve: false),
                    icon: const Icon(Icons.close_rounded, size: 16),
                    label: const Text('Reject'),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: ElevatedButton.icon(
                    onPressed: () => _processWorkerApplication(app, approve: true),
                    icon: const Icon(Icons.check_rounded, size: 16),
                    label: const Text('Approve'),
                  ),
                ),
              ],
            ),
          ],
        ],
      ),
    );
  }

  String _safeDate(String raw) {
    try {
      final d = DateTime.parse(raw).toLocal();
      return '${d.month}/${d.day}/${d.year} ${d.hour}:${d.minute.toString().padLeft(2, '0')}';
    } catch (_) {
      return raw;
    }
  }

  Widget _jobCard(Map<String, dynamic> job, {required bool isDark, bool showOwnerManage = false}) {
    final ownerEmail = (job['ownerEmail'] ?? '').toString().toLowerCase().trim();
    final status = (job['status'] ?? 'open').toString();
    final mine = ownerEmail == widget.user.email.toLowerCase().trim();
    final claimedByMe = (job['claimedByEmail'] ?? '').toString().toLowerCase().trim() == widget.user.email.toLowerCase().trim();
    final image = _jobImage(job['imageRef']?.toString());
    final canClaim = !mine && status == 'open' && _isApprovedWorker;
    final canOffer = !mine && status == 'open';
    final canManageOffers = mine && status == 'open';
    final canDone = status == 'claimed' && (mine || claimedByMe);
    final offers = List<Map<String, dynamic>>.from((job['offers'] ?? const []).map((e) => Map<String, dynamic>.from(e)));
    final category = (job['category'] ?? 'General Service').toString();
    final workType = (job['workType'] ?? 'On-site').toString();
    final urgency = (job['urgency'] ?? 'Normal').toString();
    final statusColor = status == 'open'
        ? Colors.blue
        : status == 'claimed'
            ? Colors.orange
            : Colors.green;
    final urgencyColor = urgency == 'Urgent'
        ? Colors.red
        : urgency == 'Low'
            ? Colors.green
            : Colors.amber.shade700;

    return Card(
      elevation: 0,
      color: isDark ? const Color(0xFF161B22) : Colors.white,
      margin: const EdgeInsets.only(bottom: 12),
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(16),
        side: BorderSide(color: statusColor.withOpacity(0.2)),
      ),
      child: Padding(
        padding: const EdgeInsets.all(14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            if (image != null)
              Container(
                height: 150,
                width: double.infinity,
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(10),
                  image: DecorationImage(image: image, fit: BoxFit.cover),
                ),
              ),
            if (image != null) const SizedBox(height: 10),
            Row(
              children: [
                Expanded(
                  child: Text(
                    (job['title'] ?? 'Untitled Job').toString(),
                    style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 16),
                  ),
                ),
                if (showOwnerManage && mine && status == 'open') ...[
                  IconButton(
                    tooltip: 'Edit job',
                    visualDensity: VisualDensity.compact,
                    icon: const Icon(Icons.edit_outlined, size: 20),
                    onPressed: () => _showPostJobDialog(editJob: job),
                  ),
                  IconButton(
                    tooltip: 'Delete job',
                    visualDensity: VisualDensity.compact,
                    icon: const Icon(Icons.delete_outline, size: 20, color: Colors.red),
                    onPressed: () => _confirmDeleteJob(job),
                  ),
                ],
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                  decoration: BoxDecoration(
                    color: statusColor.withOpacity(0.12),
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Text(status.toUpperCase(), style: TextStyle(fontWeight: FontWeight.bold, fontSize: 10, color: statusColor)),
                ),
              ],
            ),
            const SizedBox(height: 6),
            Text((job['description'] ?? '').toString()),
            const SizedBox(height: 8),
            Wrap(
              spacing: 6,
              runSpacing: 6,
              children: [
                _chip(category, Colors.deepPurple),
                _chip(workType, Colors.teal),
                _chip(urgency, urgencyColor),
              ],
            ),
            const SizedBox(height: 8),
            Text('Budget: \$${formatCurrency((job['agreedPrice'] ?? job['budget'] ?? 0).toDouble())}', style: const TextStyle(fontWeight: FontWeight.bold)),
            Text('Contact: ${(job['contact'] ?? '').toString()}'),
            Text('When: ${(job['preferredTime'] ?? '').toString()}'),
            Text('Address: ${(job['address'] ?? '').toString()}'),
            Text('Posted by: ${(job['ownerName'] ?? '').toString()}'),
            if ((job['claimedByName'] ?? '').toString().isNotEmpty) Text('Claimed by: ${(job['claimedByName'] ?? '').toString()}'),
            const SizedBox(height: 8),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [
                if (canClaim)
                  ElevatedButton.icon(
                    onPressed: () => _claimJob(job),
                    icon: const Icon(Icons.how_to_reg, size: 14),
                    label: const Text('Claim'),
                  ),
                if (canOffer)
                  OutlinedButton.icon(
                    onPressed: () => _showOfferDialog(job),
                    icon: const Icon(Icons.local_offer_outlined, size: 14),
                    label: const Text('Send Offer'),
                  ),
                if (canManageOffers)
                  OutlinedButton.icon(
                    onPressed: () => _showOffersManager(job),
                    icon: const Icon(Icons.inbox_outlined, size: 14),
                    label: Text('Offers (${offers.where((e) => (e['status'] ?? 'pending') == 'pending').length})'),
                  ),
                if (canDone)
                  ElevatedButton.icon(
                    onPressed: () => _markDone(job),
                    icon: const Icon(Icons.task_alt, size: 14),
                    label: const Text('Mark Done'),
                  ),
              ],
            ),
          ],
        ),
      ),
    );
  }

  Widget _chip(String label, Color color) {
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: color.withOpacity(0.12),
        borderRadius: BorderRadius.circular(8),
      ),
      child: Text(label, style: TextStyle(fontSize: 11, fontWeight: FontWeight.w700, color: color)),
    );
  }

  @override
  Widget build(BuildContext context) {
    bool isDark = Theme.of(context).brightness == Brightness.dark;
    final myEmail = widget.user.email.toLowerCase().trim();
    final allJobs = List<Map<String, dynamic>>.from(_jobs)..sort((a, b) => (b['createdAt'] ?? '').toString().compareTo((a['createdAt'] ?? '').toString()));
    final findJobs = allJobs.where((j) => (j['status'] ?? 'open') == 'open').toList();
    final claimedJobs = allJobs.where((j) => (j['status'] ?? '') == 'claimed' && (((j['claimedByEmail'] ?? '').toString().toLowerCase().trim() == myEmail) || ((j['ownerEmail'] ?? '').toString().toLowerCase().trim() == myEmail))).toList();
    final myJobs = allJobs.where((j) {
      final owner = (j['ownerEmail'] ?? '').toString().toLowerCase().trim();
      final claimed = (j['claimedByEmail'] ?? '').toString().toLowerCase().trim();
      final status = (j['status'] ?? '').toString();
      if (owner == myEmail) return true;
      return status == 'done' && claimed == myEmail;
    }).toList();
    final tabJobs = _activeTab == 0 ? findJobs : (_activeTab == 1 ? myJobs : claimedJobs);

    return NgmyTabBackScope(
      activeTab: _activeTab,
      onTabBack: () => setState(() => _activeTab = (_activeTab - 1).clamp(0, 2)),
      child: Scaffold(
      backgroundColor: isDark ? const Color(0xFF0A0A0A) : const Color(0xFFF5F7FB),
      appBar: AppBar(
        leading: IconButton(
          icon: const Icon(Icons.arrow_back_ios_new_rounded),
          onPressed: () => NgmyNavigator.pop(context),
        ),
        title: const Text('Job Marketplace', style: TextStyle(fontWeight: FontWeight.bold)),
        centerTitle: true,
        backgroundColor: Colors.transparent,
        elevation: 0,
      ),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(20),
        child: Column(
          children: [
            // Top Header Card
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(25),
              decoration: BoxDecoration(
                gradient: const LinearGradient(
                  colors: [Color(0xFFFF5722), Color(0xFFE64A19)],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
                borderRadius: BorderRadius.circular(25),
                boxShadow: [BoxShadow(color: const Color(0xFFFF5722).withOpacity(0.3), blurRadius: 15, offset: const Offset(0, 8))],
              ),
              child: Row(
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text('Job Marketplace', style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 24)),
                        Text('Find work, post jobs, and hire with confidence', style: TextStyle(color: Colors.white.withOpacity(0.88), fontSize: 13)),
                      ],
                    ),
                  ),
                  Column(
                    children: [
                      _actionButton(Icons.person_add_alt_1_rounded, 'Apply', _showWorkerApplicationDialog),
                      const SizedBox(height: 10),
                      _actionButton(Icons.business_center_rounded, 'Post', _showPostJobDialog),
                    ],
                  ),
                ],
              ),
            ),
            const SizedBox(height: 25),

            // Tabs Bar
            Container(
              height: 55,
              padding: const EdgeInsets.all(5),
              decoration: BoxDecoration(
                color: isDark ? const Color(0xFF1E1E1E) : Colors.white,
                borderRadius: BorderRadius.circular(15),
                boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.03), blurRadius: 10)],
              ),
              child: Row(
                children: [
                  Expanded(child: _tabButton(0, 'Find Jobs')),
                  Expanded(child: _tabButton(1, 'My Jobs')),
                  Expanded(child: _tabButton(2, 'Claimed')),
                ],
              ),
            ),
            const SizedBox(height: 25),

            // Content Area
            Container(
              width: double.infinity,
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: isDark ? const Color(0xFF1E1E1E) : Colors.white,
                borderRadius: BorderRadius.circular(25),
                boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.03), blurRadius: 15)],
              ),
              child: tabJobs.isEmpty
                  ? Padding(
                      padding: const EdgeInsets.symmetric(vertical: 60),
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          Icon(Icons.business_center_outlined, size: 60, color: Colors.grey.shade400),
                          const SizedBox(height: 15),
                          Text('No jobs available', style: TextStyle(color: Colors.grey.shade500, fontWeight: FontWeight.w500, fontSize: 14)),
                        ],
                      ),
                    )
                  : Column(children: tabJobs.map((j) => _jobCard(j, isDark: isDark, showOwnerManage: _activeTab == 1)).toList()),
            ),
            const SizedBox(height: 50),
          ],
        ),
      ),
    ),
    );
  }

  Widget _actionButton(IconData icon, String label, VoidCallback onTap) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(10),
      child: Container(
      width: 90,
      height: 38,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(10),
        boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.05), blurRadius: 5)],
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(icon, size: 16, color: const Color(0xFFE64A19)),
          const SizedBox(width: 8),
          Text(label, style: const TextStyle(color: Color(0xFFE64A19), fontWeight: FontWeight.bold, fontSize: 11)),
        ],
      ),
      ),
    );
  }

  Widget _tabButton(int index, String label) {
    bool isSelected = _activeTab == index;
    return GestureDetector(
      onTap: () => setState(() => _activeTab = index),
      child: Container(
        alignment: Alignment.center,
        decoration: BoxDecoration(
          gradient: isSelected
              ? const LinearGradient(colors: [Color(0xFFFF5722), Color(0xFFE64A19)])
              : null,
          borderRadius: BorderRadius.circular(12),
        ),
        child: Text(
          label,
          style: TextStyle(
            color: isSelected ? Colors.white : Colors.grey.shade600,
            fontWeight: FontWeight.bold,
            fontSize: 12,
          ),
        ),
      ),
    );
  }
}

class MediaHubScreen extends StatefulWidget {
  final UserData user;
  final List<UserData> allUsers;
  final List<MediaPost> allMedia;
  final AppConfig config;
  final Function(MediaPost) onPost;
  final VoidCallback onDataChanged;
  final Function(AppTransaction) onAddTransaction;
  final Future<void> Function()? onRefreshFromCloud;
  final Future<void> Function(MediaPost)? onDeleteMedia;
  final Future<void> Function(MediaPost)? onPruneMedia;

  const MediaHubScreen({
    super.key,
    required this.user,
    required this.allUsers,
    required this.allMedia,
    required this.config,
    required this.onPost,
    required this.onDataChanged,
    required this.onAddTransaction,
    this.onRefreshFromCloud,
    this.onDeleteMedia,
    this.onPruneMedia,
  });

  @override
  State<MediaHubScreen> createState() => _MediaHubScreenState();
}

class _MediaHubScreenState extends State<MediaHubScreen> {
  final _captionController = TextEditingController();
  bool _isPosting = false;
  OverlayEntry? _noticeEntry;
  Timer? _mediaSyncTimer;
  String _lastFeedSig = '';

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      await _cleanupExpiredPosts();
      await _silentRefreshFeed();
    });
    _mediaSyncTimer = Timer.periodic(const Duration(seconds: 30), (_) => _silentRefreshFeed());
  }

  String _feedSignature() {
    final feed = widget.allMedia.where((m) => !_isExpired(m)).map((m) => m.id).join('|');
    return feed;
  }

  Future<void> _silentRefreshFeed() async {
    if (!mounted || _isPosting) return;
    if (!await ngmyCanReachCloud()) return;
    await widget.onRefreshFromCloud?.call();
    if (!mounted || _isPosting) return;
    final sig = _feedSignature();
    if (sig == _lastFeedSig) return;
    _lastFeedSig = sig;
    setState(() {});
  }

  bool _isExpired(MediaPost post) {
    return DateTime.now().difference(post.timestamp).inDays >= 7;
  }

  ({String bucket, String path})? _parseSupabaseRef(String mediaUrl) {
    if (!mediaUrl.startsWith('supabase://')) return null;
    final withoutScheme = mediaUrl.replaceFirst('supabase://', '');
    final slashIdx = withoutScheme.indexOf('/');
    if (slashIdx <= 0 || slashIdx >= withoutScheme.length - 1) return null;
    return (bucket: withoutScheme.substring(0, slashIdx), path: withoutScheme.substring(slashIdx + 1));
  }

  Future<void> _deletePostFromStorage(MediaPost post) async {
    final ref = _parseSupabaseRef(post.videoUrl);
    if (ref == null) return;
    try {
      await Supabase.instance.client.storage.from(ref.bucket).remove([ref.path]);
    } catch (e) {
      debugPrint('Storage remove warning: $e');
    }
  }

  Future<void> _deletePostSilently(MediaPost post) async {
    if (widget.onDeleteMedia != null) {
      await widget.onDeleteMedia!(post);
      return;
    }
    await _deleteMediaRowFromSupabase(post.id);
    await _deletePostFromStorage(post);
    widget.allMedia.removeWhere((m) => m.id == post.id);
  }

  Future<void> _deletePost(MediaPost post, {bool triggerSave = true}) async {
    final owner = post.userEmail.toLowerCase().trim() == widget.user.email.toLowerCase().trim();
    if (!owner && !widget.user.isAdmin) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('You can only delete your own posts.')),
        );
      }
      return;
    }
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Delete post?'),
        content: const Text('This removes the photo or video for everyone. This cannot be undone.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
          ElevatedButton(
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red, foregroundColor: Colors.white),
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('Delete'),
          ),
        ],
      ),
    );
    if (confirmed != true || !mounted) return;

    if (widget.onDeleteMedia != null) {
      await widget.onDeleteMedia!(post);
      if (mounted) {
        setState(() {});
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Post deleted for everyone.')),
        );
      }
      widget.onDataChanged();
      return;
    }
    await _deleteMediaRowFromSupabase(post.id);
    await _deletePostFromStorage(post);
    if (mounted) {
      setState(() => widget.allMedia.removeWhere((m) => m.id == post.id));
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Post deleted for everyone.')),
      );
    } else {
      widget.allMedia.removeWhere((m) => m.id == post.id);
    }
    if (triggerSave) widget.onDataChanged();
  }

  Future<void> _cleanupExpiredPosts() async {
    final expired = widget.allMedia.where(_isExpired).toList();
    if (expired.isEmpty) return;
    for (final post in expired) {
      await _deletePostSilently(post);
    }
    if (mounted) setState(() {});
    widget.onDataChanged();
  }

  int _weeklyPostsForCurrentUser() {
    final weekAgo = DateTime.now().subtract(const Duration(days: 7));
    return widget.allMedia.where((m) {
      final sameUser = m.userEmail.toLowerCase().trim() == widget.user.email.toLowerCase().trim();
      return sameUser && m.timestamp.isAfter(weekAgo);
    }).length;
  }

  void _showGlassNotice(String title, String body, {bool isError = false}) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        backgroundColor: Colors.transparent,
        elevation: 0,
        content: Container(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
          decoration: BoxDecoration(
            color: isError ? const Color(0xFFEF4444) : const Color(0xFF7C3AED),
            borderRadius: BorderRadius.circular(16),
            boxShadow: [
              BoxShadow(color: Colors.black.withOpacity(0.2), blurRadius: 10, offset: const Offset(0, 4)),
            ],
          ),
          child: Row(
            children: [
              Icon(isError ? Icons.error_outline_rounded : Icons.check_circle_outline_rounded, color: Colors.white),
              const SizedBox(width: 12),
              Expanded(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(title, style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 14)),
                    Text(body, style: const TextStyle(color: Colors.white70, fontSize: 12)),
                  ],
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  List<String> _resolveTaggedEmails(String raw) {
    final out = <String>[];
    for (final part in raw.split(RegExp(r'[,\s]+'))) {
      final token = part.trim().replaceAll('@', '');
      if (token.isEmpty) continue;
      for (final u in widget.allUsers) {
        if (u.username.toLowerCase() == token.toLowerCase() || u.email.toLowerCase() == token.toLowerCase()) {
          out.add(u.email);
          break;
        }
      }
    }
    return out;
  }

  Future<bool> _payoutWatchReward(MediaPost post) async {
    final mon = post.monetization;
    if (!mon.hasWatchReward || mon.hasClaimed(widget.user.email)) return false;
    final creatorEmail = post.userEmail.toLowerCase().trim();
    final viewerEmail = widget.user.email.toLowerCase().trim();
    if (creatorEmail == viewerEmail) return false;

    final creatorIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == creatorEmail);
    final viewerIdx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == viewerEmail);
    if (creatorIdx < 0 || viewerIdx < 0) return false;
    if (widget.allUsers[creatorIdx].accountBalance + 0.001 < mon.watchReward) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Creator does not have enough balance for this reward right now.')),
        );
      }
      return false;
    }

    widget.allUsers[creatorIdx].accountBalance -= mon.watchReward;
    widget.allUsers[viewerIdx].accountBalance += mon.watchReward;
    if (!post.rewardedViewers.contains(viewerEmail)) {
      post.rewardedViewers.add(viewerEmail);
    }

    final ts = DateTime.now().microsecondsSinceEpoch.toString();
    widget.onAddTransaction(AppTransaction(
      id: 'media_reward_$ts',
      userEmail: viewerEmail,
      amount: mon.watchReward,
      type: TransactionType.adminAdd,
      method: PaymentMethod.system,
      status: TransactionStatus.approved,
      timestamp: DateTime.now(),
      sourceDetails: 'Media watch reward: ${post.caption.isNotEmpty ? post.caption : post.id}',
    ));
    widget.onAddTransaction(AppTransaction(
      id: 'media_reward_pay_$ts',
      userEmail: creatorEmail,
      amount: mon.watchReward,
      type: TransactionType.adminRemove,
      method: PaymentMethod.system,
      status: TransactionStatus.approved,
      timestamp: DateTime.now(),
      sourceDetails: 'Paid watch reward on media post',
    ));

    await _upsertMediaRowSafe(Map<String, dynamic>.from(post.toJson()));
    widget.onDataChanged();
    await NgmyMediaRewardTracker.clearSession(post.id, viewerEmail);
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('You earned \$${formatCurrency(mon.watchReward)} for watching!')),
      );
    }
    return true;
  }

  Future<void> _pickAndPost({required bool isVideo, String tagRaw = '', NgmyMediaMonetization monetization = const NgmyMediaMonetization()}) async {
    if (_isPosting) return;
    final limit = widget.config.maxMediaPostsPerWeek;
    if (_weeklyPostsForCurrentUser() >= limit) {
      if (mounted) {
        _showGlassNotice('Limit Reached', 'You can only upload $limit posts every 7 days.', isError: true);
      }
      return;
    }

    final picker = ImagePicker();
    XFile? media;
    try {
      await Future<void>.delayed(Duration.zero);
      media = isVideo
          ? await picker.pickVideo(source: ImageSource.gallery)
          : await picker.pickImage(
              source: ImageSource.gallery,
              imageQuality: 85,
            );
    } catch (e) {
      debugPrint('[media] picker error: $e');
      if (mounted) {
        _showGlassNotice('Picker failed', 'Could not open your gallery. Try again.', isError: true);
      }
      return;
    }
    if (media == null || !mounted) return;

    setState(() => _isPosting = true);
    try {
      final fallbackExt = isVideo ? 'mp4' : 'jpg';
      var ext = fallbackExt;
      if (media.mimeType != null && media.mimeType!.contains('/')) {
        final mimeExt = media.mimeType!.split('/').last.toLowerCase();
        if (mimeExt.isNotEmpty && mimeExt.length <= 5) ext = mimeExt == 'jpeg' ? 'jpg' : mimeExt;
      } else if (media.path.contains('.')) {
        ext = media.path.split('.').last.toLowerCase();
      }

      final maxBytes = isVideo
          ? (kIsWeb ? 120 * 1024 * 1024 : 280 * 1024 * 1024)
          : (kIsWeb ? 12 * 1024 * 1024 : 16 * 1024 * 1024);

      Uint8List bytes;
      try {
        bytes = await _readMediaPickerBytes(media);
      } catch (e) {
        debugPrint('[media] read bytes error: $e');
        if (mounted) {
          _showGlassNotice('File read failed', 'Could not read that file. Try a smaller photo or video.', isError: true);
        }
        return;
      }

      if (bytes.length > maxBytes) {
        if (mounted) {
          _showGlassNotice(
            'File too large',
            isVideo
                ? (kIsWeb ? 'Video must be under 120 MB on web (about 5+ min).' : 'Video must be under 280 MB.')
                : (kIsWeb ? 'Photo must be under 12 MB on web.' : 'Photo must be under 16 MB.'),
            isError: true,
          );
        }
        return;
      }

      double? aspectRatio;
      if (!isVideo) {
        aspectRatio = await _aspectRatioFromImageBytes(bytes);
      }

      final fileName = '${DateTime.now().microsecondsSinceEpoch}_${widget.user.email.hashCode.abs()}.$ext';
      final storagePath = 'uploads/$fileName';
      final contentType = isVideo ? _mimeForVideoExt(ext) : _mimeForImageExt(ext);

      final upload = await _uploadNgmyMediaBytes(
        bytes: bytes,
        storagePath: storagePath,
        contentType: contentType,
      );

      if (upload.ref == null) {
        if (mounted) {
          _showGlassNotice('Upload failed', upload.error ?? 'Could not upload to cloud.', isError: true);
        }
        return;
      }

      if (monetization.hasWatchReward && widget.user.accountBalance < monetization.watchReward) {
        if (mounted) {
          _showGlassNotice(
            'Insufficient balance',
            'You need at least \$${formatCurrency(monetization.watchReward)} in your account to offer this reward per viewer.',
            isError: true,
          );
        }
        return;
      }

      final post = MediaPost(
        id: DateTime.now().millisecondsSinceEpoch.toString(),
        userEmail: widget.user.email,
        username: _mediaAuthorName(widget.user),
        videoUrl: upload.ref!,
        contentType: isVideo ? 'video' : 'image',
        caption: _captionController.text.trim(),
        timestamp: DateTime.now(),
        mediaAspectRatio: aspectRatio,
        taggedUsers: _resolveTaggedEmails(tagRaw),
      );
      post.applyMonetization(monetization);

      final saved = await _upsertMediaRowSafe(Map<String, dynamic>.from(post.toJson()));
      if (!saved && mounted) {
        _showGlassNotice(
          'Sync warning',
          'Uploaded to storage but database sync failed. Run supabase/media_tables.sql if this keeps happening.',
          isError: true,
        );
      }

      widget.onPost(post);
      _captionController.clear();
      _lastFeedSig = _feedSignature();

      if (mounted) {
        _showGlassNotice('Post live!', '${isVideo ? 'Video' : 'Photo'} shared successfully.');
        setState(() {});
      }
      widget.onDataChanged();
    } catch (e, st) {
      debugPrint('Media post error: $e\n$st');
      if (mounted) {
        _showGlassNotice('Post failed', 'Something went wrong. Try a smaller file or check your internet.', isError: true);
      }
    } finally {
      if (mounted) setState(() => _isPosting = false);
    }
  }

  Future<void> _beginPostFlow({required bool isVideo, String tagRaw = '', NgmyMediaMonetization monetization = const NgmyMediaMonetization()}) async {
    if (_isPosting) return;
    await Future<void>.delayed(const Duration(milliseconds: 120));
    if (!mounted) return;
    await _pickAndPost(isVideo: isVideo, tagRaw: tagRaw, monetization: monetization);
  }

  NgmyMediaMonetization _monetizationFromDialog({
    required String link,
    required String previewSec,
    required String continuePrice,
    required String watchReward,
    required String watchSec,
    required bool enableLink,
    required bool enablePreview,
    required bool enablePayContinue,
    required bool enableWatchEarn,
  }) {
    return NgmyMediaMonetization(
      externalLink: enableLink ? link.trim() : '',
      previewSeconds: enablePreview ? (int.tryParse(previewSec.trim()) ?? 0) : 0,
      continuePrice: enablePayContinue ? (double.tryParse(continuePrice.replaceAll(RegExp(r'[^0-9.]'), '')) ?? 0) : 0,
      watchReward: enableWatchEarn ? (double.tryParse(watchReward.replaceAll(RegExp(r'[^0-9.]'), '')) ?? 0) : 0,
      watchRequiredSeconds: enableWatchEarn ? (int.tryParse(watchSec.trim()) ?? 0) : 0,
    );
  }

