class _NgmyFullscreenVideoPage extends StatefulWidget {
  final String url;
  final double aspectRatio;
  const _NgmyFullscreenVideoPage({required this.url, required this.aspectRatio});

  @override
  State<_NgmyFullscreenVideoPage> createState() => _NgmyFullscreenVideoPageState();
}

class _NgmyFullscreenVideoPageState extends State<_NgmyFullscreenVideoPage> {
  VideoPlayerController? _controller;
  bool _ready = false;
  static const _seekStep = Duration(seconds: 10);

  @override
  void initState() {
    super.initState();
    _init();
  }

  Future<void> _seekRelative(Duration delta) async {
    final c = _controller;
    if (c == null || !c.value.isInitialized) return;
    final dur = c.value.duration;
    var target = c.value.position + delta;
    if (target < Duration.zero) target = Duration.zero;
    if (dur.inMilliseconds > 0 && target > dur) target = dur;
    await c.seekTo(target);
    if (mounted) setState(() {});
  }

  Future<void> _init() async {
    try {
      final c = VideoPlayerController.networkUrl(
        Uri.parse(widget.url),
        videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
      );
      await c.initialize();
      c.setLooping(true);
      await c.play();
      if (!mounted) return;
      setState(() {
        _controller = c;
        _ready = true;
      });
    } catch (e) {
      debugPrint('[media] fullscreen video: $e');
    }
  }

  @override
  void dispose() {
    _controller?.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        fit: StackFit.expand,
        children: [
          if (_ready && _controller != null)
            Center(
              child: AspectRatio(
                aspectRatio: _controller!.value.aspectRatio > 0 ? _controller!.value.aspectRatio : widget.aspectRatio,
                child: VideoPlayer(_controller!),
              ),
            )
          else
            const Center(child: CircularProgressIndicator(color: Colors.white)),
          SafeArea(
            child: Align(
              alignment: Alignment.topLeft,
              child: IconButton(
                icon: const Icon(Icons.close_rounded, color: Colors.white, size: 28),
                onPressed: () => Navigator.pop(context),
              ),
            ),
          ),
          if (_ready && _controller != null)
            Align(
              alignment: Alignment.bottomCenter,
              child: Padding(
                padding: const EdgeInsets.only(bottom: 28),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    IconButton(
                      iconSize: 44,
                      color: Colors.white,
                      icon: const Icon(Icons.replay_10_rounded),
                      onPressed: () => _seekRelative(-_seekStep),
                    ),
                    IconButton(
                      iconSize: 56,
                      color: Colors.white,
                      icon: Icon(_controller!.value.isPlaying ? Icons.pause_circle_filled : Icons.play_circle_filled),
                      onPressed: () {
                        setState(() {
                          _controller!.value.isPlaying ? _controller!.pause() : _controller!.play();
                        });
                      },
                    ),
                    IconButton(
                      iconSize: 44,
                      color: Colors.white,
                      icon: const Icon(Icons.forward_10_rounded),
                      onPressed: () => _seekRelative(_seekStep),
                    ),
                  ],
                ),
              ),
            ),
        ],
      ),
    );
  }
}

class _NgmyFullscreenImagePage extends StatelessWidget {
  final String url;
  const _NgmyFullscreenImagePage({required this.url});

  @override
  Widget build(BuildContext context) {
    Widget image;
    if (url.startsWith('data:image')) {
      try {
        image = Image.memory(base64Decode(url.split(',').last), fit: BoxFit.contain);
      } catch (_) {
        image = const Icon(Icons.broken_image_outlined, color: Colors.white54, size: 48);
      }
    } else if (url.startsWith('http')) {
      image = Image.network(url, fit: BoxFit.contain);
    } else if (!kIsWeb) {
      image = Image.file(File(url), fit: BoxFit.contain);
    } else {
      image = const Icon(Icons.image_not_supported_outlined, color: Colors.white54, size: 48);
    }
    return Scaffold(
      backgroundColor: Colors.black,
      body: Stack(
        children: [
          InteractiveViewer(minScale: 0.5, maxScale: 4, child: Center(child: image)),
          SafeArea(
            child: IconButton(
              icon: const Icon(Icons.close_rounded, color: Colors.white, size: 28),
              onPressed: () => Navigator.pop(context),
            ),
          ),
        ],
      ),
    );
  }
}

class VideoPostWidget extends StatefulWidget {
  final MediaPost post;
  final UserData currentUser;
  final List<UserData> allUsers;
  final VoidCallback onChanged;
  final VoidCallback onDelete;
  final void Function(String userEmail)? onOpenProfile;
  final Future<bool> Function(MediaPost post)? onPayoutWatchReward;
  const VideoPostWidget({
    super.key,
    required this.post,
    required this.currentUser,
    required this.allUsers,
    required this.onChanged,
    required this.onDelete,
    this.onOpenProfile,
    this.onPayoutWatchReward,
  });

  @override
  State<VideoPostWidget> createState() => _VideoPostWidgetState();
}

class _VideoPostWidgetState extends State<VideoPostWidget> with WidgetsBindingObserver {
  VideoPlayerController? _controller;
  bool _isInitialized = false;
  bool _hasError = false;
  String _errorText = 'Unable to load media.';
  String? _resolvedMediaUrl;
  ImageProvider? _authorImage;
  bool _loadingMedia = false;
  bool _showHeartBurst = false;
  bool _previewEnded = false;
  bool _unlockedFullVideo = false;

  bool get _isImagePost => _mediaPostIsImage(widget.post);
  NgmyMediaMonetization get _mon => widget.post.monetization;

  Future<void> _initializePlayer(String resolvedUrl) async {
    if (_controller != null) {
      try {
        await _controller!.dispose();
      } catch (_) {}
      _controller = null;
    }
    try {
      if (resolvedUrl.startsWith('http')) {
        _controller = VideoPlayerController.networkUrl(
          Uri.parse(resolvedUrl),
          videoPlayerOptions: VideoPlayerOptions(mixWithOthers: true),
        );
      } else if (!kIsWeb) {
        final file = File(resolvedUrl);
        if (!await file.exists()) throw Exception('File not found at $resolvedUrl');
        _controller = VideoPlayerController.file(file);
      } else {
        throw Exception('Invalid path for web.');
      }

      await _controller!.initialize().timeout(const Duration(seconds: 30));
      if (!mounted) return;
      if (_mon.hasPreviewLimit && !_unlockedFullVideo) {
        _controller!.setLooping(false);
        _controller!.addListener(_onVideoTick);
      } else {
        _controller!.setLooping(true);
      }
      await _controller!.pause();
      final ar = _controller!.value.aspectRatio;
      if (ar > 0) {
        widget.post.mediaAspectRatio = _clampMediaAspectRatio(ar);
        unawaited(_upsertMediaRowSafe(Map<String, dynamic>.from(widget.post.toJson())));
      }
      setState(() {
        _isInitialized = true;
        _hasError = false;
        _loadingMedia = false;
      });
    } catch (e) {
      debugPrint('Media init error ($resolvedUrl): $e');
      if (!mounted) return;
      setState(() {
        _hasError = true;
        _loadingMedia = false;
        _errorText = 'Media loading failed. Check your internet.';
      });
    }
  }

  Future<void> _prepareMedia({bool loadVideo = false}) async {
    if (!mounted) return;
    if (!_isImagePost && !loadVideo) return;

    setState(() {
      _loadingMedia = true;
      _hasError = false;
    });

    try {
      final avatar = await _profileImageProviderForEmail(widget.post.userEmail);
      if (mounted) setState(() => _authorImage = avatar);

      // 1. Try to resolve URL from storage
      final resolved = await _resolveSupabaseStorageUrlResilient(widget.post.videoUrl);
      if (!mounted) return;
      _resolvedMediaUrl = resolved;

      if (_isImagePost) {
        setState(() => _loadingMedia = false);
        return;
      }
      
      // 2. Initialize video player
      await _initializePlayer(resolved);
    } catch (e) {
      debugPrint('Media preparation failed: $e');
      if (mounted) {
        setState(() {
          _hasError = true;
          _loadingMedia = false;
        });
      }
    }
  }

  void _onVideoTick() {
    if (_controller == null || !_isInitialized || _unlockedFullVideo || !_mon.hasPreviewLimit) return;
    final pos = _controller!.value.position;
    if (pos.inSeconds >= _mon.previewSeconds) {
      _controller!.removeListener(_onVideoTick);
      _controller!.pause();
      if (mounted) setState(() => _previewEnded = true);
    }
  }

  static const _videoSeekStep = Duration(seconds: 10);

  Future<void> _seekVideoRelative(Duration delta) async {
    final c = _controller;
    if (c == null || !_isInitialized) return;
    final dur = c.value.duration;
    var target = c.value.position + delta;
    if (target < Duration.zero) target = Duration.zero;
    if (dur.inMilliseconds > 0 && target > dur) target = dur;
    if (_mon.hasPreviewLimit && !_unlockedFullVideo && target.inSeconds > _mon.previewSeconds) {
      target = Duration(seconds: _mon.previewSeconds);
    }
    await c.seekTo(target);
    if (mounted) setState(() {});
  }

  Widget _videoSeekButton({required IconData icon, required VoidCallback onPressed}) {
    return Material(
      color: Colors.black.withValues(alpha: 0.5),
      shape: const CircleBorder(),
      child: InkWell(
        customBorder: const CircleBorder(),
        onTap: onPressed,
        child: Padding(
          padding: const EdgeInsets.all(8),
          child: Icon(icon, color: Colors.white, size: 30),
        ),
      ),
    );
  }

  Widget _inlineVideoSeekControls() {
    return Row(
      mainAxisSize: MainAxisSize.min,
      children: [
        _videoSeekButton(
          icon: Icons.replay_10_rounded,
          onPressed: () => _seekVideoRelative(-_videoSeekStep),
        ),
        const SizedBox(width: 16),
        _videoSeekButton(
          icon: Icons.forward_10_rounded,
          onPressed: () => _seekVideoRelative(_videoSeekStep),
        ),
      ],
    );
  }

  Future<void> _openExternalLink({bool startWatchSession = false}) async {
    final url = _mon.externalLink.trim();
    if (url.isEmpty) return;
    var uri = Uri.tryParse(url);
    if (uri == null) return;
    if (!uri.hasScheme) uri = Uri.parse('https://$url');

    if (startWatchSession && _mon.hasWatchReward && !_isOwner && !_mon.hasClaimed(widget.currentUser.email)) {
      await NgmyMediaRewardTracker.startSession(widget.post.id, widget.currentUser.email);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Stay on the link for ${_mon.watchRequiredSeconds}s, then return here to earn \$${formatCurrency(_mon.watchReward)}.'),
            duration: const Duration(seconds: 5),
          ),
        );
      }
    }

    if (await canLaunchUrl(uri)) {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    }
  }

  Future<void> _payToContinueVideo() async {
    final price = _mon.continuePrice;
    if (price <= 0) return;
    if (widget.currentUser.accountBalance + 0.001 < price) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Need \$${formatCurrency(price)} NGMY balance to continue.')),
        );
      }
      return;
    }
    final idx = widget.allUsers.indexWhere((u) => u.email.toLowerCase().trim() == widget.currentUser.email.toLowerCase().trim());
    if (idx < 0) return;
    final ownerIdx = widget.allUsers.indexWhere(
      (u) => u.email.toLowerCase().trim() == widget.post.userEmail.toLowerCase().trim(),
    );
    setState(() {
      widget.allUsers[idx].accountBalance -= price;
      widget.currentUser.accountBalance -= price;
      if (ownerIdx >= 0 && ownerIdx != idx) {
        widget.allUsers[ownerIdx].accountBalance += price;
      }
      _unlockedFullVideo = true;
      _previewEnded = false;
    });
    _controller?.removeListener(_onVideoTick);
    _controller?.setLooping(true);
    await _controller?.play();
    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Unlocked full video for \$${formatCurrency(price)}.')),
      );
    }
    widget.onChanged();
  }

  Future<void> _tryClaimWatchReward() async {
    if (!_mon.hasWatchReward || _isOwner || _mon.hasClaimed(widget.currentUser.email)) return;
    final elapsed = await NgmyMediaRewardTracker.elapsedSeconds(widget.post.id, widget.currentUser.email);
    if (elapsed == null || elapsed < _mon.watchRequiredSeconds) return;
    await widget.onPayoutWatchReward?.call(widget.post);
  }

  Future<void> _handleLinkAction() async {
    final mon = _mon;
    if (!mon.hasLink) return;
    if (mon.hasWatchReward && !_isOwner && !mon.hasClaimed(widget.currentUser.email)) {
      final ok = await showDialog<bool>(
        context: context,
        builder: (ctx) => AlertDialog(
          title: const Text('Earn by watching'),
          content: Text(
            'Open the link and stay for ${mon.watchRequiredSeconds} seconds. When you return to NGMY you earn \$${formatCurrency(mon.watchReward)}.',
          ),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx, false), child: const Text('Cancel')),
            FilledButton(onPressed: () => Navigator.pop(ctx, true), child: const Text('Open link')),
          ],
        ),
      );
      if (ok != true) return;
      await _openExternalLink(startWatchSession: true);
      return;
    }
    await _openExternalLink();
  }

  Widget _previewPaywallOverlay() {
    final mon = _mon;
    return Container(
      color: Colors.black.withValues(alpha: 0.82),
      padding: const EdgeInsets.all(16),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          const Icon(Icons.lock_clock_rounded, color: Colors.white, size: 40),
          const SizedBox(height: 10),
          Text(
            mon.hasPreviewLimit ? 'Preview ended (${mon.previewSeconds}s)' : 'Continue watching',
            textAlign: TextAlign.center,
            style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w900, fontSize: 16),
          ),
          const SizedBox(height: 8),
          const Text(
            'Open the link or pay to keep watching.',
            textAlign: TextAlign.center,
            style: TextStyle(color: Colors.white70, fontSize: 12),
          ),
          const SizedBox(height: 14),
          if (mon.hasLink)
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                onPressed: () => _handleLinkAction(),
                icon: const Icon(Icons.open_in_new_rounded),
                label: const Text('Open link'),
                style: FilledButton.styleFrom(backgroundColor: const Color(0xFF8B5CF6)),
              ),
            ),
          if (mon.hasPayToContinue) ...[
            const SizedBox(height: 8),
            SizedBox(
              width: double.infinity,
              child: FilledButton.icon(
                onPressed: _payToContinueVideo,
                icon: const Icon(Icons.payments_rounded),
                label: Text('Pay \$${formatCurrency(mon.continuePrice)} to continue'),
                style: FilledButton.styleFrom(backgroundColor: const Color(0xFF00B25A)),
              ),
            ),
          ],
        ],
      ),
    );
  }

  double _effectiveAspectRatio(bool isVideo) {
    if (widget.post.mediaAspectRatio != null && widget.post.mediaAspectRatio! > 0) {
      return _clampMediaAspectRatio(widget.post.mediaAspectRatio!);
    }
    if (isVideo && _isInitialized && _controller != null && _controller!.value.aspectRatio > 0) {
      return _clampMediaAspectRatio(_controller!.value.aspectRatio);
    }
    return 1.0;
  }

  Widget _buildMediaFrame(bool isVideo, bool isImage) {
    final ratio = _effectiveAspectRatio(isVideo);
    final maxH = MediaQuery.of(context).size.height * 0.68;
    return LayoutBuilder(
      builder: (context, constraints) {
        final w = constraints.maxWidth;
        final naturalH = w / ratio;
        final h = naturalH > maxH ? maxH : naturalH;
        return SizedBox(
          width: w,
          height: h.clamp(72.0, maxH),
          child: Stack(
            alignment: Alignment.center,
            children: [
              ClipRRect(
                borderRadius: BorderRadius.circular(16),
                child: Container(
                  color: Colors.black,
                  width: double.infinity,
                  height: double.infinity,
                  child: _loadingMedia
                      ? const Center(child: CircularProgressIndicator())
                      : isVideo
                      ? (_hasError
                          ? Center(
                              child: Padding(
                                padding: const EdgeInsets.all(16),
                                child: Text(_errorText, style: const TextStyle(color: Colors.white70, fontSize: 12), textAlign: TextAlign.center),
                              ),
                            )
                          : (_isInitialized && _controller != null)
                              ? FittedBox(
                                  fit: BoxFit.cover,
                                  clipBehavior: Clip.hardEdge,
                                  child: SizedBox(
                                    width: _controller!.value.size.width,
                                    height: _controller!.value.size.height,
                                    child: VideoPlayer(_controller!),
                                  ),
                                )
                              : const Center(child: CircularProgressIndicator()))
                      : _buildImageContent(),
                ),
              ),
              if (isVideo && _previewEnded && !_unlockedFullVideo) _previewPaywallOverlay(),
              if (isVideo && _isInitialized && _controller != null && !_controller!.value.isPlaying && !_previewEnded)
                Container(
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(color: Colors.black.withOpacity(0.4), shape: BoxShape.circle),
                  child: const Icon(Icons.play_arrow_rounded, color: Colors.white, size: 40),
                ),
              if (isImage && _mon.hasLink)
                Positioned(
                  right: 10,
                  bottom: 10,
                  child: Material(
                    color: const Color(0xFF8B5CF6),
                    borderRadius: BorderRadius.circular(20),
                    child: InkWell(
                      onTap: _handleLinkAction,
                      borderRadius: BorderRadius.circular(20),
                      child: const Padding(
                        padding: EdgeInsets.symmetric(horizontal: 12, vertical: 8),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Icon(Icons.link_rounded, color: Colors.white, size: 18),
                            SizedBox(width: 6),
                            Text('Open link', style: TextStyle(color: Colors.white, fontWeight: FontWeight.w800, fontSize: 12)),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              if (_showHeartBurst)
                TweenAnimationBuilder<double>(
                  tween: Tween(begin: 0.4, end: 1.3),
                  duration: const Duration(milliseconds: 700),
                  curve: Curves.easeOutBack,
                  builder: (context, scale, child) => Opacity(
                    opacity: _showHeartBurst ? (1.0 - (scale - 0.4) / 1.1).clamp(0.0, 1.0) : 0,
                    child: Transform.scale(scale: scale, child: child),
                  ),
                  child: const Icon(Icons.favorite_rounded, color: Color(0xFFFF3B8A), size: 96),
                ),
            ],
          ),
        );
      },
    );
  }

  Widget _buildImageContent() {
    final resolved = _resolvedMediaUrl ?? widget.post.videoUrl;
    if (_hasError) {
      return Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Icon(Icons.broken_image_outlined, color: Colors.white.withOpacity(0.7), size: 42),
            const SizedBox(height: 8),
            Text(_errorText, style: const TextStyle(color: Colors.white70, fontSize: 12), textAlign: TextAlign.center),
          ],
        ),
      );
    }
    if (resolved.startsWith('data:image')) {
      try {
        return Image.memory(base64Decode(resolved.split(',').last), fit: BoxFit.cover, width: double.infinity, height: double.infinity);
      } catch (_) {
        return Center(child: Icon(Icons.broken_image_outlined, color: Colors.white.withOpacity(0.7), size: 42));
      }
    }
    if (resolved.startsWith('http')) {
      return Image.network(
        resolved,
        fit: BoxFit.cover,
        width: double.infinity,
        height: double.infinity,
        gaplessPlayback: true,
        loadingBuilder: (_, child, progress) {
          if (progress == null) return child;
          return const Center(child: CircularProgressIndicator());
        },
        errorBuilder: (_, __, ___) => Center(
          child: Icon(Icons.broken_image_outlined, color: Colors.white.withOpacity(0.7), size: 42),
        ),
      );
    }
    if (!kIsWeb) {
      return Image.file(
        File(resolved),
        fit: BoxFit.cover,
        width: double.infinity,
        height: double.infinity,
        errorBuilder: (_, __, ___) => Center(
          child: Icon(Icons.broken_image_outlined, color: Colors.white.withOpacity(0.7), size: 42),
        ),
      );
    }
    return Center(
      child: Icon(Icons.image_not_supported_outlined, color: Colors.white.withOpacity(0.7), size: 42),
    );
  }

  Future<ImageProvider?> _profileImageProviderForEmail(String email) async {
    final u = widget.allUsers.firstWhere(
      (x) => x.email.toLowerCase().trim() == email.toLowerCase().trim(),
      orElse: () => UserData(email: email),
    );
    final path = u.profilePicturePath;
    if (path == null || path.trim().isEmpty) return null;
    if (path.startsWith('data:image')) {
      try {
        return MemoryImage(base64Decode(path.split(',').last));
      } catch (_) {
        return null;
      }
    }
    if (path.startsWith('http://') || path.startsWith('https://')) {
      return NetworkImage(path);
    }
    if (!kIsWeb) {
      final f = File(path);
      if (await f.exists()) return FileImage(f);
    }
    return null;
  }

  bool get _liked => widget.post.likedBy.contains(widget.currentUser.email);
  bool get _saved => widget.post.savedBy.contains(widget.currentUser.email);
  bool get _isOwner => widget.currentUser.email.toLowerCase().trim() == widget.post.userEmail.toLowerCase().trim();

  String get _displayUsername => _mediaPostDisplayName(widget.post, widget.allUsers);

  Future<void> _persistPostChange() async {
    await _upsertMediaRowSafe(Map<String, dynamic>.from(widget.post.toJson()));
    widget.onChanged();
  }

  Future<void> _toggleLike() async {
    setState(() {
      if (_liked) {
        widget.post.likedBy.remove(widget.currentUser.email);
      } else {
        widget.post.likedBy.add(widget.currentUser.email);
      }
      widget.post.likes = widget.post.likedBy.length;
    });
    await _persistPostChange();
  }

  Future<void> _toggleSave() async {
    setState(() {
      if (_saved) {
        widget.post.savedBy.remove(widget.currentUser.email);
      } else {
        widget.post.savedBy.add(widget.currentUser.email);
      }
    });
    await _persistPostChange();
  }

  Future<void> _sharePost() async {
    final resolved = await _resolveSupabaseStorageUrl(widget.post.videoUrl);
    if (!mounted) return;
    await Clipboard.setData(ClipboardData(text: '${widget.post.caption}\n$resolved'));
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(content: Text('Post link copied to clipboard.')),
    );
  }

  Future<void> _handlePostMenu(String action) async {
    if (action == 'save') {
      await _toggleSave();
      return;
    }
    if (action == 'delete') {
      widget.onDelete();
      return;
    }
  }

  Future<void> _quickLike() async {
    if (!_liked) {
      setState(() {
        widget.post.likedBy.add(widget.currentUser.email);
        widget.post.likes = widget.post.likedBy.length;
      });
      await _persistPostChange();
    }
    _triggerHeartBurst();
  }

  void _triggerHeartBurst() {
    setState(() => _showHeartBurst = true);
    Future.delayed(const Duration(milliseconds: 900), () {
      if (mounted) setState(() => _showHeartBurst = false);
    });
  }

  Future<void> _openFullscreenMedia() async {
    var resolved = _resolvedMediaUrl ?? widget.post.videoUrl;
    if (resolved.startsWith('supabase://')) {
      resolved = await _resolveSupabaseStorageUrlResilient(resolved);
    }
    if (!mounted || resolved.trim().isEmpty) return;
    if (_isImagePost) {
      await Navigator.of(context).push(
        MaterialPageRoute<void>(
          fullscreenDialog: true,
          builder: (_) => _NgmyFullscreenImagePage(url: resolved),
        ),
      );
      return;
    }
    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        fullscreenDialog: true,
        builder: (_) => _NgmyFullscreenVideoPage(
          url: resolved,
          aspectRatio: _effectiveAspectRatio(true),
        ),
      ),
    );
  }

  Widget _commentAvatar(String email, {double radius = 18, String? profilePictureUrl, bool isVirtual = false}) {
    if (isVirtual || email.startsWith('vp_')) {
      final path = (profilePictureUrl ?? '').trim();
      ImageProvider? img;
      if (path.startsWith('data:image')) {
        try {
          img = MemoryImage(base64Decode(path.split(',').last));
        } catch (_) {}
      } else if (path.startsWith('http')) {
        img = NetworkImage(path);
      } else if (path.startsWith('supabase://')) {
        return FutureBuilder<String>(
          future: _resolveSupabaseStorageUrlResilient(path),
          builder: (_, s) {
            final resolved = s.data ?? '';
            if (resolved.startsWith('http')) {
              return CircleAvatar(radius: radius, backgroundImage: NetworkImage(resolved));
            }
            return CircleAvatar(radius: radius, child: Icon(Icons.person, size: radius));
          },
        );
      } else if (!kIsWeb && path.isNotEmpty) {
        img = FileImage(File(path));
      }
      return CircleAvatar(
        radius: radius,
        backgroundImage: img,
        backgroundColor: const Color(0xFF7C3AED).withOpacity(0.25),
        child: img == null ? Icon(Icons.person, size: radius, color: Colors.white70) : null,
      );
    }
    final u = widget.allUsers.firstWhere(
      (x) => x.email.toLowerCase().trim() == email.toLowerCase().trim(),
      orElse: () => UserData(email: email),
    );
    final path = u.profilePicturePath;
    ImageProvider? img;
    if (path != null && path.trim().isNotEmpty) {
      if (path.startsWith('data:image')) {
        try {
          img = MemoryImage(base64Decode(path.split(',').last));
        } catch (_) {}
      } else if (path.startsWith('http')) {
        img = NetworkImage(path);
      } else if (!kIsWeb) {
        img = FileImage(File(path));
      }
    }
    return CircleAvatar(
      radius: radius,
      backgroundImage: img,
      backgroundColor: const Color(0xFF7C3AED).withOpacity(0.25),
      child: img == null ? Icon(Icons.person, size: radius, color: Colors.white70) : null,
    );
  }

  Widget _buildCommentTile(
    Map<String, dynamic> cm, {
    required bool isDark,
    required void Function(String commentId, String username) onReply,
    int depth = 0,
  }) {
    final email = (cm['userEmail'] ?? '').toString();
    final storedName = (cm['username'] ?? 'User').toString();
    final username = storedName.trim().isNotEmpty && storedName.trim() != 'User'
        ? storedName.trim()
        : (email.isNotEmpty
            ? _mediaAuthorName(
                widget.allUsers.firstWhere(
                  (x) => x.email.toLowerCase().trim() == email.toLowerCase().trim(),
                  orElse: () => UserData(email: email),
                ),
              )
            : storedName);
    final text = (cm['text'] ?? '').toString();
    final id = (cm['id'] ?? '').toString();
    final isVirtual = cm['isVirtual'] == true || email.startsWith('vp_');
    final profilePictureUrl = (cm['profilePictureUrl'] ?? '').toString();
    final replies = List<Map<String, dynamic>>.from(
      (cm['replies'] ?? []).map((e) => Map<String, dynamic>.from(e as Map)),
    );
    return Padding(
      padding: EdgeInsets.only(left: depth * 16.0, bottom: 10),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              _commentAvatar(email, radius: depth > 0 ? 14 : 18, profilePictureUrl: profilePictureUrl, isVirtual: isVirtual),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    RichText(
                      text: TextSpan(
                        style: TextStyle(color: isDark ? Colors.white : Colors.black87, fontSize: 13),
                        children: [
                          TextSpan(text: username, style: const TextStyle(fontWeight: FontWeight.w800)),
                          const TextSpan(text: '  '),
                          TextSpan(text: text),
                        ],
                      ),
                    ),
                    if (depth == 0 && id.isNotEmpty)
                      TextButton(
                        style: TextButton.styleFrom(padding: EdgeInsets.zero, minimumSize: Size.zero, tapTargetSize: MaterialTapTargetSize.shrinkWrap),
                        onPressed: () => onReply(id, username),
                        child: Text('Reply', style: TextStyle(color: Colors.grey.shade500, fontSize: 12, fontWeight: FontWeight.w600)),
                      ),
                  ],
                ),
              ),
            ],
          ),
          for (final r in replies)
            _buildCommentTile(r, isDark: isDark, onReply: onReply, depth: depth + 1),
        ],
      ),
    );
  }

  void _openComments() {
    final c = TextEditingController();
    String? replyToId;
    String? replyToName;
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) {
        final isDark = Theme.of(ctx).brightness == Brightness.dark;
        return StatefulBuilder(
          builder: (ctx, setModal) {
            Future<void> submitComment() async {
              final text = c.text.trim();
              if (text.isEmpty) return;
              final node = {
                'id': DateTime.now().microsecondsSinceEpoch.toString(),
                'userEmail': widget.currentUser.email,
                'username': _mediaAuthorName(widget.currentUser),
                'text': text,
                'timestamp': DateTime.now().toUtc().toIso8601String(),
                'replies': <Map<String, dynamic>>[],
              };
              setState(() {
                if (replyToId != null) {
                  final idx = widget.post.comments.indexWhere((x) => (x['id'] ?? '').toString() == replyToId);
                  if (idx != -1) {
                    final parent = Map<String, dynamic>.from(widget.post.comments[idx]);
                    final replies = List<Map<String, dynamic>>.from(
                      (parent['replies'] ?? []).map((e) => Map<String, dynamic>.from(e as Map)),
                    );
                    replies.add(node);
                    parent['replies'] = replies;
                    widget.post.comments[idx] = parent;
                  } else {
                    widget.post.comments.add(node);
                  }
                } else {
                  widget.post.comments.add(node);
                }
              });
              setModal(() {
                replyToId = null;
                replyToName = null;
              });
              c.clear();
              await _persistPostChange();
            }

            return Container(
              height: MediaQuery.of(ctx).size.height * 0.72,
              padding: EdgeInsets.only(
                left: 16,
                right: 16,
                top: 16,
                bottom: MediaQuery.of(ctx).viewInsets.bottom + 16,
              ),
              decoration: BoxDecoration(
                color: isDark ? const Color(0xFF0F152D) : Colors.white,
                borderRadius: const BorderRadius.vertical(top: Radius.circular(24)),
              ),
              child: Column(
                children: [
                  Row(
                    children: [
                      const Expanded(
                        child: Text('Comments', style: TextStyle(fontWeight: FontWeight.w800, fontSize: 17)),
                      ),
                      IconButton(
                        icon: const Icon(Icons.close_rounded),
                        onPressed: () => Navigator.pop(ctx),
                      ),
                    ],
                  ),
                  const SizedBox(height: 6),
                  Expanded(
                    child: widget.post.comments.isEmpty
                        ? const Center(child: Text('No comments yet. Be the first!'))
                        : ListView.builder(
                            itemCount: widget.post.comments.length,
                            itemBuilder: (context, i) {
                              final cm = widget.post.comments[i];
                              return _buildCommentTile(
                                cm,
                                isDark: isDark,
                                onReply: (id, name) {
                                  setModal(() {
                                    replyToId = id;
                                    replyToName = name;
                                  });
                                },
                              );
                            },
                          ),
                  ),
                  if (replyToName != null)
                    Align(
                      alignment: Alignment.centerLeft,
                      child: Padding(
                        padding: const EdgeInsets.only(bottom: 6),
                        child: Text('Replying to $replyToName', style: TextStyle(color: Colors.grey.shade500, fontSize: 12)),
                      ),
                    ),
                  Row(
                    children: [
                      _commentAvatar(widget.currentUser.email, radius: 16),
                      const SizedBox(width: 8),
                      Expanded(
                        child: TextField(
                          controller: c,
                          decoration: InputDecoration(
                            hintText: replyToName != null ? 'Reply to $replyToName...' : 'Write a comment...',
                            filled: true,
                            fillColor: isDark ? Colors.white.withOpacity(0.06) : Colors.grey.shade100,
                            border: OutlineInputBorder(borderRadius: BorderRadius.circular(12), borderSide: BorderSide.none),
                          ),
                          onSubmitted: (_) => submitComment(),
                        ),
                      ),
                      const SizedBox(width: 8),
                      IconButton(onPressed: submitComment, icon: const Icon(Icons.send_rounded)),
                    ],
                  ),
                ],
              ),
            );
          },
        );
      },
    ).whenComplete(c.dispose);
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _prepareMedia(loadVideo: true);
    });
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _controller?.removeListener(_onVideoTick);
    _controller?.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      unawaited(_tryClaimWatchReward());
    }
  }

